import React, { useEffect } from 'react';
import { Tabs, useRouter, useRootNavigationState } from 'expo-router';
import { CalendarDays, Clock3, House, UserRound } from 'lucide-react-native';
import { ActivityIndicator, Animated, Pressable, View, StyleSheet, type GestureResponderEvent } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useAuth } from '../../hooks/useAuth';
import { COLORS } from '../../lib/config';
import { useThemePreference } from '../../hooks/useThemePreference';

interface AnimatedTabBarButtonProps {
  accessibilityState?: { selected?: boolean };
  children?: React.ReactNode;
  onLongPress?: ((event: GestureResponderEvent) => void) | null;
  onPress?: ((event: GestureResponderEvent) => void) | null;
  style?: any;
}

export default function TabLayout() {
  const auth = useAuth();
  const router = useRouter();
  const { isDark } = useThemePreference();
  const insets = useSafeAreaInsets();
  const navigationState = useRootNavigationState();

  // Protect the entire tab group - redirect to login if session lost.
  // We wait for navigationState?.key so that expo-router's internal linking
  // (getInitialURL promise in useLinking.native) has a mounted navigator to
  // update. Without this, you can get:
  //   "Can't perform a React state update on a component that hasn't mounted yet"
  useEffect(() => {
    if (!navigationState?.key) return;

    if (!auth.isLoading && !auth.isAuthenticated) {
      // Use replace to avoid adding to history stack on cold start
      router.replace('/login');
    }
  }, [auth.isLoading, auth.isAuthenticated, router, navigationState?.key]);

  if (auth.isLoading || !auth.isAuthenticated) {
    return (
      <View style={styles.center}>
        <ActivityIndicator size="large" color={COLORS.primary} />
      </View>
    );
  }

  return (
    <Tabs
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: COLORS.primary,
        tabBarInactiveTintColor: isDark ? COLORS.onSurfaceVariantDark : COLORS.onSurfaceVariant,
        tabBarStyle: {
          backgroundColor: isDark ? COLORS.surfaceDark : COLORS.surface,
          borderTopWidth: StyleSheet.hairlineWidth,
          borderTopColor: isDark ? COLORS.outlineDark : COLORS.outline,
          height: 68 + insets.bottom,
          paddingBottom: Math.max(insets.bottom, 8),
          paddingTop: 8,
          shadowColor: '#000000',
          shadowOpacity: isDark ? 0.16 : 0.06,
          shadowOffset: { width: 0, height: -6 },
          shadowRadius: 12,
          elevation: 8,
        },
        tabBarLabelStyle: { fontSize: 11, fontWeight: '700', letterSpacing: 0.2, marginTop: 1 },
        tabBarItemStyle: {
          marginHorizontal: 6,
          marginVertical: 4,
          borderRadius: 18,
          paddingVertical: 2,
        },
        tabBarActiveBackgroundColor: 'transparent',
        tabBarButton: (props) => <AnimatedTabBarButton {...props} />,
        sceneStyle: {
          backgroundColor: isDark ? COLORS.backgroundDark : '#f7f4ef',
        },
      }}
    >
      <Tabs.Screen
        name="index"
        options={{
          title: 'Home',
          tabBarIcon: ({ color }) => <House size={19} color={color} strokeWidth={2.25} />,
        }}
      />
      <Tabs.Screen
        name="attendance"
        options={{
          title: 'Attendance',
          tabBarIcon: ({ color }) => <Clock3 size={19} color={color} strokeWidth={2.25} />,
        }}
      />
      <Tabs.Screen
        name="leave"
        options={{
          title: 'Leave',
          tabBarIcon: ({ color }) => <CalendarDays size={19} color={color} strokeWidth={2.25} />,
        }}
      />
      <Tabs.Screen
        name="profile"
        options={{
          title: 'Info',
          tabBarIcon: ({ color }) => <UserRound size={19} color={color} strokeWidth={2.25} />,
        }}
      />
    </Tabs>
  );
}

function AnimatedTabBarButton({
  accessibilityState,
  children,
  onLongPress,
  onPress,
  style,
  ...rest
}: AnimatedTabBarButtonProps) {
  const selected = Boolean(accessibilityState?.selected);
  const scale = React.useRef(new Animated.Value(selected ? 1.04 : 1)).current;
  const translateY = React.useRef(new Animated.Value(selected ? -2 : 0)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.spring(scale, {
        toValue: selected ? 1.04 : 1,
        useNativeDriver: true,
        speed: 24,
        bounciness: 5,
      }),
      Animated.spring(translateY, {
        toValue: selected ? -2 : 0,
        useNativeDriver: true,
        speed: 24,
        bounciness: 5,
      }),
    ]).start();
  }, [scale, selected, translateY]);

  return (
    <Pressable
      {...rest}
      accessibilityState={accessibilityState}
      onLongPress={onLongPress}
      onPress={onPress}
      style={style}
    >
      <Animated.View style={{ transform: [{ scale }, { translateY }] }}>{children}</Animated.View>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  center: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
});

import React from 'react';
import { View, ActivityIndicator, StyleSheet, useColorScheme, type ViewStyle, Platform } from 'react-native';
import { PaperProvider, MD3LightTheme, MD3DarkTheme } from 'react-native-paper';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Stack } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import * as Notifications from 'expo-notifications';

import { COLORS } from '../lib/config';
import { AuthProvider, useAuth } from '../hooks/useAuth';
import { NotificationsProvider } from '../hooks/useNotifications';
import { ThemePreferenceProvider, useThemePreference } from '../hooks/useThemePreference';
import { ToastProvider } from '../hooks/useToast';

if (Platform.OS !== 'web') {
  Notifications.setNotificationHandler({
    handleNotification: async () => ({
      shouldPlaySound: true,
      shouldSetBadge: true,
      shouldShowBanner: true,
      shouldShowList: true,
    }),
  });
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      staleTime: 1000 * 60 * 1.5,
      gcTime: 1000 * 60 * 8,
    },
  },
});

function createAppTheme(colorScheme: 'light' | 'dark' | null | 'unspecified' | undefined) {
  const isDark = colorScheme === 'dark';
  const base = isDark ? MD3DarkTheme : MD3LightTheme;

  return {
    ...base,
    colors: {
      ...base.colors,
      primary: COLORS.primary,
      onPrimary: COLORS.onPrimary,
      primaryContainer: isDark ? '#1f2a5e' : '#e0e5f5',
      onPrimaryContainer: isDark ? '#e0e5f5' : '#1f2a5e',
      secondary: COLORS.accent,
      onSecondary: COLORS.onAccent,
      surface: isDark ? COLORS.surfaceDark : COLORS.surface,
      surfaceVariant: isDark ? COLORS.surfaceVariantDark : COLORS.surfaceVariant,
      onSurface: isDark ? COLORS.onSurfaceDark : COLORS.onSurface,
      onSurfaceVariant: isDark ? COLORS.onSurfaceVariantDark : COLORS.onSurfaceVariant,
      outline: isDark ? COLORS.outlineDark : COLORS.outline,
      background: isDark ? COLORS.backgroundDark : COLORS.background,
      elevation: {
        level0: isDark ? COLORS.backgroundDark : COLORS.background,
        level1: isDark ? '#1a2138' : '#f0f2f8',
        level2: isDark ? '#1f2740' : '#e8ebf5',
        level3: isDark ? '#242f5c' : '#e0e5f5',
        level4: isDark ? '#2a3566' : '#d8ddf0',
        level5: isDark ? '#2f3a70' : '#d0d8f0',
      },
      error: COLORS.error,
      onError: '#ffffff',
    },
  };
}

export default function RootLayout() {
  return (
    <SafeAreaProvider>
      <QueryClientProvider client={queryClient}>
        <ThemePreferenceProvider>
          <ThemedApp />
        </ThemePreferenceProvider>
      </QueryClientProvider>
    </SafeAreaProvider>
  );
}

function ThemedApp() {
  const { colorScheme } = useThemePreference();
  const appTheme = createAppTheme(colorScheme);

  return (
    <PaperProvider theme={appTheme}>
      <AuthProvider>
        <ToastProvider>
          <NotificationsProvider>
            <StatusBar style={colorScheme === 'dark' ? 'light' : 'dark'} />
            <RootNavigator backgroundColor={appTheme.colors.background} />
          </NotificationsProvider>
        </ToastProvider>
      </AuthProvider>
    </PaperProvider>
  );
}

function RootNavigator({ backgroundColor }: { backgroundColor: string }) {
  const auth = useAuth();

  return (
    <>
      <Stack screenOptions={{ headerShown: false }}>
        <Stack.Screen name="login" />
        <Stack.Screen name="(tabs)" />
        <Stack.Screen name="index" />
        <Stack.Screen name="promotions" />
        <Stack.Screen name="shift" />
        <Stack.Screen name="payroll" />
      </Stack>

      {auth.isLoading && (
        <View style={[StyleSheet.absoluteFill, styles.loadingOverlay, { backgroundColor }]}>
          <ActivityIndicator size="large" color={COLORS.primary} />
        </View>
      )}
    </>
  );
}

const styles = StyleSheet.create<{ loadingOverlay: ViewStyle }>({
  loadingOverlay: {
    ...StyleSheet.absoluteFill,
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 100,
  },
});

