  },
  logoutButton: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
    paddingHorizontal: 16,
    paddingVertical: 10,
    marginTop: 12,
  },
  logoutText: {
    color: COLORS.accent,
    fontSize: 15,
    fontWeight: '600',
  },
  markAllText: {
    color: COLORS.accent,
    fontSize: 13,
    fontWeight: '700',
  },
  notificationList: {
    gap: 10,
  },
  notificationItem: {
    borderWidth: 1,
    borderRadius: 14,
    paddingHorizontal: 14,
    paddingVertical: 12,
  },
  notificationTitle: {
    fontSize: 14,
    fontWeight: '800',
    marginBottom: 4,
  },
  notificationBody: {
    fontSize: 13,
    lineHeight: 18,
  },
  emptyNotifications: {
    paddingVertical: 16,
  },
  themeTransitionCircle: {
    position: 'absolute',
    width: 44,
    height: 44,
    borderRadius: 22,
    // Will be scaled from center point via transform
  },
});

function MenuContent({
  closeLabelIcon,
  closeMenu,
  drawerItems,
  auth,
  isDark,
  router,
}: {
  closeLabelIcon: React.ReactNode;
  closeMenu: () => void;
  drawerItems: Array<{ label: string; route: string; icon: React.ComponentType<{ size?: number; color?: string }> }>;
  auth: UseAuthReturn;
  isDark: boolean;
  router: ReturnType<typeof useRouter>;
}) {
  const primaryTextColor = isDark ? COLORS.onSurfaceDark : COLORS.onSurface;
  return (
    <>
      <View style={styles.drawerHeader}>
        <Text style={[styles.drawerTitle, { color: primaryTextColor }]}>Menu</Text>
        {closeLabelIcon ? (
          <TouchableScale
            style={[styles.drawerCloseButton, { backgroundColor: isDark ? COLORS.surfaceVariantDark : '#e8ebf5' }]}
            onPress={closeMenu}
            pressedScale={0.92}
          >
            {closeLabelIcon}
          </TouchableScale>
        ) : null}
      </View>

      {drawerItems.map((item) => {
        const Icon = item.icon;
        return (
          <TouchableScale
            key={item.label}
            style={styles.drawerItem}
            onPress={() => {
              closeMenu();
              router.push(item.route as never);
            }}
            pressedScale={0.98}
          >
            <Icon size={18} color={isDark ? COLORS.onSurfaceVariantDark : COLORS.onSurfaceVariant} />
            <Text style={[styles.drawerItemText, { color: isDark ? COLORS.onSurfaceDark : COLORS.onSurface }]}>{item.label}</Text>
          </TouchableScale>
        );
      })}

      <TouchableScale
        style={styles.logoutButton}
        onPress={() => {
          closeMenu();
          void auth.logout();
        }}
        pressedScale={0.98}
      >
        <Power size={18} color={COLORS.accent} />
        <Text style={styles.logoutText}>Logout</Text>
      </TouchableScale>
    </>
  );
}

