import React from 'react';
import {
  Animated,
  Pressable,
  type GestureResponderEvent,
  type PressableProps,
  type StyleProp,
  type ViewStyle,
} from 'react-native';

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

interface TouchableScaleProps extends Omit<PressableProps, 'style'> {
  children: React.ReactNode;
  style?: StyleProp<ViewStyle>;
  pressedScale?: number;
}

export function TouchableScale({
  children,
  style,
  pressedScale = 0.97,
  onPressIn,
  onPressOut,
  ...props
}: TouchableScaleProps) {
  const scale = React.useRef(new Animated.Value(1)).current;

  const animateTo = React.useCallback(
    (value: number) => {
      Animated.spring(scale, {
        toValue: value,
        useNativeDriver: true,
        speed: 24,
        bounciness: 4,
      }).start();
    },
    [scale]
  );

  const handlePressIn = React.useCallback(
    (event: GestureResponderEvent) => {
      animateTo(pressedScale);
      onPressIn?.(event);
    },
    [animateTo, onPressIn, pressedScale]
  );

  const handlePressOut = React.useCallback(
    (event: GestureResponderEvent) => {
      animateTo(1);
      onPressOut?.(event);
    },
    [animateTo, onPressOut]
  );

  return (
    <AnimatedPressable
      {...props}
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      style={[style, { transform: [{ scale }] }]}
    >
      {children}
    </AnimatedPressable>
  );
}

import { createContext, createElement, useState, useEffect, useCallback, useContext, type ReactNode } from 'react';
import { Platform } from 'react-native';
import { api, saveTokens, clearTokens, loadTokensFromStorage, AuthTokens, AuthUser } from '../lib/api';
import * as SecureStore from '../lib/secure-store'; // use wrapper (fixes ExpoSecureStore.default.setValueWithKeyAsync on web)
import {
  authenticateWithBiometrics as promptBiometricAuth,
  getBiometricStatus,
  setBiometricEnabled as storeBiometricEnabled,
} from '../lib/biometrics';
import { normalizeSingle } from '../lib/api';

type AnyRecord = Record<string, unknown>;

interface AuthState {
  isLoading: boolean;
  isAuthenticated: boolean;
  hasStoredSession: boolean;
  user: AuthUser | null;
  employee: any | null;
  error: string | null;
  requiresOtp: boolean;
  tempToken: string | null;
  biometricEnabled: boolean;
  biometricEnrolled: boolean;
  biometricLocked: boolean;
  biometricSupported: boolean;
  biometricTypeLabel: string;
}

function useProvideAuth() {
  const [state, setState] = useState<AuthState>({
    isLoading: true,
    isAuthenticated: false,
    hasStoredSession: false,
    user: null,
    employee: null,
    error: null,
    requiresOtp: false,
    tempToken: null,
    biometricEnabled: false,
    biometricEnrolled: false,
    biometricLocked: false,
    biometricSupported: false,
    biometricTypeLabel: 'Fingerprint',
  });

  const resetOtp = useCallback(() => {
    setState((s) => ({ ...s, requiresOtp: false, tempToken: null, error: null }));
  }, []);

  const clearError = useCallback(() => {
    setState((s) => ({ ...s, error: null }));
  }, []);

  const loadSession = useCallback(async ({ skipBiometricLock = false }: { skipBiometricLock?: boolean } = {}) => {
    setState((s) => ({ ...s, isLoading: true }));
    const [tokens, biometricStatus] = await Promise.all([
      loadTokensFromStorage(),
      getBiometricStatus(),
    ]);
    if (!tokens) {
      setState((s) => ({
        ...s,
        isLoading: false,
        isAuthenticated: false,
        hasStoredSession: biometricStatus.enabled,
        user: null,
        employee: null,
        biometricEnabled: biometricStatus.enabled,
        biometricEnrolled: biometricStatus.enrolled,
        biometricLocked: false,
        biometricSupported: biometricStatus.supported,
        biometricTypeLabel: biometricStatus.label,
      }));
      return;
    }

    try {
      // Try to hydrate current user + employee
      const [userPayload, empPayload] = await Promise.all([
        api.getCurrentUser().catch(() => null),
        api.getCurrentEmployee().catch(() => null),
      ]);

      const user = extractUser(userPayload);
      const employee = await normalizeSingle(empPayload);

      // Fallbacks for name
      const empName = employee ? [employee.first_name, employee.last_name, employee.full_name].filter(Boolean).join(' ') : '';
      const finalUser: AuthUser = user || {
        id: 'me',
        fullName: empName || 'Employee',
        email: (user as any)?.email || (employee as any)?.email || '',
      };

      // Persist lightly
      if (user) await SecureStore.setItemAsync('hrms.user', JSON.stringify(user)).catch(() => {});
      if (employee) await SecureStore.setItemAsync('hrms.employee', JSON.stringify(employee)).catch(() => {});

      const biometricLocked = biometricStatus.enabled && !skipBiometricLock;

      setState({
        isLoading: false,
        isAuthenticated: !biometricLocked,
        hasStoredSession: true,
        user: finalUser,
        employee,
        error: null,
        requiresOtp: false,
        tempToken: null,
        biometricEnabled: biometricStatus.enabled,
        biometricEnrolled: biometricStatus.enrolled,
        biometricLocked,
        biometricSupported: biometricStatus.supported,
        biometricTypeLabel: biometricStatus.label,
      });
    } catch (e: unknown) {
      // Invalid token probably
      await clearTokens();
      setState({
        isLoading: false,
        isAuthenticated: false,
        hasStoredSession: biometricStatus.enabled,
        user: null,
        employee: null,
        error: null,
        requiresOtp: false,
        tempToken: null,
        biometricEnabled: biometricStatus.enabled,
        biometricEnrolled: biometricStatus.enrolled,
        biometricLocked: false,
        biometricSupported: biometricStatus.supported,
        biometricTypeLabel: biometricStatus.label,
      });
    }
  }, []);

  useEffect(() => {
    void loadSession();
  }, [loadSession]);

  const login = useCallback(async (email: string, password: string) => {
    setState((s) => ({ ...s, isLoading: true, error: null }));
    try {
      const res: AnyRecord = await api.login(email.trim(), password) as AnyRecord;

      // Align strictly with the provided OpenAPI spec examples for /api/auth/login
      const userFromResponse = (res?.user as AnyRecord) || ((res?.data as AnyRecord)?.user as AnyRecord) || {};
      const requiresOtp = !!(
        res?.requires_2fa ||
        (userFromResponse as any)?.requires_2fa ||
        res?.requiresOtp ||
        res?.requires_otp ||
        res?.temp_token ||
        res?.tempToken
      );
      const tempToken = (res?.temp_token as string) || (res?.tempToken as string) || null;

      if (requiresOtp && tempToken) {
        setState((s) => ({
          ...s,
          isLoading: false,
          requiresOtp: true,
          tempToken: tempToken as string,
          error: null,
        }));
        return { requiresOtp: true };
      }

      if (requiresOtp) {
        // 2FA required but temp token may be implicit or the client will ask for code in the next step
        setState((s) => ({
          ...s,
          isLoading: false,
          requiresOtp: true,
          tempToken: tempToken as string | null,
          error: null,
        }));
        return { requiresOtp: true };
      }

      // Direct login success (tokens + user) per spec examples
      const tokens = extractTokens(res);
      const user = extractUser(res);

      if (tokens) {
        await saveTokens(tokens);
      }

      setState((s) => ({
        ...s,
        isLoading: false,
        hasStoredSession: !!tokens,
        requiresOtp: false,
        tempToken: null,
      }));

      await loadSession({ skipBiometricLock: true });
      return { requiresOtp: false };
    } catch (e: unknown) {
      const msg = (e as Error)?.message || 'Login failed. Check your credentials.';
      setState((s) => ({ ...s, isLoading: false, error: msg }));
      throw e;
    }
  }, [loadSession]);

  const verifyOtp = useCallback(async (code: string) => {
    if (!state.tempToken) throw new Error('No OTP session. Please login again.');
    setState((s) => ({ ...s, isLoading: true, error: null }));

    try {
      // Per spec: /api/auth/2fa/complete-login expects the temporary token + the code (TOTP or backup)
      const res: AnyRecord = await api.verifyOtp(state.tempToken, code.trim()) as AnyRecord;
      const tokens = extractTokens(res);
      if (tokens) await saveTokens(tokens);

      setState((s) => ({ ...s, requiresOtp: false, tempToken: null, isLoading: false }));
      await loadSession({ skipBiometricLock: true });
    } catch (e: unknown) {
      const msg = (e as Error)?.message || 'Invalid code. Please try again.';
      setState((s) => ({ ...s, isLoading: false, error: msg }));
      throw e;
    }
  }, [state.tempToken, loadSession]);

  const logout = useCallback(async () => {
    const rt = (await SecureStore.getItemAsync('hrms.refreshToken')) || undefined;
    const biometricStatus = await getBiometricStatus();
    await api.logout(rt);
    if (!biometricStatus.enabled) {
      await clearTokens();
    }
    setState({
      isLoading: false,
      isAuthenticated: false,
      hasStoredSession: biometricStatus.enabled,
      user: null,
      employee: null,
      error: null,
      requiresOtp: false,
      tempToken: null,
      biometricEnabled: biometricStatus.enabled,
      biometricEnrolled: biometricStatus.enrolled,
      biometricLocked: false,
      biometricSupported: biometricStatus.supported,
      biometricTypeLabel: biometricStatus.label,
    });
  }, []);

  const refreshProfile = useCallback(async () => {
    await loadSession({ skipBiometricLock: true });
  }, [loadSession]);

  const enableBiometricLogin = useCallback(async () => {
    setState((s) => ({ ...s, isLoading: true, error: null }));

    try {
      const biometricStatus = await getBiometricStatus();
      if (!biometricStatus.supported || !biometricStatus.enrolled) {
        throw new Error(
          Platform.OS === 'web'
            ? 'Fingerprint login is only available in the Android or iPhone app, not the browser preview.'
            : 'Fingerprint login is not available on this device yet.'
        );
      }

      const confirmed = await promptBiometricAuth(
        biometricStatus.label,
        `Confirm your ${biometricStatus.label.toLowerCase()} to enable quick sign in`
      );

      if (!confirmed) {
        throw new Error(`${biometricStatus.label} confirmation was cancelled.`);
      }

      await storeBiometricEnabled(true);
      setState((s) => ({
        ...s,
        isLoading: false,
        hasStoredSession: true,
        biometricEnabled: true,
        biometricEnrolled: biometricStatus.enrolled,
        biometricSupported: biometricStatus.supported,
        biometricTypeLabel: biometricStatus.label,
      }));
      return true;
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : 'Unable to enable fingerprint login.';
      setState((s) => ({ ...s, isLoading: false, error: message }));
      throw e;
    }
  }, []);

  const disableBiometricLogin = useCallback(async () => {
    await storeBiometricEnabled(false);
    const biometricStatus = await getBiometricStatus();
    setState((s) => ({
        ...s,
        biometricEnabled: false,
        biometricEnrolled: biometricStatus.enrolled,
        biometricLocked: false,
        biometricSupported: biometricStatus.supported,
        biometricTypeLabel: biometricStatus.label,
      }));
  }, []);

  const authenticateWithBiometricLogin = useCallback(async () => {
    if (!state.biometricEnabled) {
      return false;
    }

    setState((s) => ({ ...s, isLoading: true, error: null }));

    try {
      const confirmed = await promptBiometricAuth(
        state.biometricTypeLabel,
        `Use ${state.biometricTypeLabel.toLowerCase()} to sign in`
      );

      if (confirmed) {
        await loadSession({ skipBiometricLock: true });
        // loadSession sets isLoading:false and isAuthenticated:true + user data
      } else {
        setState((s) => ({
          ...s,
          isLoading: false,
          isAuthenticated: false,
          biometricLocked: true,
        }));
      }

      return confirmed;
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : 'Fingerprint authentication failed.';
      setState((s) => ({ ...s, isLoading: false, error: message }));
      throw e;
    }
  }, [state.biometricEnabled, state.biometricTypeLabel, loadSession]);

  return {
    ...state,
    authenticateWithBiometricLogin,
    clearError,
    disableBiometricLogin,
    enableBiometricLogin,
    login,
    verifyOtp,
    logout,
    refreshProfile,
    resetOtp,
  };
}

export type UseAuthReturn = ReturnType<typeof useProvideAuth>;

const AuthContext = createContext<UseAuthReturn | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const auth = useProvideAuth();
  return createElement(AuthContext.Provider, { value: auth }, children);
}

export function useAuth() {
  const auth = useContext(AuthContext);
  if (!auth) {
    throw new Error('useAuth must be used within an AuthProvider.');
  }
  return auth;
}

function extractTokens(payload: unknown): AuthTokens | null {
  if (!payload || typeof payload !== 'object') return null;
  const p = payload as AnyRecord;
  const root = (p.data as AnyRecord) || (p.result as AnyRecord) || p || {};
  const t = (root.tokens as AnyRecord) || (p.tokens as AnyRecord) || root;

  // Per OpenAPI spec examples: responses use access_token / refresh_token (snake_case)
  const access =
    (t?.access_token as string) ||
    (t?.accessToken as string) ||
    (root?.access_token as string) ||
    (root?.accessToken as string) ||
    (root?.token as string);
  const refresh =
    (t?.refresh_token as string) ||
    (t?.refreshToken as string) ||
    (root?.refresh_token as string) ||
    (root?.refreshToken as string);

  if (access && refresh) return { accessToken: access, refreshToken: refresh };
  return null;
}

function extractUser(payload: unknown): AuthUser | null {
  if (!payload || typeof payload !== 'object') return null;
  const p = payload as AnyRecord;
  const rootPayload = (p.data as AnyRecord) || (p.result as AnyRecord) || p;
  const root =
    (p.data as AnyRecord)?.user ||
    (p.result as AnyRecord)?.user ||
    (p.user as AnyRecord) ||
    (p.data as AnyRecord) ||
    (p.result as AnyRecord) ||
    p;
  if (!root) return null;

  const r = root as AnyRecord;
  const activeCompany = (r.active_company as AnyRecord) || (rootPayload.active_company as AnyRecord) || (p.company as AnyRecord);
  const companies = Array.isArray(p.companies)
    ? (p.companies as AnyRecord[])
    : Array.isArray(rootPayload.companies)
      ? (rootPayload.companies as AnyRecord[])
      : [];
  const firstCompany = companies.find((entry) => entry && typeof entry === 'object') || null;
  const id = r.id || r.user_id || r.sub;
  const email = r.email as string | undefined;
  let fullName = (r.fullName as string) || (r.full_name as string) || (r.name as string);
  if (!fullName) {
    const fn = (r.first_name as string) || (r.firstName as string) || '';
    const ln = (r.last_name as string) || (r.lastName as string) || '';
    fullName = [fn, ln].filter(Boolean).join(' ').trim() || (email as string);
  }
  if (!id || !email) return null;

  const employeeId =
    (r.employee_no as string) ||
    (r.employeeId as string) ||
    (r.employee_id as string) ||
    (r.user_no as string) ||
    (typeof r.employee_id === 'number' ? String(r.employee_id) : undefined) ||
    (typeof rootPayload.employee_id === 'number' ? String(rootPayload.employee_id) : undefined);

  const role =
    (r.role as string) ||
    (r.user_type as string) ||
    (Array.isArray(r.roles) && typeof r.roles[0] === 'string' ? (r.roles[0] as string) : undefined) ||
    (Array.isArray(r.roles) && r.roles[0] && typeof r.roles[0] === 'object'
      ? ((r.roles[0] as AnyRecord).name as string | undefined)
      : undefined);

  const companyId =
    (typeof r.companyId === 'number' ? r.companyId : undefined) ||
    (typeof activeCompany?.id === 'number' ? activeCompany.id : undefined) ||
    (typeof activeCompany?.company_id === 'number' ? activeCompany.company_id : undefined) ||
    (typeof firstCompany?.companyId === 'number' ? firstCompany.companyId : undefined);

  const companyName =
    (r.companyName as string) ||
    (r.company_name as string) ||
    (activeCompany?.name as string) ||
    (activeCompany?.company_name as string) ||
    (firstCompany?.companyName as string) ||
    (firstCompany?.company_name as string);

  return {
    id: (id ?? 'me') as string | number,
    fullName: fullName || 'Employee',
    email,
    employeeId,
    role,
    companyId,
    companyName,
  };
}

import React, {
  createContext,
  createElement,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { useQuery } from '@tanstack/react-query';

import { api, normalizeList } from '../lib/api';
import {
  ensureNotificationChannelsAsync,
  ensureNotificationPermissionsAsync,
  presentHrmsNotification,
} from '../lib/notification-settings';
import * as SecureStore from '../lib/secure-store';
import { useAuth } from './useAuth';

type NotificationRoute = '/(tabs)/leave';

export interface AppNotification {
  id: string;
  type: 'leave-status';
  title: string;
  body: string;
  createdAt: string;
  read: boolean;
  route: NotificationRoute;
  requestId: string;
  status: string;
}

interface NotificationContextValue {
  notifications: AppNotification[];
  unreadCount: number;
  markAsRead: (id: string) => Promise<void>;
  markAllAsRead: () => Promise<void>;
}

const NotificationContext = createContext<NotificationContextValue | undefined>(undefined);

export function NotificationsProvider({ children }: { children: ReactNode }) {
  const auth = useAuth();
  const userId = String(auth.user?.id ?? '');
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [bootstrappedUserId, setBootstrappedUserId] = useState<string | null>(null);

  const notificationStorageKey = userId ? `hrms.notifications.${userId}` : '';
  const snapshotStorageKey = userId ? `hrms.notificationSnapshot.${userId}` : '';

  const leaveRequestsQuery = useQuery({
    queryKey: ['mobileNotificationLeaveRequests', userId],
    queryFn: async () => normalizeList(await api.listMyLeaveRequests({ limit: 50 })),
    enabled: auth.isAuthenticated && !!userId,
    refetchInterval: 1000 * 30,
  });

  useEffect(() => {
    if (!auth.isAuthenticated) return;

    let cancelled = false;

    async function prepareNativeNotifications() {
      try {
        await ensureNotificationChannelsAsync();
        if (!cancelled) {
          await ensureNotificationPermissionsAsync();
        }
      } catch {
        // Keep in-app notifications working even if native notifications fail.
      }
    }

    void prepareNativeNotifications();

    return () => {
      cancelled = true;
    };
  }, [auth.isAuthenticated]);

  useEffect(() => {
    let cancelled = false;

    async function loadStoredNotifications() {
      if (!userId) {
        if (!cancelled) {
          setNotifications([]);
          setBootstrappedUserId(null);
        }
        return;
      }

      const stored = await SecureStore.getItemAsync(notificationStorageKey);
      if (cancelled) return;

      if (!stored) {
        setNotifications([]);
        setBootstrappedUserId(userId);
        return;
      }

      try {
        const parsed = JSON.parse(stored) as AppNotification[];
        setNotifications(Array.isArray(parsed) ? parsed : []);
      } catch {
        setNotifications([]);
      }
      setBootstrappedUserId(userId);
    }

    void loadStoredNotifications();
    return () => {
      cancelled = true;
    };
  }, [notificationStorageKey, userId]);

  useEffect(() => {
    if (!userId || bootstrappedUserId !== userId) return;
    void SecureStore.setItemAsync(notificationStorageKey, JSON.stringify(notifications));
  }, [bootstrappedUserId, notificationStorageKey, notifications, userId]);

  useEffect(() => {
    if (!auth.isAuthenticated || !userId || bootstrappedUserId !== userId) return;
    if (!leaveRequestsQuery.data) return;

    let cancelled = false;

    async function reconcileNotifications() {
      const currentSnapshot = buildLeaveSnapshot(leaveRequestsQuery.data);
      const storedSnapshotRaw = await SecureStore.getItemAsync(snapshotStorageKey);
      if (cancelled) return;

      if (!storedSnapshotRaw) {
        await SecureStore.setItemAsync(snapshotStorageKey, JSON.stringify(currentSnapshot));
        return;
      }

      let previousSnapshot: Record<string, { status: string; leaveType: string; startDate: string; endDate: string }> = {};
      try {
        previousSnapshot = JSON.parse(storedSnapshotRaw) as typeof previousSnapshot;
      } catch {
        previousSnapshot = {};
      }

      const freshNotifications: AppNotification[] = [];

      Object.entries(currentSnapshot).forEach(([requestId, current]) => {
        const previous = previousSnapshot[requestId];
        if (!previous) return;
        if (previous.status === current.status) return;

        freshNotifications.push({
          id: `leave-status:${requestId}:${current.status}`,
          type: 'leave-status',
          title: `${capitalizeStatus(current.status)} leave request`,
          body: `${current.leaveType || 'Your leave request'} is now ${humanizeStatus(current.status)}.`,
          createdAt: new Date().toISOString(),
          read: false,
          route: '/(tabs)/leave',
          requestId,
          status: current.status,
        });
      });

      const unseenNotifications = freshNotifications.filter(
        (item) => !notifications.some((existing) => existing.id === item.id)
      );

      if (unseenNotifications.length) {
        setNotifications((existing) => {
          const seenIds = new Set(existing.map((item) => item.id));
          const merged = [...unseenNotifications.filter((item) => !seenIds.has(item.id)), ...existing];
          return merged.slice(0, 50);
        });

        await Promise.allSettled(
          unseenNotifications.map((item) =>
            presentHrmsNotification({
              title: item.title,
              body: item.body,
              data: {
                route: item.route,
                requestId: item.requestId,
                status: item.status,
                type: item.type,
              },
            })
          )
        );
      }

      await SecureStore.setItemAsync(snapshotStorageKey, JSON.stringify(currentSnapshot));
    }

    void reconcileNotifications();

    return () => {
      cancelled = true;
    };
  }, [auth.isAuthenticated, bootstrappedUserId, leaveRequestsQuery.data, notifications, snapshotStorageKey, userId]);

  const markAsRead = useCallback(async (id: string) => {
    setNotifications((current) =>
      current.map((item) => (item.id === id ? { ...item, read: true } : item))
    );
  }, []);

  const markAllAsRead = useCallback(async () => {
    setNotifications((current) => current.map((item) => ({ ...item, read: true })));
  }, []);

  const value = useMemo<NotificationContextValue>(
    () => ({
      notifications,
      unreadCount: notifications.filter((item) => !item.read).length,
      markAsRead,
      markAllAsRead,
    }),
    [markAllAsRead, markAsRead, notifications]
  );

  return createElement(NotificationContext.Provider, { value }, children);
}

export function useNotifications() {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error('useNotifications must be used within NotificationsProvider');
  }
  return context;
}

function buildLeaveSnapshot(items: Record<string, unknown>[] | undefined) {
  return (items || []).reduce<Record<string, { status: string; leaveType: string; startDate: string; endDate: string }>>(
    (snapshot, item) => {
      const requestId = String(item.id ?? '');
      if (!requestId) return snapshot;
      const leaveType =
        readString(asRecord(item.leave_type), ['name']) ||
        readString(item, ['leave_type_name']) ||
        'Leave request';

      snapshot[requestId] = {
        status: readString(item, ['status']) || 'pending',
        leaveType,
        startDate: readString(item, ['start_date']),
        endDate: readString(item, ['end_date']),
      };
      return snapshot;
    },
    {}
  );
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' ? (value as Record<string, unknown>) : null;
}

function readString(value: unknown, keys: string[]) {
  const record = asRecord(value);
  if (!record) return '';
  for (const key of keys) {
    const candidate = record[key];
    if (typeof candidate === 'string' && candidate.trim()) return candidate.trim();
  }
  return '';
}

function humanizeStatus(value: string) {
  return value.replaceAll('_', ' ');
}

function capitalizeStatus(value: string) {
  const cleaned = humanizeStatus(value);
  return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
}

