import React, {
  createContext,
  createElement,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import {
  Animated,
  Pressable,
  StyleSheet,
  Text,
  View,
  type ViewStyle,
  type TextStyle,
} from 'react-native';
import { Portal, useTheme } from 'react-native-paper';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { X } from 'lucide-react-native';

import { useThemePreference } from './useThemePreference';
import { COLORS } from '../lib/config';

export type ToastType = 'error' | 'success' | 'info';

export interface ToastAction {
  label: string;
  onPress: () => void;
}

export interface ToastOptions {
  message: string;
  type?: ToastType;
  duration?: number;
  action?: ToastAction;
}

interface ToastContextValue {
  show: (options: ToastOptions | string) => void;
  error: (message: string, options?: Partial<Omit<ToastOptions, 'message' | 'type'>>) => void;
  success: (message: string, options?: Partial<Omit<ToastOptions, 'message' | 'type'>>) => void;
  info: (message: string, options?: Partial<Omit<ToastOptions, 'message' | 'type'>>) => void;
  hide: () => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

interface CurrentToast extends ToastOptions {
  id: number;
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const [current, setCurrent] = useState<CurrentToast | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const translateY = useRef(new Animated.Value(-80)).current;
  const opacity = useRef(new Animated.Value(0)).current;
  const idCounter = useRef(0);

  const hide = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    Animated.parallel([
      Animated.timing(translateY, {
        toValue: -80,
        duration: 180,
        useNativeDriver: true,
      }),
      Animated.timing(opacity, {
        toValue: 0,
        duration: 180,
        useNativeDriver: true,
      }),
    ]).start(() => {
      setCurrent(null);
      translateY.setValue(-80);
      opacity.setValue(0);
    });
  }, [translateY, opacity]);

  const show = useCallback(
    (options: ToastOptions | string) => {
      const toastOptions: ToastOptions =
        typeof options === 'string' ? { message: options } : options;

      // Clear any existing
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }

      const newToast: CurrentToast = {
        ...toastOptions,
        type: toastOptions.type ?? 'info',
        duration: toastOptions.duration ?? 4500,
        id: ++idCounter.current,
      };

      setCurrent(newToast);

      // Animate in
      translateY.setValue(-80);
      opacity.setValue(0);
      Animated.parallel([
        Animated.spring(translateY, {
          toValue: 0,
          useNativeDriver: true,
          speed: 20,
          bounciness: 4,
        }),
        Animated.timing(opacity, {
          toValue: 1,
          duration: 160,
          useNativeDriver: true,
        }),
      ]).start();

      // Auto dismiss (longer if has action)
      const baseDuration = newToast.duration ?? 4500;
      const dismissAfter = newToast.action ? Math.max(baseDuration, 8000) : baseDuration;

      timeoutRef.current = setTimeout(() => {
        hide();
      }, dismissAfter);
    },
    [hide, translateY, opacity]
  );

  const error = useCallback(
    (message: string, options?: Partial<Omit<ToastOptions, 'message' | 'type'>>) => {
      show({ message, type: 'error', ...options });
    },
    [show]
  );

  const success = useCallback(
    (message: string, options?: Partial<Omit<ToastOptions, 'message' | 'type'>>) => {
      show({ message, type: 'success', ...options });
    },
    [show]
  );

  const info = useCallback(
    (message: string, options?: Partial<Omit<ToastOptions, 'message' | 'type'>>) => {
      show({ message, type: 'info', ...options });
    },
    [show]
  );

  // Cleanup
  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  const value = React.useMemo(
    () => ({ show, error, success, info, hide }),
    [show, error, success, info, hide]
  );

  return (
    <ToastContext.Provider value={value}>
      {children}
      {current && (
        <Portal>
          <ToastRenderer
            toast={current}
            onHide={hide}
            translateY={translateY}
            opacity={opacity}
          />
        </Portal>
      )}
    </ToastContext.Provider>
  );
}

function ToastRenderer({
  toast,
  onHide,
  translateY,
  opacity,
}: {
  toast: CurrentToast;
  onHide: () => void;
  translateY: Animated.Value;
  opacity: Animated.Value;
}) {
  const insets = useSafeAreaInsets();
  const paperTheme = useTheme();
  const { isDark } = useThemePreference();

  const type = toast.type ?? 'info';

  // System-like colors using the app theme + COLORS
  let backgroundColor: string;
  let textColor: string;
  let accentColor: string;

  if (type === 'error') {
    backgroundColor = isDark ? '#2c1f1f' : '#fef2f2';
    textColor = isDark ? '#fca5a5' : '#991b1b';
    accentColor = COLORS.error;
  } else if (type === 'success') {
    backgroundColor = isDark ? '#1f2a22' : '#ecfdf5';
    textColor = isDark ? '#86efac' : '#166534';
    accentColor = COLORS.success ?? '#15803d';
  } else {
    backgroundColor = isDark ? paperTheme.colors.surface : '#f8fafc';
    textColor = isDark ? paperTheme.colors.onSurface : '#1e2937';
    accentColor = paperTheme.colors.primary;
  }

  const handleActionPress = () => {
    if (toast.action) {
      toast.action.onPress();
      // Close after action unless the action itself shows another toast
      onHide();
    }
  };

  return (
    <Animated.View
      style={[
        styles.container,
        {
          top: insets.top + 8,
          opacity,
          transform: [{ translateY }],
          backgroundColor,
          borderColor: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)',
        },
      ]}
    >
      {/* Left accent bar */}
      <View style={[styles.accent, { backgroundColor: accentColor }]} />

      <View style={styles.content}>
        <Text style={[styles.message, { color: textColor }]} numberOfLines={3}>
          {toast.message}
        </Text>

        <View style={styles.actions}>
          {toast.action ? (
            <Pressable
              onPress={handleActionPress}
              style={[styles.actionButton, { borderColor: accentColor }]}
            >
              <Text style={[styles.actionText, { color: accentColor }]}>
                {toast.action.label}
              </Text>
            </Pressable>
          ) : null}

          <Pressable
            onPress={onHide}
            hitSlop={12}
            style={styles.closeButton}
            accessibilityLabel="Close notification"
          >
            <X size={18} color={textColor} />
          </Pressable>
        </View>
      </View>
    </Animated.View>
  );
}

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    left: 12,
    right: 12,
    borderRadius: 14,
    borderWidth: 1,
    flexDirection: 'row',
    alignItems: 'flex-start',
    paddingVertical: 12,
    paddingRight: 8,
    paddingLeft: 4,
