import {
  createBranch,
  deleteBranch,
  grantBranchAccess,
  listBranchAccess,
  listBranches,
  listUsers,
  patchBranch,
  revokeBranchAccess,
  type AdminRecord,
  type BranchesQueryParams,
} from "@/lib/admin-api"
import { canPerformPermission, normalizePermissionLabels } from "@/components/app-sidebar"
import { env } from "@/lib/env"
import { AUTH_STORAGE_KEYS } from "@/utils/constants"
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"

const TOKEN_STORAGE_KEY = "hrms.admin.accessToken"

const DEFAULT_QUERY: Required<Omit<BranchesQueryParams, "status">> & {
  status: string
} = {
  page: 1,
  limit: 20,
  sortBy: "created_at",
  sortOrder: "DESC",
  search: "",
  status: "",
}

type BranchForm = {
  name: string
  country: string
  city: string
  address: string
  status: string
}

type CountryOption = { code: string; name: string }

const regionDisplayNames =
  typeof Intl !== "undefined" && typeof Intl.DisplayNames !== "undefined"
    ? new Intl.DisplayNames(["en"], { type: "region" })
    : null

function safeCountryName(code: string) {
  try {
    return regionDisplayNames?.of(code) ?? code
  } catch {
    return code
  }
}

const COUNTRY_OPTIONS: CountryOption[] = (countryCodes as string[])
  .map((code) => ({
    code,
    name: safeCountryName(code),
  }))
  .sort((first, second) => first.name.localeCompare(second.name))

const CITY_OPTIONS_BY_COUNTRY: Record<string, string[]> = {
  Tanzania: ["Dar es Salaam", "Arusha", "Moshi", "Mwanza", "Zanzibar", "Dodoma", "Mbeya", "Morogoro"],
  Kenya: ["Nairobi", "Mombasa", "Kisumu", "Nakuru"],
  Uganda: ["Kampala", "Entebbe", "Gulu", "Jinja"],
  Rwanda: ["Kigali", "Huye", "Musanze"],
}

function readStoredToken() {
  if (typeof window === "undefined") {
    return ""
  }

  const authTokensRaw = window.localStorage.getItem(AUTH_STORAGE_KEYS.tokens)
  if (authTokensRaw) {
    try {
      const parsed = JSON.parse(authTokensRaw) as { accessToken?: string; access_token?: string }
      const accessToken = (parsed.accessToken ?? parsed.access_token ?? "").trim()
      if (accessToken) {
        return accessToken
      }
    } catch {
      // Fall back to legacy key below.
    }
  }

  return window.localStorage.getItem(TOKEN_STORAGE_KEY)?.trim() ?? ""
}

function collectPermissionNames(value: unknown, sink: Set<string>) {
  if (typeof value === "string" && value.trim()) {
    sink.add(value.trim())
    return
  }

  if (Array.isArray(value)) {
    value.forEach((entry) => collectPermissionNames(entry, sink))
    return
  }

  if (typeof value !== "object" || value === null) {
    return
  }

  const record = value as Record<string, unknown>
  for (const key of ["permissions", "authorities", "actions", "scopes", "data", "items", "results", "user"]) {
    collectPermissionNames(record[key], sink)
  }
}

function readActorPermissions() {
  if (typeof window === "undefined") {
    return [] as string[]
  }

  const names = new Set<string>()

  try {
    const raw = window.sessionStorage.getItem("hrms.dashboard.actorPermissions")
    if (raw) {
      const parsed = JSON.parse(raw) as unknown
      if (Array.isArray(parsed)) {
        return normalizePermissionLabels(parsed.filter((entry) => typeof entry === "string"))
      }
    }
  } catch {
    // Fall back to local payloads.
  }

  try {
    const rawUser = window.localStorage.getItem(AUTH_STORAGE_KEYS.user)
    if (rawUser) {
      collectPermissionNames(JSON.parse(rawUser), names)
    }
  } catch {
    // ignore malformed stored user
  }

  try {
    const rawTokens = window.localStorage.getItem(AUTH_STORAGE_KEYS.tokens)
    if (rawTokens) {
      collectPermissionNames(JSON.parse(rawTokens), names)
    }
  } catch {
    // ignore malformed stored tokens
  }

  return normalizePermissionLabels(Array.from(names))
}

function readString(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "string" && value.trim()) {
      return value
    }
  }
  return "-"
}

function readNumber(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "number" && Number.isFinite(value)) {
      return value
    }
    if (typeof value === "string" && value.trim()) {
      const parsed = Number(value)
      if (Number.isFinite(parsed)) {
        return parsed
      }
    }
  }
  return null
}

function emptyForm(): BranchForm {
  return {
    name: "",
    country: "",
    city: "",
    address: "",
    status: "active",
  }
}

function userLabel(row: AdminRecord) {
  const first = readString(row, ["first_name", "firstName"])
  const last = readString(row, ["last_name", "lastName"])
  const fullName = [first, last].filter((value) => value !== "-").join(" ").trim()
  const displayName = fullName || readString(row, ["name", "full_name", "display_name"])
  const email = readString(row, ["email"])
  if (displayName !== "-" && email !== "-") {
    return `${displayName} (${email})`
  }
  if (displayName !== "-") {
    return displayName
  }
  if (email !== "-") {
    return email
  }
  const id = readNumber(row, ["id", "user_id"])
  return id === null ? "Unknown user" : `User #${id}`
}

function accessUserName(row: AdminRecord, users: AdminRecord[]) {
  const direct = readString(row, [
    "name",
    "full_name",
    "display_name",
    "user_name",
    "username",
    "email",
  ])
  if (direct !== "-") {
    return direct
  }

  const user = (row.user ?? row.company_user ?? null) as AdminRecord | null
  if (user) {
    const nested = userLabel(user)
    if (nested !== "Unknown user") {
      return nested
    }
  }

  const userId = readNumber(row, ["user_id", "id"])
  if (userId === null) {
    return "-"
  }

  const matched = users.find((candidate) => {
    const id = readNumber(candidate, ["id", "user_id"])
    return id === userId
  })
  return matched ? userLabel(matched) : "-"
}

function accessRowUserId(row: AdminRecord) {
  const nestedUser = (row.user ?? row.company_user ?? null) as AdminRecord | null
  if (nestedUser) {
    const nestedId = readNumber(nestedUser, ["id", "user_id"])
    if (nestedId !== null) {
      return nestedId
    }
  }
  return readNumber(row, ["user_id"])
}

export function BranchesView() {
  // Permissions come from browser storage — always start empty so SSR and the
  // first client paint match, then hydrate from session/local storage after mount.
  const [actorPermissions, setActorPermissions] = React.useState<string[]>([])
  const [permissionsReady, setPermissionsReady] = React.useState(false)
  const [query, setQuery] = React.useState(DEFAULT_QUERY)
  const [rows, setRows] = React.useState<AdminRecord[]>([])
  const [loading, setLoading] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [page, setPage] = React.useState(1)
  const [totalPages, setTotalPages] = React.useState<number | null>(null)
  const [total, setTotal] = React.useState<number | null>(null)

  const [openForm, setOpenForm] = React.useState(false)
  const [form, setForm] = React.useState<BranchForm>(emptyForm())
  const [editingId, setEditingId] = React.useState<number | null>(null)

  const [openAccess, setOpenAccess] = React.useState(false)
  const [accessBranch, setAccessBranch] = React.useState<AdminRecord | null>(null)
  const [accessRows, setAccessRows] = React.useState<AdminRecord[]>([])
  const [accessError, setAccessError] = React.useState<string | null>(null)
  const [companyUsers, setCompanyUsers] = React.useState<AdminRecord[]>([])
  const [accessUserId, setAccessUserId] = React.useState<number | null>(null)
  const [accessUserIds, setAccessUserIds] = React.useState<number[]>([])
  const [accessUserQuery, setAccessUserQuery] = React.useState("")
  const [accessPickerOpen, setAccessPickerOpen] = React.useState(false)
  const [pendingDelete, setPendingDelete] = React.useState<AdminRecord | null>(null)
  const debouncedSearch = useDebouncedValue(query.search, 350)

  React.useEffect(() => {
    setActorPermissions(readActorPermissions())
    setPermissionsReady(true)
  }, [])

  const cityOptions = React.useMemo(() => {
    const selectedCountry = form.country.trim().toLowerCase()
    if (!selectedCountry) {
      return [] as string[]
    }

    const knownCities = Object.entries(CITY_OPTIONS_BY_COUNTRY).find(
      ([country]) => country.toLowerCase() === selectedCountry
    )?.[1] ?? []

    const existingBranchCities = rows
      .filter((row) => readString(row, ["country"]).toLowerCase() === selectedCountry)
      .map((row) => readString(row, ["city"]))
      .filter((value) => value !== "-")

    return Array.from(new Set([...knownCities, ...existingBranchCities]))
  }, [form.country, rows])

  const normalizedQuery = React.useMemo(
    () => ({
      ...query,
      search: debouncedSearch,
      status: query.status || undefined,
    }),
    [debouncedSearch, query]
  )

  const fetchBranches = React.useCallback(async (signal?: AbortSignal) => {
    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      setRows([])
      return
    }

    setLoading(true)
    setError(null)
    try {
      const result = await listBranches(
        token,
        {
          ...normalizedQuery,
          page,
        },
        {
          signal,
          cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_SHORT_MS,
        }
      )
      setRows(result.rows)
      setTotalPages(result.totalPages)
      setTotal(result.total)
    } catch (errorObject) {
      if (signal?.aborted) {
        return
      }
      setRows([])
      setTotalPages(null)
      setTotal(null)
      setError(errorObject instanceof Error ? errorObject.message : "Failed to load branches.")
    } finally {
      if (!signal?.aborted) {
        setLoading(false)
      }
    }
  }, [normalizedQuery, page])

  React.useEffect(() => {
    const controller = new AbortController()
    void fetchBranches(controller.signal)
    return () => controller.abort()
  }, [fetchBranches])

  const canGoPrevious = page > 1 && !loading
  const canGoNext = !loading && (totalPages === null || page < totalPages)

  const queueAccessUser = React.useCallback((id: number) => {
    setAccessUserIds((previous) => (previous.includes(id) ? previous : [...previous, id]))
    setAccessUserId(null)
    setAccessUserQuery("")
    setAccessPickerOpen(true)
    setAccessError(null)
  }, [])

  function fillFormFromRow(row: AdminRecord) {
    setForm({
      name: readString(row, ["name"]),
      country: readString(row, ["country"]),
      city: readString(row, ["city"]),
      address: readString(row, ["address"]),
      status: readString(row, ["status"]) === "-" ? "active" : readString(row, ["status"]),
    })
  }

  async function submitForm() {
    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      return
    }
    if (editingId === null && !canCreateBranches) {
      setError("You do not have permission to create branches.")
      return
    }
    if (editingId !== null && !canUpdateBranches) {
      setError("You do not have permission to update branches.")
      return
    }

    const payload: AdminRecord = {
      name: form.name.trim(),
      country: form.country.trim(),
      city: form.city.trim(),
      address: form.address.trim(),
      status: form.status || "active",
    }

    setSaving(true)
    setError(null)
    try {
      if (editingId === null) {
        await createBranch(token, payload)
      } else {
        await patchBranch(token, editingId, payload)
      }
      setOpenForm(false)
      setEditingId(null)
      setForm(emptyForm())
      await fetchBranches()
    } catch (errorObject) {
      setError(errorObject instanceof Error ? errorObject.message : "Failed to save branch.")
    } finally {
      setSaving(false)
    }
  }

  async function handleDelete(row: AdminRecord) {
    const token = readStoredToken()
    const id = readNumber(row, ["id"])
    if (!token || id === null) {
      return
    }
    if (!canDeleteBranches) {
      setError("You do not have permission to delete branches.")
      return
    }
    setSaving(true)
    setError(null)
    try {
      await deleteBranch(token, id)
      await fetchBranches()
    } catch (errorObject) {
      setError(errorObject instanceof Error ? errorObject.message : "Failed to delete branch.")
    } finally {
      setSaving(false)
    }
  }

  async function openBranchAccess(row: AdminRecord) {
    const token = readStoredToken()
    const id = readNumber(row, ["id"])
    if (!token || id === null) {
      return
    }
    if (!canManageBranchAccess) {
      setError("You do not have permission to manage branch access.")
      return
    }
    setAccessBranch(row)
    setAccessUserId(null)
    setAccessUserIds([])
    setAccessUserQuery("")
    setOpenAccess(true)
    setSaving(true)
    setError(null)
    setAccessError(null)
    try {
      const [records, usersResult] = await Promise.all([
        listBranchAccess(token, id),
        listUsers(token, { page: 1, limit: 100, sortBy: "created_at", sortOrder: "DESC" }),
      ])
      setAccessRows(records)
      setCompanyUsers(usersResult.rows)
    } catch (errorObject) {
      setAccessRows([])
      setCompanyUsers([])
      setError(errorObject instanceof Error ? errorObject.message : "Failed to load branch access.")
    } finally {
      setSaving(false)
    }
  }

  async function grantAccess() {
    const token = readStoredToken()
    const branchId = readNumber(accessBranch ?? {}, ["id"])
    let userId = accessUserId
    if (userId === null && accessUserQuery.trim()) {
      const matched = selectableUsers.find((user) => {
        const id = readNumber(user, ["id", "user_id"])
        if (id === null) {
          return false
        }
        return accessUserQuery.trim() === `${id} - ${userLabel(user)}`
      })
      userId = matched ? readNumber(matched, ["id", "user_id"]) : null
    }
    const queuedUserIds = accessUserIds.filter((id) => id > 0)
    if (queuedUserIds.length === 0 && userId !== null && userId > 0) {
      queuedUserIds.push(userId)
    }
    if (!token || branchId === null || queuedUserIds.length === 0) {
      setAccessError("Please choose at least one valid user before granting branch access.")
      return
    }
    if (!canManageBranchAccess) {
      setAccessError("You do not have permission to manage branch access.")
      return
    }
    setSaving(true)
    setAccessError(null)
    try {
      await Promise.all(queuedUserIds.map((id) => grantBranchAccess(token, branchId, id)))
      const records = await listBranchAccess(token, branchId)
      setAccessRows(records)
      setAccessUserId(null)
      setAccessUserIds([])
      setAccessUserQuery("")
    } catch (errorObject) {
      setAccessError(errorObject instanceof Error ? errorObject.message : "Failed to grant branch access.")
    } finally {
      setSaving(false)
    }
  }

  async function revokeAccess(userId: number) {
    const token = readStoredToken()
    const branchId = readNumber(accessBranch ?? {}, ["id"])
    if (!token || branchId === null) {
      return
    }
    if (!canManageBranchAccess) {
      setAccessError("You do not have permission to manage branch access.")
      return
    }
    setSaving(true)
    setAccessError(null)
    try {
      await revokeBranchAccess(token, branchId, userId)
      const records = await listBranchAccess(token, branchId)
      setAccessRows(records)
    } catch (errorObject) {
      setAccessError(errorObject instanceof Error ? errorObject.message : "Failed to revoke branch access.")
    } finally {
      setSaving(false)
    }
  }

  const assignedUserIds = new Set(
    accessRows
      .map((row) => accessRowUserId(row))
      .filter((value): value is number => value !== null)
  )

  const selectableUsers = companyUsers.filter((user) => {
    const id = readNumber(user, ["id", "user_id"])
    return id !== null && !assignedUserIds.has(id)
  })

  const queryText = accessUserQuery.trim().toLowerCase()
  const filteredSelectableUsers = (!queryText
    ? selectableUsers.slice(0, 8)
    : selectableUsers
        .filter((user) => `${readNumber(user, ["id", "user_id"]) ?? ""} ${userLabel(user)}`.toLowerCase().includes(queryText))
        .slice(0, 8))

  const canCreateBranches =
    permissionsReady && canPerformPermission(actorPermissions, "branches:create")
  const canUpdateBranches =
    permissionsReady && canPerformPermission(actorPermissions, "branches:update")
  const canDeleteBranches =
    permissionsReady && canPerformPermission(actorPermissions, "branches:delete")
  const canManageBranchAccess =
    permissionsReady && canPerformPermission(actorPermissions, "branches:manage-access")

  const accessColumns: Column<AdminRecord>[] = [
    {
      key: "user",
      label: "User",
      defaultWidth: 260,
      render: (row) => accessUserName(row, companyUsers),
    },
    {
      key: "user_id",
      label: "User ID",
      defaultWidth: 90,
      render: (row) => String(accessRowUserId(row) ?? "-"),
    },
    {
      key: "actions",
      label: "Actions",
      defaultWidth: 90,
      sortable: false,
      render: (row) => {
        const userId = accessRowUserId(row)
        return (
          <div className="flex justify-end gap-1 pr-1" onClick={(event) => event.stopPropagation()}>
            {canManageBranchAccess ? (
              <button
                type="button"
                className="admin-table-icon-button"
                data-variant="danger"
                disabled={saving || userId === null}
                onClick={() => {
                  if (userId !== null) {
                    void revokeAccess(userId)
                  }
                }}
                aria-label="Revoke branch access"
                title="Revoke branch access"
              >
                <Trash2 className="size-4" />
              </button>
            ) : null}
          </div>
        )
      },
    },
  ]

  const branchColumns: Column<AdminRecord>[] = [
    { key: "name", label: "Name", defaultWidth: 110, sortable: true, render: (r) => readString(r, ["name"]) },
    { key: "code", label: "Code", defaultWidth: 55, sortable: true, render: (r) => readString(r, ["code"]) },
    { key: "country", label: "Country", defaultWidth: 65, sortable: true, render: (r) => readString(r, ["country"]) },
    { key: "city", label: "City", defaultWidth: 65, sortable: true, render: (r) => readString(r, ["city"]) },
    { key: "status", label: "Status", defaultWidth: 55, sortable: true, render: (r) => readString(r, ["status"]) },
    {
      key: "actions",
      label: "Actions",
      defaultWidth: 70,
      sortable: false,
      render: (row) => {
        const id = readNumber(row, ["id"])
        return (
          <div className="flex justify-end gap-1 pr-1" onClick={(e) => e.stopPropagation()}>
            {canUpdateBranches ? (
              <button
                type="button"
                className="admin-table-icon-button"
                onClick={() => {
                  fillFormFromRow(row)
                  setEditingId(id)
                  setOpenForm(true)
                }}
                aria-label="Edit branch"
                title="Edit branch"
              >
                <Pencil className="size-4" />
              </button>
            ) : null}
            {canManageBranchAccess ? (
              <button
                type="button"
                className="admin-table-icon-button"
                onClick={() => void openBranchAccess(row)}
                aria-label="Branch access"
                title="Branch access"
              >
                <KeyRound className="size-4" />
              </button>
            ) : null}
            {canDeleteBranches ? (
              <button
                type="button"
                className="admin-table-icon-button"
                data-variant="danger"
                disabled={saving}
                onClick={() => setPendingDelete(row)}
                aria-label="Delete branch"
                title="Delete branch"
              >
                <Trash2 className="size-4" />
              </button>
            ) : null}
          </div>
        )
      },
    },
  ]

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-1.5">
        <SearchToggleField
          className="min-w-0"
          placeholder="Search branch"
          value={query.search}
          onChange={(value) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, search: value }))
          }}
        />
        <select
          className="h-8 min-w-[8rem] rounded-md border border-slate-300 bg-white px-2 text-xs text-slate-900"
          value={query.status}
          onChange={(event) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, status: event.target.value }))
          }}
          aria-label="Filter branch status"
        >
          <option value="">All statuses</option>
          <option value="active">active</option>
          <option value="inactive">inactive</option>
        </select>
        <div className="ml-auto flex items-center gap-1.5">
          {canCreateBranches ? (
            <button
              type="button"
              className="inline-flex h-8 items-center gap-1.5 rounded-md bg-[var(--primary)] px-2.5 text-xs font-semibold text-white transition hover:brightness-95 disabled:opacity-60"
              onClick={() => {
                setEditingId(null)
                setForm(emptyForm())
                setOpenForm(true)
              }}
              aria-label="Add branch"
              title="Add branch"
            >
              <Plus className="size-3.5" />
              Add Branch
            </button>
          ) : null}
          <button
            type="button"
            className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-slate-300 bg-white text-primary transition hover:bg-slate-50 disabled:opacity-60"
            onClick={() => void fetchBranches()}
            disabled={loading}
            aria-label="Refresh"
            title="Refresh"
          >
            <RefreshCw className={`size-3.5 text-primary ${loading ? "animate-spin" : ""}`} />
          </button>
        </div>
      </div>

      {error ? <p className="text-sm text-rose-600">{error}</p> : null}

      <ResizableTable
        title="Branch"
        data={rows}
        columns={branchColumns}
        itemsPerPage={20}
        loading={loading}
        storageKey="branches"
      />

      {openForm ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-2xl rounded-lg border border-slate-200 bg-white p-4 shadow-lg">
            <h3 className="text-lg font-semibold text-slate-900">{editingId === null ? "Add" : "Edit"} Branch</h3>
            <div className="mt-3 grid gap-3 md:grid-cols-2">
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Name</span>
                <input className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.name} onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Country</span>
                <input
                  list="branch-country-options"
                  className="h-10 rounded-md border border-slate-300 px-3 text-sm"
                  value={form.country}
                  onChange={(event) => {
                    const nextCountry = event.target.value
                    setForm((prev) => {
                      const selectedChanged = prev.country.trim().toLowerCase() !== nextCountry.trim().toLowerCase()
                      return {
                        ...prev,
                        country: nextCountry,
                        city: selectedChanged ? "" : prev.city,
                      }
                    })
                  }}
                  placeholder="Select country"
                />
                <datalist id="branch-country-options">
                  {COUNTRY_OPTIONS.map((option) => (
                    <option key={option.code} value={option.name} />
                  ))}
                </datalist>
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">City</span>
                <input
                  list="branch-city-options"
                  className="h-10 rounded-md border border-slate-300 px-3 text-sm"
                  value={form.city}
                  onChange={(event) => setForm((prev) => ({ ...prev, city: event.target.value }))}
                  placeholder={form.country ? "Select city" : "Select country first"}
                />
                <datalist id="branch-city-options">
                  {cityOptions.map((city) => (
                    <option key={city} value={city} />
                  ))}
                </datalist>
              </label>
              <label className="grid gap-1 md:col-span-2">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Address</span>
                <Textarea className="min-h-20 rounded-md border border-slate-300 px-3 py-2 text-sm" value={form.address} onChange={(event) => setForm((prev) => ({ ...prev, address: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Status</span>
                <select className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.status} onChange={(event) => setForm((prev) => ({ ...prev, status: event.target.value }))}>
                  <option value="active">active</option>
                  <option value="inactive">inactive</option>
                </select>
              </label>
            </div>
            <div className="mt-4 flex justify-end gap-2">
              <button type="button" className="rounded-md border border-slate-300 px-3 py-2 text-sm" onClick={() => setOpenForm(false)}>
                Cancel
              </button>
              <button type="button" className="rounded-md bg-[var(--primary)] px-3 py-2 text-sm font-medium text-white transition hover:brightness-95 disabled:opacity-60" disabled={saving} onClick={() => void submitForm()}>
                {saving ? "Saving..." : "Save"}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      {openAccess && accessBranch ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-2xl rounded-lg border border-slate-200 bg-white p-4 shadow-lg">
            <h3 className="text-lg font-semibold text-slate-900">Branch Access: {readString(accessBranch, ["name", "code"])}</h3>
            <div className="mt-3 grid gap-3 md:grid-cols-[minmax(0,1fr)_auto] md:items-end">
              <label className="grid min-w-0 gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">User</span>
                {accessUserIds.length > 0 ? (
                  <div className="flex flex-wrap gap-2 rounded-md border border-slate-200 bg-slate-50 p-2">
                    {accessUserIds.map((id) => {
                      const user = selectableUsers.find((candidate) => readNumber(candidate, ["id", "user_id"]) === id)
                      const label = user ? userLabel(user) : `User #${id}`
                      return (
                        <span key={id} className="inline-flex items-center gap-1 rounded-full border border-slate-300 bg-white px-2 py-1 text-xs text-slate-700">
                          {label}
                          <button
                            type="button"
                            className="rounded px-1 text-slate-500 hover:bg-slate-100 hover:text-slate-700"
                            onClick={() => {
                              setAccessUserIds((previous) => previous.filter((entry) => entry !== id))
                              if (accessUserId === id) {
                                setAccessUserId(null)
                              }
                            }}
                            aria-label={`Remove ${label}`}
                          >
                            ×
                          </button>
                        </span>
                      )
                    })}
                  </div>
                ) : null}
                <div className="relative">
                  <input
                    className="h-10 w-full rounded-md border border-slate-300 px-4 text-sm"
                    value={accessUserQuery}
                    onFocus={() => setAccessPickerOpen(true)}
                    onBlur={() => {
                      window.setTimeout(() => setAccessPickerOpen(false), 120)
                    }}
                    onChange={(event) => {
                      const raw = event.target.value
                      setAccessUserQuery(raw)
                      const matched = selectableUsers.find((user) => {
                        const id = readNumber(user, ["id", "user_id"])
                        if (id === null) {
                          return false
                        }
                        return raw === `${id} - ${userLabel(user)}`
                      })
                      if (matched) {
                        const id = readNumber(matched, ["id", "user_id"])
                        setAccessUserId(id)
                      } else {
                        setAccessUserId(null)
                      }
                    }}
                    placeholder="Search and select user (e.g. Emmanuel)"
                  />
                  {accessPickerOpen && filteredSelectableUsers.length > 0 ? (
                    <div className="absolute left-0 right-0 top-[calc(100%+6px)] z-20 max-h-56 overflow-y-auto rounded-md border border-slate-200 bg-white p-1 shadow-lg">
                      {filteredSelectableUsers.map((user) => {
                        const id = readNumber(user, ["id", "user_id"])
                        if (id === null) {
                          return null
                        }
                        const label = `${id} - ${userLabel(user)}`
                        return (
                          <button
                            key={id}
                            type="button"
                            className="block w-full rounded-md px-3 py-2 text-left text-sm text-slate-700 hover:bg-slate-100"
                            onMouseDown={(event) => {
                              event.preventDefault()
                              queueAccessUser(id)
                            }}
                            onClick={() => queueAccessUser(id)}
                          >
                            {label}
                          </button>
                        )
                      })}
                    </div>
                  ) : null}
                </div>
              </label>
              <button
                type="button"
                className="h-10 rounded-md bg-[var(--primary)] px-3 text-sm font-medium text-white transition hover:brightness-95 md:whitespace-nowrap"
                onClick={() => void grantAccess()}
              >
                Grant Access
              </button>
            </div>
            {accessError ? <p className="mt-2 text-sm text-rose-600">{accessError}</p> : null}

            <ResizableTable
              title="Access"
              data={accessRows}
              columns={accessColumns}
              itemsPerPage={10}
              storageKey="branch-access"
            />

            <div className="mt-4 flex justify-end gap-2">
              <button
                type="button"
                className="rounded-md border border-slate-300 px-3 py-2 text-sm"
                onClick={() => {
                  setOpenAccess(false)
                  setAccessError(null)
                }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <AlertDialog
        open={Boolean(pendingDelete)}
        onOpenChange={(open) => {
          if (!open) {
            setPendingDelete(null)
          }
        }}
      >
        <AlertDialogContent className="max-w-md">
          <AlertDialogHeader>
            <AlertDialogTitle>Confirm Delete</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this branch? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <button
              type="button"
              disabled={saving || !pendingDelete}
              className="rounded-md bg-[hsl(358,82%,59%)] px-3 py-2 text-sm font-medium text-white hover:brightness-95 disabled:cursor-not-allowed disabled:opacity-60"
              onClick={async () => {
                if (!pendingDelete) {
                  return
                }
                const row = pendingDelete
                setPendingDelete(null)
                await handleDelete(row)
              }}
            >
              {saving ? "Deleting..." : "Delete"}
            </button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

"use client"

import * as React from "react"
import { Pencil, Plus, RefreshCw, Trash2 } from "lucide-react"
import { SearchToggleField } from "@/components/common/search-toggle-field"
import { ResizableTable, type Column } from "@/components/ui/resizable-table"
import { Textarea } from "@/components/ui/textarea"
import { useDebouncedValue } from "@/hooks/use-debounced-value"

import {
  createDepartment,
  deleteDepartment,
  listBranches,
  listDepartments,
  patchDepartment,
  type AdminRecord,
  type DepartmentsQueryParams,
} from "@/lib/admin-api"
import { canPerformPermission, normalizePermissionLabels } from "@/components/app-sidebar"
import { env } from "@/lib/env"
import { AUTH_STORAGE_KEYS } from "@/utils/constants"
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"

const TOKEN_STORAGE_KEY = "hrms.admin.accessToken"

const DEFAULT_QUERY: Required<Omit<DepartmentsQueryParams, "status">> & {
  status: string
} = {
  page: 1,
  limit: 20,
  sortBy: "created_at",
  sortOrder: "DESC",
  search: "",
  status: "",
  branch_id: 0,
  parent_id: 0,
}

type DepartmentForm = {
  name: string
  description: string
  status: string
  branch_id: string
  parent_id: string
}

function readStoredToken() {
  if (typeof window === "undefined") {
    return ""
  }

  const authTokensRaw = window.localStorage.getItem(AUTH_STORAGE_KEYS.tokens)
  if (authTokensRaw) {
    try {
      const parsed = JSON.parse(authTokensRaw) as { accessToken?: string; access_token?: string }
      const accessToken = (parsed.accessToken ?? parsed.access_token ?? "").trim()
      if (accessToken) {
        return accessToken
      }
    } catch {
      // Fall through to legacy key.
    }
  }

  return window.localStorage.getItem(TOKEN_STORAGE_KEY)?.trim() ?? ""
}

function collectPermissionNames(value: unknown, sink: Set<string>) {
  if (typeof value === "string" && value.trim()) {
    sink.add(value.trim())
    return
  }

  if (Array.isArray(value)) {
    value.forEach((entry) => collectPermissionNames(entry, sink))
    return
  }

  if (typeof value !== "object" || value === null) {
    return
  }

  const record = value as Record<string, unknown>
  for (const key of ["permissions", "authorities", "actions", "scopes", "data", "items", "results", "user"]) {
    collectPermissionNames(record[key], sink)
  }
}

function readActorPermissions() {
  if (typeof window === "undefined") {
    return [] as string[]
  }

  const names = new Set<string>()

  try {
    const raw = window.sessionStorage.getItem("hrms.dashboard.actorPermissions")
    if (raw) {
      const parsed = JSON.parse(raw) as unknown
      if (Array.isArray(parsed)) {
        return normalizePermissionLabels(parsed.filter((entry) => typeof entry === "string"))
      }
    }
  } catch {
    // Fall through to local payload inspection.
  }

  for (const key of [AUTH_STORAGE_KEYS.user, AUTH_STORAGE_KEYS.tokens, "hrms.admin.user"]) {
    try {
      const raw = window.localStorage.getItem(key)
      if (!raw) continue
      collectPermissionNames(JSON.parse(raw) as unknown, names)
    } catch {
      // Ignore malformed local storage entries.
    }
  }

  return normalizePermissionLabels(Array.from(names))
}

function readString(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "string" && value.trim()) {
      return value
    }
  }
  return "-"
}

function readNumber(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "number" && Number.isFinite(value)) {
      return value
    }
    if (typeof value === "string" && value.trim()) {
      const parsed = Number(value)
      if (Number.isFinite(parsed)) {
        return parsed
      }
    }
  }
  return null
}

function emptyForm(): DepartmentForm {
  return {
    name: "",
    description: "",
    status: "active",
    branch_id: "",
    parent_id: "",
  }
}

export function DepartmentsView() {
  // Browser storage only — keep empty until after mount to avoid SSR hydration mismatch.
  const [actorPermissions, setActorPermissions] = React.useState<string[]>([])
  const [permissionsReady, setPermissionsReady] = React.useState(false)
  const canCreateDepartments = React.useMemo(
    () => permissionsReady && canPerformPermission(actorPermissions, "departments:create"),
    [actorPermissions, permissionsReady]
  )
  const canUpdateDepartments = React.useMemo(
    () => permissionsReady && canPerformPermission(actorPermissions, "departments:update"),
    [actorPermissions, permissionsReady]
  )
  const canDeleteDepartments = React.useMemo(
    () => permissionsReady && canPerformPermission(actorPermissions, "departments:delete"),
    [actorPermissions, permissionsReady]
  )
  const [query, setQuery] = React.useState(DEFAULT_QUERY)
  const [rows, setRows] = React.useState<AdminRecord[]>([])
  const [loading, setLoading] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [page, setPage] = React.useState(1)
  const [totalPages, setTotalPages] = React.useState<number | null>(null)
  const [total, setTotal] = React.useState<number | null>(null)

  const [openCreate, setOpenCreate] = React.useState(false)
  const [form, setForm] = React.useState<DepartmentForm>(emptyForm())
  const [editingId, setEditingId] = React.useState<number | null>(null)
  const [branches, setBranches] = React.useState<AdminRecord[]>([])
  const [allDepartments, setAllDepartments] = React.useState<AdminRecord[]>([])
  const [pendingDelete, setPendingDelete] = React.useState<AdminRecord | null>(null)
  const debouncedSearch = useDebouncedValue(query.search, 350)

  React.useEffect(() => {
    setActorPermissions(readActorPermissions())
    setPermissionsReady(true)
  }, [])

  const normalizedQuery = React.useMemo(
    () => ({
      ...query,
      search: debouncedSearch,
      status: query.status || undefined,
      branch_id: query.branch_id > 0 ? query.branch_id : undefined,
      parent_id: query.parent_id > 0 ? query.parent_id : undefined,
    }),
    [debouncedSearch, query]
  )

  const fetchDepartments = React.useCallback(async (signal?: AbortSignal) => {
    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      setRows([])
      return
    }

    setLoading(true)
    setError(null)
    try {
      const result = await listDepartments(
        token,
        {
          ...normalizedQuery,
          page,
        },
        {
          signal,
          cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_SHORT_MS,
        }
      )
      setRows(result.rows)
      setTotalPages(result.totalPages)
      setTotal(result.total)
    } catch (errorObject) {
      if (signal?.aborted) {
        return
      }
      setRows([])
      setTotalPages(null)
      setTotal(null)
      setError(errorObject instanceof Error ? errorObject.message : "Failed to load departments.")
    } finally {
      if (!signal?.aborted) {
        setLoading(false)
      }
    }
  }, [normalizedQuery, page])

  React.useEffect(() => {
    const controller = new AbortController()
    void fetchDepartments(controller.signal)
    return () => controller.abort()
  }, [fetchDepartments])

  React.useEffect(() => {
    const token = readStoredToken()
    if (!token) {
      return
    }
    void listBranches(token, {
      page: 1,
      limit: 100,
      sortBy: "created_at",
      sortOrder: "DESC",
      status: "active",
    }, { cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_LONG_MS })
      .then((result) => setBranches(result.rows))
      .catch(() => setBranches([]))
  }, [])

  React.useEffect(() => {
    const token = readStoredToken()
    if (!token) {
      return
    }
    void listDepartments(token, {
      page: 1,
      limit: 100,
      sortBy: "created_at",
      sortOrder: "DESC",
    }, { cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_LONG_MS })
      .then((result) => setAllDepartments(result.rows))
      .catch(() => setAllDepartments([]))
  }, [])

  const canGoPrevious = page > 1 && !loading
  const canGoNext = !loading && (totalPages === null || page < totalPages)

  function fillFormFromRow(row: AdminRecord) {
    setForm({
      name: readString(row, ["name"]),
      description: readString(row, ["description"]),
      status: readString(row, ["status"]) === "-" ? "active" : readString(row, ["status"]),
      branch_id: String(readNumber(row, ["branch_id"]) ?? ""),
      parent_id: String(readNumber(row, ["parent_id"]) ?? ""),
    })
  }

  function branchName(branchId: number | null) {
    if (branchId === null) {
      return "-"
    }
    const match = branches.find((branch) => readNumber(branch, ["id"]) === branchId)
    if (!match) {
      return String(branchId)
    }
    return readString(match, ["name", "code"])
  }

  function departmentName(departmentId: number | null) {
    if (departmentId === null) {
      return "-"
    }
    const match = allDepartments.find((department) => readNumber(department, ["id"]) === departmentId)
    if (!match) {
      return String(departmentId)
    }
    return readString(match, ["name", "code"])
  }

  async function submitForm() {
    if (editingId === null && !canCreateDepartments) {
      setError("You do not have permission to create departments.")
      return
    }
    if (editingId !== null && !canUpdateDepartments) {
      setError("You do not have permission to update departments.")
      return
    }

    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      return
    }

    const payload: AdminRecord = {
      name: form.name.trim(),
      description: form.description.trim(),
      status: form.status || "active",
      branch_id: form.branch_id.trim() ? Number(form.branch_id) : 0,
      parent_id: form.parent_id.trim() ? Number(form.parent_id) : undefined,
    }

    setSaving(true)
    setError(null)
    try {
      if (editingId === null) {
        await createDepartment(token, payload)
      } else {
        await patchDepartment(token, editingId, payload)
      }
      setOpenCreate(false)
      setEditingId(null)
      setForm(emptyForm())
      await fetchDepartments()
    } catch (errorObject) {
      setError(errorObject instanceof Error ? errorObject.message : "Failed to save department.")
    } finally {
      setSaving(false)
    }
  }

  async function handleDelete(row: AdminRecord) {
    if (!canDeleteDepartments) {
      setError("You do not have permission to delete departments.")
      return
    }

    const token = readStoredToken()
    const id = readNumber(row, ["id"])
    if (!token || id === null) {
      return
    }

    setSaving(true)
    setError(null)
    try {
      await deleteDepartment(token, id)
      await fetchDepartments()
    } catch (errorObject) {
      setError(errorObject instanceof Error ? errorObject.message : "Failed to delete department.")
    } finally {
      setSaving(false)
    }
  }

  const departmentColumns: Column<AdminRecord>[] = [
    { key: "name", label: "Name", defaultWidth: 120, sortable: true, render: (r) => readString(r, ["name"]) },
    { key: "code", label: "Code", defaultWidth: 60, sortable: true, render: (r) => readString(r, ["code"]) },
    { key: "branch", label: "Branch", defaultWidth: 80, render: (r) => branchName(readNumber(r, ["branch_id"])) },
    { key: "parent", label: "Parent", defaultWidth: 80, render: (r) => departmentName(readNumber(r, ["parent_id"])) },
    { key: "status", label: "Status", defaultWidth: 60, sortable: true, render: (r) => readString(r, ["status"]) },
    {
      key: "actions",
      label: "Actions",
      defaultWidth: 60,
      sortable: false,
      render: (row) => {
        const id = readNumber(row, ["id"])
        return (
          <div className="flex justify-end gap-1 pr-1" onClick={(e) => e.stopPropagation()}>
            {canUpdateDepartments ? (
              <button
                type="button"
                className="admin-table-icon-button"
                onClick={() => {
                  fillFormFromRow(row)
                  setEditingId(id)
                  setOpenCreate(true)
                }}
                aria-label="Edit department"
                title="Edit department"
              >
                <Pencil className="size-4" />
              </button>
            ) : null}
            {canDeleteDepartments ? (
              <button
                type="button"
                className="admin-table-icon-button"
                data-variant="danger"
                disabled={saving}
                onClick={() => setPendingDelete(row)}
                aria-label="Delete department"
                title="Delete department"
              >
                <Trash2 className="size-4" />
              </button>
            ) : null}
          </div>
        )
      },
    },
  ]

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-1.5">
        <SearchToggleField
          className="min-w-0"
          placeholder="Search department"
          value={query.search}
          onChange={(value) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, search: value }))
          }}
        />
        <select
          className="h-8 min-w-[8rem] rounded-md border border-slate-300 bg-white px-2 text-xs text-slate-900"
          value={query.status}
          onChange={(event) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, status: event.target.value }))
          }}
          aria-label="Filter department status"
        >
          <option value="">All statuses</option>
          <option value="active">active</option>
          <option value="inactive">inactive</option>
        </select>
        <div className="ml-auto flex items-center gap-1.5">
          {canCreateDepartments ? (
            <button
              type="button"
              className="inline-flex h-8 items-center gap-1.5 rounded-md bg-slate-900 px-2.5 text-xs font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
              onClick={() => {
                setEditingId(null)
                setForm(emptyForm())
                setOpenCreate(true)
              }}
              aria-label="Add department"
              title="Add department"
            >
              <Plus className="size-3.5" />
              Add Department
            </button>
          ) : null}
          <button
            type="button"
            className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-slate-300 bg-white text-primary transition hover:bg-slate-50 disabled:opacity-60"
            onClick={() => void fetchDepartments()}
            disabled={loading}
            aria-label="Refresh"
            title="Refresh"
          >
            <RefreshCw className={`size-3.5 text-primary ${loading ? "animate-spin" : ""}`} />
          </button>
        </div>
      </div>

      {error ? <p className="text-sm text-rose-600">{error}</p> : null}

      <ResizableTable
        title="Department"
        data={rows}
        columns={departmentColumns}
        itemsPerPage={20}
        loading={loading}
        storageKey="departments"
      />

      {openCreate ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-2xl rounded-lg border border-slate-200 bg-white p-4 shadow-lg">
            <h3 className="text-lg font-semibold text-slate-900">{editingId === null ? "Add" : "Edit"} Department</h3>
            <div className="mt-3 grid gap-3 md:grid-cols-2">
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Name</span>
                <input className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.name} onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Branch</span>
                <select
                  className="h-10 rounded-md border border-slate-300 px-3 text-sm"
                  value={form.branch_id}
                  onChange={(event) => setForm((prev) => ({ ...prev, branch_id: event.target.value }))}
                >
                  <option value="">Select branch</option>
                  {branches.map((branch) => {
                    const id = readNumber(branch, ["id"])
                    if (id === null) {
                      return null
                    }
                    return (
                      <option key={id} value={String(id)}>
                        {readString(branch, ["name"])}
                      </option>
                    )
                  })}
                </select>
              </label>
              <label className="grid gap-1 md:col-span-2">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Description</span>
                <Textarea className="min-h-20 rounded-md border border-slate-300 px-3 py-2 text-sm" value={form.description} onChange={(event) => setForm((prev) => ({ ...prev, description: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Status</span>
                <select className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.status} onChange={(event) => setForm((prev) => ({ ...prev, status: event.target.value }))}>
                  <option value="active">active</option>
                  <option value="inactive">inactive</option>
                </select>
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Parent Department</span>
                <select
                  className="h-10 rounded-md border border-slate-300 px-3 text-sm"
                  value={form.parent_id}
                  onChange={(event) => setForm((prev) => ({ ...prev, parent_id: event.target.value }))}
                >
                  <option value="">No parent</option>
                  {allDepartments
                    .filter((department) => {
                      const id = readNumber(department, ["id"])
                      return id !== null && (editingId === null || id !== editingId)
                    })
                    .map((department) => {
                      const id = readNumber(department, ["id"])
                      if (id === null) {
                        return null
                      }
                      return (
                        <option key={id} value={String(id)}>
                          {readString(department, ["name"])}
                        </option>
                      )
                    })}
                </select>
              </label>
            </div>
            <div className="mt-4 flex justify-end gap-2">
              <button type="button" className="rounded-md border border-slate-300 px-3 py-2 text-sm" onClick={() => setOpenCreate(false)}>
                Cancel
              </button>
              <button type="button" className="rounded-md bg-slate-900 px-3 py-2 text-sm font-medium text-white" disabled={saving} onClick={() => void submitForm()}>
                {saving ? "Saving..." : "Save"}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <AlertDialog
        open={Boolean(pendingDelete)}
        onOpenChange={(open) => {
          if (!open) {
            setPendingDelete(null)
          }
        }}
      >
        <AlertDialogContent className="max-w-md">
          <AlertDialogHeader>
            <AlertDialogTitle>Confirm Delete</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this department? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <button
              type="button"
              disabled={saving || !pendingDelete}
              className="rounded-md bg-[hsl(358,82%,59%)] px-3 py-2 text-sm font-medium text-white hover:brightness-95 disabled:cursor-not-allowed disabled:opacity-60"
              onClick={async () => {
                if (!pendingDelete) {
                  return
                }
                const row = pendingDelete
                setPendingDelete(null)
                await handleDelete(row)
              }}
            >
              {saving ? "Deleting..." : "Delete"}
            </button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

"use client"

import * as React from "react"
import { Pencil, Plus, RefreshCw, Trash2 } from "lucide-react"
import { SearchToggleField } from "@/components/common/search-toggle-field"
import { ResizableTable, type Column } from "@/components/ui/resizable-table"
import { Textarea } from "@/components/ui/textarea"
import { useDebouncedValue } from "@/hooks/use-debounced-value"

import {
  createDesignation,
  deleteDesignation,
  listDepartments,
  listDesignations,
  patchDesignation,
  type AdminRecord,
  type DesignationsQueryParams,
} from "@/lib/admin-api"
import { canPerformPermission, normalizePermissionLabels } from "@/components/app-sidebar"
import { env } from "@/lib/env"
import { AUTH_STORAGE_KEYS } from "@/utils/constants"
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"

const TOKEN_STORAGE_KEY = "hrms.admin.accessToken"

const DEFAULT_QUERY: Required<Omit<DesignationsQueryParams, "status" | "department_id">> & {
  status: string
  department_id: number
} = {
  page: 1,
  limit: 20,
  sortBy: "created_at",
  sortOrder: "DESC",
  search: "",
  status: "",
  department_id: 0,
}

type DesignationForm = {
  name: string
  code: string
  description: string
  status: string
  department_id: string
  hierarchy_level: string
  grade_level: string
  is_managerial: string
}

function readStoredToken() {
  if (typeof window === "undefined") {
    return ""
  }

  const authTokensRaw = window.localStorage.getItem(AUTH_STORAGE_KEYS.tokens)
  if (authTokensRaw) {
    try {
      const parsed = JSON.parse(authTokensRaw) as { accessToken?: string; access_token?: string }
      const accessToken = (parsed.accessToken ?? parsed.access_token ?? "").trim()
      if (accessToken) {
        return accessToken
      }
    } catch {
      // Fall through to legacy key.
    }
  }

  return window.localStorage.getItem(TOKEN_STORAGE_KEY)?.trim() ?? ""
}

function collectPermissionNames(value: unknown, sink: Set<string>) {
  if (typeof value === "string" && value.trim()) {
    sink.add(value.trim())
    return
  }

  if (Array.isArray(value)) {
    value.forEach((entry) => collectPermissionNames(entry, sink))
    return
  }

  if (typeof value !== "object" || value === null) {
    return
  }

  const record = value as Record<string, unknown>
  for (const key of ["permissions", "authorities", "actions", "scopes", "data", "items", "results", "user"]) {
    collectPermissionNames(record[key], sink)
  }
}

function readActorPermissions() {
  if (typeof window === "undefined") {
    return [] as string[]
  }

  const names = new Set<string>()

  try {
    const raw = window.sessionStorage.getItem("hrms.dashboard.actorPermissions")
    if (raw) {
      const parsed = JSON.parse(raw) as unknown
      if (Array.isArray(parsed)) {
        return normalizePermissionLabels(parsed.filter((entry) => typeof entry === "string"))
      }
    }
  } catch {
    // Fall through to local payload inspection.
  }

  for (const key of [AUTH_STORAGE_KEYS.user, AUTH_STORAGE_KEYS.tokens, "hrms.admin.user"]) {
    try {
      const raw = window.localStorage.getItem(key)
      if (!raw) continue
      collectPermissionNames(JSON.parse(raw) as unknown, names)
    } catch {
      // Ignore malformed local storage entries.
    }
  }

  return normalizePermissionLabels(Array.from(names))
}

function readString(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "string" && value.trim()) {
      return value
    }
  }
  return "-"
}

function readNumber(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "number" && Number.isFinite(value)) {
      return value
    }
    if (typeof value === "string" && value.trim()) {
      const parsed = Number(value)
      if (Number.isFinite(parsed)) {
        return parsed
      }
    }
  }
  return null
}

function readBoolean(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "boolean") {
      return value
    }
    if (typeof value === "string") {
      if (value.toLowerCase() === "true") {
        return true
      }
      if (value.toLowerCase() === "false") {
        return false
      }
    }
  }
  return false
}

function emptyForm(): DesignationForm {
  return {
    name: "",
    code: "",
    description: "",
    status: "active",
    department_id: "",
    hierarchy_level: "0",
    grade_level: "0",
    is_managerial: "false",
  }
}

export function DesignationsView() {
  // Browser storage only — keep empty until after mount to avoid SSR hydration mismatch.
  const [actorPermissions, setActorPermissions] = React.useState<string[]>([])
  const [permissionsReady, setPermissionsReady] = React.useState(false)
  const canCreateDesignations = React.useMemo(
    () => permissionsReady && canPerformPermission(actorPermissions, "designations:create"),
    [actorPermissions, permissionsReady]
  )
  const canUpdateDesignations = React.useMemo(
    () => permissionsReady && canPerformPermission(actorPermissions, "designations:update"),
    [actorPermissions, permissionsReady]
  )
  const canDeleteDesignations = React.useMemo(
    () => permissionsReady && canPerformPermission(actorPermissions, "designations:delete"),
    [actorPermissions, permissionsReady]
  )
  const [query, setQuery] = React.useState(DEFAULT_QUERY)
  const [rows, setRows] = React.useState<AdminRecord[]>([])
  const [departments, setDepartments] = React.useState<AdminRecord[]>([])
  const [loading, setLoading] = React.useState(false)
  const [saving, setSaving] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [page, setPage] = React.useState(1)
  const [totalPages, setTotalPages] = React.useState<number | null>(null)
  const [total, setTotal] = React.useState<number | null>(null)

  const [openForm, setOpenForm] = React.useState(false)
  const [form, setForm] = React.useState<DesignationForm>(emptyForm())
  const [editingId, setEditingId] = React.useState<number | null>(null)
  const [pendingDelete, setPendingDelete] = React.useState<AdminRecord | null>(null)
  const debouncedSearch = useDebouncedValue(query.search, 350)

  React.useEffect(() => {
    setActorPermissions(readActorPermissions())
    setPermissionsReady(true)
  }, [])

  const normalizedQuery = React.useMemo(
    () => ({
      ...query,
      search: debouncedSearch,
      status: query.status || undefined,
      department_id: query.department_id > 0 ? query.department_id : undefined,
    }),
    [debouncedSearch, query]
  )

  const fetchDesignations = React.useCallback(async (signal?: AbortSignal) => {
    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      setRows([])
      return
    }

    setLoading(true)
    setError(null)
    try {
      const result = await listDesignations(
        token,
        {
          ...normalizedQuery,
          page,
        },
        {
          signal,
          cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_SHORT_MS,
        }
      )
      setRows(result.rows)
      setTotalPages(result.totalPages)
      setTotal(result.total)
    } catch (errorObject) {
      if (signal?.aborted) {
        return
      }
      setRows([])
      setTotalPages(null)
      setTotal(null)
      setError(errorObject instanceof Error ? errorObject.message : "Failed to load designations.")
    } finally {
      if (!signal?.aborted) {
        setLoading(false)
      }
    }
  }, [normalizedQuery, page])

  React.useEffect(() => {
    const controller = new AbortController()
    void fetchDesignations(controller.signal)
    return () => controller.abort()
  }, [fetchDesignations])

  React.useEffect(() => {
    const token = readStoredToken()
    if (!token) {
      return
    }
    void listDepartments(token, {
      page: 1,
      limit: 100,
      sortBy: "created_at",
      sortOrder: "DESC",
    }, { cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_LONG_MS })
      .then((result) => setDepartments(result.rows))
      .catch(() => setDepartments([]))
  }, [])

  const canGoPrevious = page > 1 && !loading
  const canGoNext = !loading && (totalPages === null || page < totalPages)

  function fillFormFromRow(row: AdminRecord) {
    setForm({
      name: readString(row, ["name"]),
      code: readString(row, ["code"]),
      description: readString(row, ["description"]),
      status: readString(row, ["status"]) === "-" ? "active" : readString(row, ["status"]),
      department_id: String(readNumber(row, ["department_id"]) ?? ""),
      hierarchy_level: String(readNumber(row, ["hierarchy_level"]) ?? 0),
      grade_level: String(readNumber(row, ["grade_level"]) ?? 0),
      is_managerial: String(readBoolean(row, ["is_managerial"])),
    })
  }

  function departmentName(departmentId: number | null) {
    if (departmentId === null) {
      return "-"
    }
    const match = departments.find((department) => readNumber(department, ["id"]) === departmentId)
    if (!match) {
      return String(departmentId)
    }
    return readString(match, ["name", "code"])
  }

  async function submitForm() {
    if (editingId === null && !canCreateDesignations) {
      setError("You do not have permission to create designations.")
      return
    }
    if (editingId !== null && !canUpdateDesignations) {
      setError("You do not have permission to update designations.")
      return
    }

    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      return
    }

    const payload: AdminRecord = {
      name: form.name.trim(),
      code: form.code.trim(),
      description: form.description.trim(),
      status: form.status || "active",
      department_id: form.department_id.trim() ? Number(form.department_id) : 0,
      hierarchy_level: Number(form.hierarchy_level || "0"),
      grade_level: Number(form.grade_level || "0"),
      is_managerial: form.is_managerial === "true",
    }

    setSaving(true)
    setError(null)
    try {
      if (editingId === null) {
        await createDesignation(token, payload)
      } else {
        await patchDesignation(token, editingId, payload)
      }
      setOpenForm(false)
      setEditingId(null)
      setForm(emptyForm())
      await fetchDesignations()
    } catch (errorObject) {
      setError(errorObject instanceof Error ? errorObject.message : "Failed to save designation.")
    } finally {
      setSaving(false)
    }
  }

  async function handleDelete(row: AdminRecord) {
    if (!canDeleteDesignations) {
      setError("You do not have permission to delete designations.")
      return
    }

    const token = readStoredToken()
    const id = readNumber(row, ["id"])
    if (!token || id === null) {
      return
    }

    setSaving(true)
    setError(null)
    try {
      await deleteDesignation(token, id)
      await fetchDesignations()
    } catch (errorObject) {
      setError(errorObject instanceof Error ? errorObject.message : "Failed to delete designation.")
    } finally {
      setSaving(false)
    }
  }

  const designationColumns: Column<AdminRecord>[] = [
    { key: "name", label: "Name", defaultWidth: 100, sortable: true, render: (r) => readString(r, ["name"]) },
    { key: "code", label: "Code", defaultWidth: 50, sortable: true, render: (r) => readString(r, ["code"]) },
    { key: "department", label: "Dept", defaultWidth: 75, render: (r) => departmentName(readNumber(r, ["department_id"])) },
    { key: "hierarchy", label: "Hier", defaultWidth: 45, sortable: true, render: (r) => String(readNumber(r, ["hierarchy_level"]) ?? "-") },
    { key: "grade", label: "Grade", defaultWidth: 40, sortable: true, render: (r) => String(readNumber(r, ["grade_level"]) ?? "-") },
    { key: "managerial", label: "Mgr", defaultWidth: 45, render: (r) => (readBoolean(r, ["is_managerial"]) ? "Y" : "N") },
    { key: "status", label: "Status", defaultWidth: 50, sortable: true, render: (r) => readString(r, ["status"]) },
    {
      key: "actions",
      label: "Act",
      defaultWidth: 55,
      sortable: false,
      render: (row) => {
        const id = readNumber(row, ["id"])
        return (
          <div className="flex justify-end gap-1 pr-1" onClick={(e) => e.stopPropagation()}>
            {canUpdateDesignations ? (
              <button
                type="button"
                className="admin-table-icon-button"
                onClick={() => {
                  fillFormFromRow(row)
                  setEditingId(id)
                  setOpenForm(true)
                }}
                aria-label="Edit designation"
                title="Edit designation"
              >
                <Pencil className="size-4" />
              </button>
            ) : null}
            {canDeleteDesignations ? (
              <button
                type="button"
                className="admin-table-icon-button"
                data-variant="danger"
                disabled={saving}
                onClick={() => setPendingDelete(row)}
                aria-label="Delete designation"
                title="Delete designation"
              >
                <Trash2 className="size-4" />
              </button>
            ) : null}
          </div>
        )
      },
    },
  ]

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-1.5">
        <SearchToggleField
          className="min-w-0"
          placeholder="Search designation"
          value={query.search}
          onChange={(value) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, search: value }))
          }}
        />
        <select
          className="h-8 min-w-[8rem] rounded-md border border-slate-300 bg-white px-2 text-xs text-slate-900"
          value={query.status}
          onChange={(event) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, status: event.target.value }))
          }}
          aria-label="Filter designation status"
        >
          <option value="">All statuses</option>
          <option value="active">active</option>
          <option value="inactive">inactive</option>
        </select>
        <select
          className="h-8 min-w-[9rem] max-w-[12rem] rounded-md border border-slate-300 bg-white px-2 text-xs text-slate-900"
          value={query.department_id === 0 ? "" : String(query.department_id)}
          onChange={(event) => {
            setPage(1)
            setQuery((previous) => ({
              ...previous,
              department_id: event.target.value ? Number(event.target.value) : 0,
            }))
          }}
          aria-label="Filter by department"
        >
          <option value="">All departments</option>
          {departments.map((department) => {
            const id = readNumber(department, ["id"])
            if (id === null) {
              return null
            }
            return (
              <option key={id} value={String(id)}>
                {readString(department, ["name"])}
              </option>
            )
          })}
        </select>
        <div className="ml-auto flex items-center gap-1.5">
          {canCreateDesignations ? (
            <button
              type="button"
              className="inline-flex h-8 items-center gap-1.5 rounded-md bg-slate-900 px-2.5 text-xs font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
              onClick={() => {
                setEditingId(null)
                setForm(emptyForm())
                setOpenForm(true)
              }}
              aria-label="Add designation"
              title="Add designation"
            >
              <Plus className="size-3.5" />
              Add Designation
            </button>
          ) : null}
          <button
            type="button"
            className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-slate-300 bg-white text-primary transition hover:bg-slate-50 disabled:opacity-60"
            onClick={() => void fetchDesignations()}
            disabled={loading}
            aria-label="Refresh"
            title="Refresh"
          >
            <RefreshCw className={`size-3.5 text-primary ${loading ? "animate-spin" : ""}`} />
          </button>
        </div>
      </div>

      {error ? <p className="text-sm text-rose-600">{error}</p> : null}

      <ResizableTable
        title="Designation"
        data={rows}
        columns={designationColumns}
        itemsPerPage={20}
        loading={loading}
        storageKey="designations"
      />

      {openForm ? (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4">
          <div className="w-full max-w-2xl rounded-lg border border-slate-200 bg-white p-4 shadow-lg">
            <h3 className="text-lg font-semibold text-slate-900">{editingId === null ? "Add" : "Edit"} Designation</h3>
            <div className="mt-3 grid gap-3 md:grid-cols-2">
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Name</span>
                <input className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.name} onChange={(event) => setForm((prev) => ({ ...prev, name: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Code</span>
                <input className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.code} onChange={(event) => setForm((prev) => ({ ...prev, code: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Department</span>
                <select className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.department_id} onChange={(event) => setForm((prev) => ({ ...prev, department_id: event.target.value }))}>
                  <option value="">Select department</option>
                  {departments.map((department) => {
                    const id = readNumber(department, ["id"])
                    if (id === null) {
                      return null
                    }
                    return (
                      <option key={id} value={String(id)}>
                        {readString(department, ["name"])}
                      </option>
                    )
                  })}
                </select>
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Hierarchy Level</span>
                <input type="number" min={0} className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.hierarchy_level} onChange={(event) => setForm((prev) => ({ ...prev, hierarchy_level: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Grade Level</span>
                <input type="number" min={0} className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.grade_level} onChange={(event) => setForm((prev) => ({ ...prev, grade_level: event.target.value }))} />
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Managerial</span>
                <select className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.is_managerial} onChange={(event) => setForm((prev) => ({ ...prev, is_managerial: event.target.value }))}>
                  <option value="false">No</option>
                  <option value="true">Yes</option>
                </select>
              </label>
              <label className="grid gap-1">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Status</span>
                <select className="h-10 rounded-md border border-slate-300 px-3 text-sm" value={form.status} onChange={(event) => setForm((prev) => ({ ...prev, status: event.target.value }))}>
                  <option value="active">active</option>
                  <option value="inactive">inactive</option>
                </select>
              </label>
              <label className="grid gap-1 md:col-span-2">
                <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Description</span>
                <Textarea className="min-h-20 rounded-md border border-slate-300 px-3 py-2 text-sm" value={form.description} onChange={(event) => setForm((prev) => ({ ...prev, description: event.target.value }))} />
              </label>
            </div>
            <div className="mt-4 flex justify-end gap-2">
              <button type="button" className="rounded-md border border-slate-300 px-3 py-2 text-sm" onClick={() => setOpenForm(false)}>
                Cancel
              </button>
              <button type="button" className="rounded-md bg-slate-900 px-3 py-2 text-sm font-medium text-white" disabled={saving} onClick={() => void submitForm()}>
                {saving ? "Saving..." : "Save"}
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <AlertDialog
        open={Boolean(pendingDelete)}
        onOpenChange={(open) => {
          if (!open) {
            setPendingDelete(null)
          }
        }}
      >
        <AlertDialogContent className="max-w-md">
          <AlertDialogHeader>
            <AlertDialogTitle>Confirm Delete</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this designation? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <button
              type="button"
              disabled={saving || !pendingDelete}
              className="rounded-md bg-[hsl(358,82%,59%)] px-3 py-2 text-sm font-medium text-white hover:brightness-95 disabled:cursor-not-allowed disabled:opacity-60"
              onClick={async () => {
                if (!pendingDelete) {
                  return
                }
                const row = pendingDelete
                setPendingDelete(null)
                await handleDelete(row)
              }}
            >
              {saving ? "Deleting..." : "Delete"}
            </button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

