                              <span className={dob ? "text-foreground" : "text-muted-foreground"}>
                                {dob ? dob.toLocaleDateString() : "Select date from calendar"}
                              </span>
                            </PopoverTrigger>
                            <PopoverContent className="w-auto p-0" align="start">
