              const timeRange = !shift || isOffDay
                ? "—"
                : `${formatTimeValue(shift.start_time)} to ${formatTimeValue(shift.end_time)}`
              const expectedWork = isOffDay ? "—" : formatMinutesDuration(shift?.expected_work_minutes)

