  type LeaveBalancesResponse = {
    rows: AdminRecord[]
    current_fiscal_year?: string
    totals?: Record<string, number>
  }

  const { loading: loadingProfile, error: profileError, token, employee } = useSelfEmployeeData()
  const [loading, setLoading] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [leaveTypesError, setLeaveTypesError] = React.useState<string | null>(null)
  const [balancesError, setBalancesError] = React.useState<string | null>(null)
  const [holidaysError, setHolidaysError] = React.useState<string | null>(null)
  const [policiesError, setPoliciesError] = React.useState<string | null>(null)
  const [leaveTypes, setLeaveTypes] = React.useState<AdminRecord[]>([])
  const [requests, setRequests] = React.useState<AdminRecord[]>([])
  const [balances, setBalances] = React.useState<AdminRecord[]>([])
  const [leaveBalancesFull, setLeaveBalancesFull] = React.useState<LeaveBalancesResponse | null>(null)
  const [holidays, setHolidays] = React.useState<AdminRecord[]>([])
  const [policies, setPolicies] = React.useState<AdminRecord[]>([])
  const [message, setMessage] = React.useState<string | null>(null)
  const [requestDialogOpen, setRequestDialogOpen] = React.useState(false)
  const [cancelDialogOpen, setCancelDialogOpen] = React.useState(false)
  const [requestToCancel, setRequestToCancel] = React.useState<number | string | null>(null)
  const [cancelReason, setCancelReason] = React.useState("")

  const [requestForm, setRequestForm] = React.useState({
    leave_type_id: "",
    start_date: "",
    end_date: "",
    reason: "",
  })

  const employeeId = readNumber(employee, ["id", "employee_id"])
  const activeTab = tab

  const availableLeaveTypes = React.useMemo(() => {
    const options = new Map<string, { id: string; label: string }>()

    const addOption = (idValue: unknown, labelValue: unknown) => {
      const id = readNumberish(idValue)
      const label = typeof labelValue === "string" ? labelValue.trim() : ""
      if (id === null || !label) {
        return
      }
      options.set(String(id), { id: String(id), label })
    }

    leaveTypes.forEach((row) => {
      addOption(row.id ?? row.leave_type_id, readString(row, ["name", "code"], ""))
    })

    balances.forEach((row) => {
      const leaveType = asRecord(row.leave_type)
      addOption(leaveType?.id ?? row.leave_type_id, readString(leaveType, ["name", "code"], ""))
    })

    requests.forEach((row) => {
      const leaveType = asRecord(row.leave_type)
      addOption(leaveType?.id ?? row.leave_type_id, readString(leaveType, ["name", "code"], ""))
    })

    policies.forEach((row) => {
      const policyTypes = Array.isArray(row.leave_types) ? row.leave_types : []
      policyTypes.forEach((entry) => {
        const policyType = asRecord(entry)
        const leaveType = asRecord(policyType?.leave_type)
        addOption(leaveType?.id ?? policyType?.leave_type_id, readString(leaveType, ["name", "code"], ""))
      })
    })

    return Array.from(options.values())
  }, [balances, leaveTypes, policies, requests])

  const leaveTypeLabelById = React.useMemo(() => {
    const labels = new Map<string, string>()

    leaveTypes.forEach((row) => {
      const id = readNumberish(row.id ?? row.leave_type_id)
      const label =
        readString(asRecord(row.leave_type), ["name", "display_name", "code"], "") ||
        readString(row, ["name", "display_name", "code"], "")

      if (id !== null && label) {
        labels.set(String(id), label)
      }
    })

    return labels
  }, [leaveTypes])

  const balanceTotals = React.useMemo(() => {
    const totals = leaveBalancesFull?.totals
    return [
      {
        label: "Allocated",
        value: readLeaveTotalsValue(totals, ["allocated_days", "allocated"]),
      },
      {
        label: "Used",
        value: readLeaveTotalsValue(totals, ["used_days", "used"]),
      },
      {
        label: "Pending",
        value: readLeaveTotalsValue(totals, ["pending_days", "pending"]),
      },
      {
        label: "Carried Forward",
        value: readLeaveTotalsValue(totals, ["carried_forward_days", "carried_forward"]),
      },
      {
        label: "Expired",
        value: readLeaveTotalsValue(totals, ["expired_days", "expired"]),
      },
      {
        label: "Available",
        value: readLeaveTotalsValue(totals, ["available_days", "available", "remaining_days", "remaining"]),
      },
    ]
  }, [leaveBalancesFull?.totals])

  const selectedLeaveTypeLabel = React.useMemo(() => {
    if (!requestForm.leave_type_id) {
      return ""
    }
    return availableLeaveTypes.find((item) => item.id === requestForm.leave_type_id)?.label ?? ""
  }, [availableLeaveTypes, requestForm.leave_type_id])

  const readEndpointError = React.useCallback(
    (errorObject: unknown, fallbackMessage: string) => {
      const message = errorObject instanceof Error ? errorObject.message : fallbackMessage
      const status =
        typeof errorObject === "object" && errorObject !== null && "status" in errorObject
          ? (errorObject as { status?: number }).status
          : undefined

      if (status === 403) {
        return SELF_SERVICE_UNAVAILABLE_MESSAGE
      }

      return message
    },
    []
  )

  const loadData = React.useCallback(async () => {
    if (!token || employeeId === null) {
      return
    }

    setLoading(true)
    setError(null)
    setLeaveTypesError(null)
    setBalancesError(null)
    setHolidaysError(null)
    setPoliciesError(null)

    try {
      if (activeTab === "requests") {
        const [requestsResult, typesResult] = await Promise.allSettled([
          listMyLeaveRequests(token, {
            page: 1,
            limit: 100,
            sortBy: "created_at",
            sortOrder: "DESC",
          }),
          listLeaveTypes(token, { page: 1, limit: 100 }),
        ])

        if (requestsResult.status === "fulfilled") {
          setRequests(requestsResult.value.rows)
        } else {
          setRequests([])
          setError(readEndpointError(requestsResult.reason, "Failed to load leave requests."))
        }

        if (typesResult.status === "fulfilled") {
          setLeaveTypes(typesResult.value.rows)
        } else {
          setLeaveTypes([])
          setLeaveTypesError(readEndpointError(typesResult.reason, "Failed to load leave types."))
        }
      }

      if (activeTab === "balances") {
        const [balancesResult, typesResult] = await Promise.allSettled([
          listMyLeaveBalances(token, { page: 1, limit: 100 }),
          listLeaveTypes(token, { page: 1, limit: 100 }),
        ])

        if (balancesResult.status === "fulfilled") {
          setBalances(balancesResult.value.rows)
          setLeaveBalancesFull(balancesResult.value)
        } else {
          throw balancesResult.reason
        }

        if (typesResult.status === "fulfilled") {
          setLeaveTypes(typesResult.value.rows)
          setLeaveTypesError(null)
        } else {
          setLeaveTypes([])
          setLeaveTypesError(readEndpointError(typesResult.reason, "Failed to load leave types."))
        }
      }

      if (activeTab === "holidays") {
        const holidaysResult = await listAttendanceHolidays(token, { page: 1, limit: 365 })
        setHolidays(holidaysResult.rows)
      }

      if (activeTab === "policies") {
        const policiesResult = await listLeavePolicies(token, { page: 1, limit: 100 })
        setPolicies(policiesResult.rows)
      }
    } catch (errorObject) {
      if (activeTab === "balances") {
        setBalances([])
        setLeaveBalancesFull(null)
        setBalancesError(readEndpointError(errorObject, "Failed to load leave balances."))
      } else if (activeTab === "holidays") {
        setHolidays([])
        setHolidaysError(readEndpointError(errorObject, "Failed to load holiday calendar."))
      } else if (activeTab === "policies") {
        setPolicies([])
        setPoliciesError(readEndpointError(errorObject, "Failed to load leave policies."))
      } else {
        setError(readEndpointError(errorObject, "Failed to load leave data."))
      }
    } finally {
      setLoading(false)
    }
  }, [activeTab, employeeId, readEndpointError, token])

  React.useEffect(() => {
    void loadData()
  }, [loadData])

  const onRequestLeave = async (submit: boolean) => {
    if (!token || employeeId === null) {
      setMessage("Your profile is not ready for leave requests.")
      return
    }

    if (!requestForm.leave_type_id || !requestForm.start_date || !requestForm.end_date) {
      setMessage("Leave type and dates are required.")
      return
    }

    if (submit && !requestForm.reason.trim()) {
      setMessage("A reason is required before submitting the request.")
      return
    }

    if (availableLeaveTypes.length === 0) {
      setMessage("Leave requests cannot be created until leave types are available to your account.")
      return
    }

    setLoading(true)
    setMessage(null)

    try {
      await createMyLeaveRequest(token, {
        leave_type_id: Number(requestForm.leave_type_id),
        start_date: requestForm.start_date ? `${requestForm.start_date}T00:00:00` : "",
        end_date: requestForm.end_date ? `${requestForm.end_date}T00:00:00` : "",
        reason: requestForm.reason.trim(),
        submit,
      })
      setRequestForm({ leave_type_id: "", start_date: "", end_date: "", reason: "" })
      setMessage(submit ? "Leave request submitted." : "Leave request saved as a draft.")
      setRequestDialogOpen(false)
      await loadData()
    } catch (errorObject) {
      const text =
        errorObject instanceof Error
          ? errorObject.message
          : submit
            ? "Failed to submit leave request."
            : "Failed to save draft."
      setMessage(text)
    } finally {
      setLoading(false)
    }
  }

  const onCancelRequest = async (id: number | string, reason: string = "Cancelled by user") => {
    if (!token) return
    setLoading(true)
    setMessage(null)
    try {
      await cancelMyLeaveRequest(token, id, reason)
      setMessage("Leave request cancelled.")
      await loadData()
    } catch (errorObject) {
      const text = errorObject instanceof Error ? errorObject.message : "Failed to cancel request."
      setMessage(text)
    } finally {
      setLoading(false)
    }
  }

  const openCancelDialog = (id: number | string) => {
    setRequestToCancel(id)
    setCancelReason("")
    setCancelDialogOpen(true)
  }

  const onConfirmCancelRequest = async () => {
    if (requestToCancel === null) {
      return
    }
    await onCancelRequest(requestToCancel, cancelReason.trim() || "Cancelled by user")
    setCancelDialogOpen(false)
    setRequestToCancel(null)
    setCancelReason("")
  }

  const onDownloadPdf = async (id: number | string) => {
    if (!token) return
    try {
      const res = await fetch(`${API_BASE_URL}/api/me/leave/requests/${id}/pdf`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!res.ok) throw new Error("Failed to generate PDF")
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement("a")
      a.href = url
      a.download = `leave_request_${id}.pdf`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
    } catch (errorObject) {
      const text = errorObject instanceof Error ? errorObject.message : "Failed to download PDF."
      setMessage(text)
    }
  }

  const onSubmitRequest = async (id: number | string) => {
    if (!token) return
    setLoading(true)
    setMessage(null)
    try {
      await submitMyLeaveRequest(token, id)
      setMessage("Leave request submitted.")
      await loadData()
    } catch (errorObject) {
      const text = errorObject instanceof Error ? errorObject.message : "Failed to submit request."
      setMessage(text)
    } finally {
      setLoading(false)
    }
  }

  if (loadingProfile) {
    return (
      <div className="flex flex-col items-center justify-center gap-4 py-10">
        <LumaSpin />
        <p className="text-sm text-muted-foreground">Loading your profile...</p>
      </div>
    )
  }

  if (profileError) {
    return <div className="px-4 py-2 text-sm text-red-600">{profileError}</div>
  }

  if (employeeId === null) {
    return <div className="px-4 py-2 text-sm text-red-600">Employee profile not found.</div>
  }

  let tabContent: React.ReactNode = null
  if (activeTab === "requests") {
    tabContent = (
      <section className="space-y-4 px-4 py-2 lg:px-6">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <h2 className="text-3xl font-semibold tracking-tight text-foreground">My Requests</h2>
          {requests.length > 0 && (
            <div className="flex gap-2">
              <Button type="button" onClick={() => setRequestDialogOpen(true)} className="sm:hidden bg-primary text-white hover:bg-primary/90 !text-white">
                New Leave Request
              </Button>
              <Button type="button" onClick={() => setRequestDialogOpen(true)} className="hidden sm:inline-flex bg-primary text-white hover:bg-primary/90 !text-white">
                New Leave Request
              </Button>
            </div>
          )}
        </div>
        {requests.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 text-center">
            <p className="text-sm text-muted-foreground">No leave requests found.</p>
            <Button
              type="button"
              onClick={() => setRequestDialogOpen(true)}
              className="mt-6 bg-primary text-white hover:bg-primary/90 !text-white"
            >
              New Leave Request
            </Button>
          </div>
        ) : (
          <div className="space-y-2">
            {requests.map((row, index) => {
              const id = readNumber(row, ["id"])
              const status = readString(row, ["status"], "pending").toLowerCase()
              const canCancel = ["pending", "draft"].includes(status)
              const statusMeta = resolveLeaveStatusMeta(status)
              return (
                <div key={String(row.id ?? index)} className="relative overflow-hidden rounded-2xl p-4 text-white" style={{ backgroundColor: 'var(--primary)' }}>
                  <Doodle name="doodle-circles" />
                  <div className="relative z-10">
                    <div className="flex items-start justify-between gap-3">
                      <p className="font-medium">{readString(row, ["leave_no", "request_no", "reason"], "Request")}</p>
                      <Badge className={cn("border text-xs uppercase tracking-wide", statusMeta.badgeClassName)}>
                        {statusMeta.label}
                      </Badge>
                    </div>
                    <p className="text-white/80">{formatDate(row.start_date)} to {formatDate(row.end_date)}</p>
                    <p className="text-white/80">{statusMeta.helperText || `Status: ${readString(row, ["status"], "pending")}`}</p>
                    <p className="text-white/80">Leave Type: {readString(asRecord(row.leave_type), ["name"], "-")}</p>
                    <div className="mt-2 flex gap-2">
                      {id && (
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => void onDownloadPdf(id)}
                          disabled={loading}
                          className="border-primary bg-primary text-white hover:bg-primary/90 hover:text-white"
                        >
                          Download PDF
                        </Button>
                      )}
                      {id && canCancel && (
                        <Button variant="destructive" size="sm" onClick={() => openCancelDialog(id)} disabled={loading} className="!text-white">
                          Cancel
                        </Button>
                      )}
                      {id && status === "draft" && (
                        <Button size="sm" onClick={() => void onSubmitRequest(id)} disabled={loading} className="bg-white/20 text-white hover:bg-white/30">
                          Submit
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}
        {message ? <p className="text-sm text-muted-foreground">{message}</p> : null}
        {error ? <p className="text-sm text-red-600">{error}</p> : null}
      </section>
    )
  }
  if (activeTab === "balances") {
    const fiscalYear = leaveBalancesFull?.current_fiscal_year || "2026"
    const showBalancesError = balancesError && balancesError !== SELF_SERVICE_UNAVAILABLE_MESSAGE
    tabContent = (
      <section className="space-y-4 px-4 py-2 lg:px-6">
        <div className="space-y-1">
          <h2 className="text-2xl font-semibold tracking-tight text-foreground">Leave Balances</h2>
          <p className="text-sm text-muted-foreground">Fiscal Year: {fiscalYear}</p>
        </div>
        {loading ? (
          <div className="flex items-center gap-2 py-2">
            <LumaSpin />
            <p className="text-sm text-muted-foreground">Loading balances...</p>
          </div>
        ) : null}
        {!loading && balances.length === 0 ? <p className="text-sm text-slate-500">No balance records found.</p> : null}
        <div className="flex flex-wrap items-end gap-x-5 gap-y-2 border-b border-border/70 pb-3">
          {balanceTotals.map((item) => (
            <div key={item.label} className="min-w-[88px]">
              <p className="text-[10px] font-semibold uppercase tracking-[0.22em] text-muted-foreground">
                {item.label}
              </p>
              <p className="mt-0.5 text-lg font-semibold tracking-tight text-primary">
                {formatDayValue(item.value)}
              </p>
              <p className="text-[11px] text-muted-foreground">days</p>
            </div>
          ))}
        </div>
        <div className="space-y-2">
          {balances.map((row, index) => (
            <div key={String(row.id ?? index)} className="relative overflow-hidden rounded-2xl p-4 text-white" style={{ backgroundColor: 'var(--primary)' }}>
              <Doodle name="doodle-circles" />
              <div className="relative z-10">
                <p className="font-medium">
                  {(() => {
                    const nestedLeaveType = asRecord(row.leave_type)
                    const nestedLabel =
                      readString(nestedLeaveType, ["name", "display_name", "code"], "") ||
                      readString(row, ["leave_type_name", "leave_type_code"], "")

                    if (nestedLabel) {
                      return nestedLabel
                    }

                    const leaveTypeId = readNumberish(row.leave_type_id ?? nestedLeaveType?.id)
                    if (leaveTypeId !== null) {
                      return leaveTypeLabelById.get(String(leaveTypeId)) ?? `Leave type #${leaveTypeId}`
                    }

                    return "Leave type"
                  })()}
                </p>
                <p className="text-white/80">Fiscal Year: {readString(row, ["fiscal_year"], fiscalYear)}</p>
                <div className="mt-1 grid grid-cols-2 gap-2 text-xs text-white/80">
                  <div>Allocated: {String(row.allocated_days ?? "-")}</div>
                  <div>Used: {String(row.used_days ?? "-")}</div>
                  <div>Pending: {String(row.pending_days ?? "-")}</div>
                  <div>Available: {String(row.available_days ?? row.remaining_days ?? "-")}</div>
                </div>
              </div>
            </div>
          ))}
        </div>
        {showBalancesError ? <p className="text-sm text-slate-500">{balancesError}</p> : null}
        {error ? <p className="text-sm text-red-600">{error}</p> : null}
      </section>
    )
  }

  if (activeTab === "holidays") {
    const showHolidaysError = holidaysError && holidaysError !== SELF_SERVICE_UNAVAILABLE_MESSAGE
    const sortedHolidays = [...holidays].sort((left, right) => {
      const leftDate = readString(left, ["holiday_date", "from_date", "start_date", "date"], "")
      const rightDate = readString(right, ["holiday_date", "from_date", "start_date", "date"], "")
      return leftDate.localeCompare(rightDate)
    })
    tabContent = (
      <section className="space-y-4 px-4 py-2 lg:px-6">
        <div className="space-y-1">
          <h2 className="text-2xl font-semibold tracking-tight text-foreground">Holiday Calendar</h2>
          <p className="text-sm text-muted-foreground">Company holidays pulled from the attendance holiday calendar.</p>
        </div>
        {loading ? (
          <div className="flex flex-col items-center justify-center gap-2 py-4">
            <LumaSpin />
            <p className="text-sm text-muted-foreground">Loading holidays...</p>
          </div>
        ) : null}
        {!loading && sortedHolidays.length === 0 ? (
          <p className="text-sm text-slate-500">No holidays were returned by `/api/attendance/holidays`.</p>
        ) : null}
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {sortedHolidays.map((row, index) => {
            const holidayStart =
              readString(row, ["holiday_date", "from_date", "start_date", "date"], "") || "-"
            const holidayEnd = readString(row, ["to_date", "end_date"], "")
            const holidayType = readString(row, ["type", "holiday_type", "category"], "")
            const holidayBranch = readString(asRecord(row.branch), ["name", "branch_name"], "")
            const holidayDescription = readString(row, ["description", "notes", "remarks"], "")
            const dateLabel =
              holidayEnd && holidayEnd !== holidayStart
                ? `${formatDate(holidayStart)} - ${formatDate(holidayEnd)}`
                : formatDate(holidayStart)

            return (
              <div key={String(row.id ?? index)} className="relative overflow-hidden rounded-2xl p-4 text-white" style={{ backgroundColor: 'var(--primary)' }}>
                <Doodle name="doodle-circles" />
                <div className="relative z-10">
                  <div className="flex items-start justify-between gap-3">
                    <p className="font-medium">{readString(row, ["name", "title"], "Holiday")}</p>
                    {holidayType ? (
                      <span className="rounded-full bg-white/20 px-2.5 py-1 text-[11px] font-medium uppercase tracking-wide text-white/90">
                        {holidayType}
                      </span>
                    ) : null}
                  </div>
                  <p className="mt-2 text-white/80">{dateLabel}</p>
                  {holidayBranch ? <p className="mt-1 text-xs text-white/60">Branch: {holidayBranch}</p> : null}
                  {holidayDescription ? <p className="mt-2 text-xs text-white/60">{holidayDescription}</p> : null}
                </div>
              </div>
            )
          })}
        </div>
        {showHolidaysError ? <p className="text-sm text-slate-500">{holidaysError}</p> : null}
        {error ? <p className="text-sm text-red-600">{error}</p> : null}
      </section>
    )
  }

  if (activeTab === "policies") {
    const showPoliciesError = policiesError && policiesError !== SELF_SERVICE_UNAVAILABLE_MESSAGE
    tabContent = (
      <section className="space-y-4 px-4 py-2 lg:px-6">
        <h2 className="text-2xl font-semibold tracking-tight text-foreground">Leave Policies</h2>
        {loading ? (
          <div className="flex flex-col items-center justify-center gap-2 py-4">
            <LumaSpin />
            <p className="text-sm text-muted-foreground">Loading policies...</p>
          </div>
        ) : null}
        {!loading && policies.length === 0 ? <p className="text-sm text-slate-500">No leave policies found.</p> : null}
        <div className="space-y-2">
          {policies.map((row, index) => (
            <div key={String(row.id ?? index)} className="relative overflow-hidden rounded-2xl p-4 text-white" style={{ backgroundColor: 'var(--primary)' }}>
              <Doodle name="doodle-circles" />
              <div className="relative z-10">
                <p className="font-medium">{readString(row, ["name"], "Policy")}</p>
                <p className="text-white/80">Status: {readString(row, ["status"], "-")}</p>
                <p className="text-white/80">Accrual: {readString(row, ["accrual_method"], "-")}</p>
              </div>
            </div>
          ))}
        </div>
        {showPoliciesError ? <p className="text-sm text-slate-500">{policiesError}</p> : null}
        {error ? <p className="text-sm text-red-600">{error}</p> : null}
      </section>
    )
  }

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <DoodleSprites />
      <div className="flex-1 min-h-0 relative">
        {tabContent}
      </div>
      <Dialog open={requestDialogOpen} onOpenChange={setRequestDialogOpen}>
        <DialogPopup className="sm:max-w-xl">
          <DialogHeader>
            <DialogTitle>Request Leave</DialogTitle>
            <DialogDescription>Save a draft or submit a new leave request without leaving this page.</DialogDescription>
          </DialogHeader>
          <div className="grid gap-3">
            <div className="space-y-1">
              <Label>Leave Type</Label>
              <Select value={requestForm.leave_type_id} onValueChange={(value) => setRequestForm((prev) => ({ ...prev, leave_type_id: value ?? "" }))}>
                <SelectTrigger>
                  <SelectValue placeholder={availableLeaveTypes.length > 0 ? "Select leave type" : "No leave types available"}>
                    {selectedLeaveTypeLabel || undefined}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  {availableLeaveTypes.map((row) => (
                    <SelectItem key={row.id} value={row.id}>
                      {row.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {availableLeaveTypes.length === 0 && leaveTypesError ? <p className="text-xs text-slate-500">{leaveTypesError}</p> : null}
            </div>
            <div className="grid gap-3 sm:grid-cols-2">
              <div className="space-y-1">
                <Label>Start Date</Label>
                <Input type="date" value={requestForm.start_date} onChange={(event) => setRequestForm((prev) => ({ ...prev, start_date: event.target.value }))} />
              </div>
              <div className="space-y-1">
                <Label>End Date</Label>
                <Input type="date" value={requestForm.end_date} onChange={(event) => setRequestForm((prev) => ({ ...prev, end_date: event.target.value }))} />
              </div>
            </div>
            <div className="space-y-1">
              <Label>Reason</Label>
              <Textarea
                className="min-h-24"
                value={requestForm.reason}
                onChange={(event) => setRequestForm((prev) => ({ ...prev, reason: event.target.value }))}
              />
            </div>
            {message ? <p className="text-sm text-slate-700 dark:text-slate-300">{message}</p> : null}
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setRequestDialogOpen(false)}>
              Close
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={() => void onRequestLeave(false)}
              disabled={loading || availableLeaveTypes.length === 0}
            >
              Save Draft
            </Button>
            <Button type="button" onClick={() => void onRequestLeave(true)} disabled={loading || availableLeaveTypes.length === 0} className="bg-primary text-white hover:bg-primary/90 !text-white">
              Submit Request
            </Button>
          </DialogFooter>
        </DialogPopup>
      </Dialog>
      <Dialog open={cancelDialogOpen} onOpenChange={setCancelDialogOpen}>
        <DialogPopup className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>Cancel Leave Request</DialogTitle>
            <DialogDescription>Provide a short reason for cancelling this leave request.</DialogDescription>
          </DialogHeader>
          <div className="grid gap-2">
            <Label htmlFor="cancel-reason">Reason</Label>
            <Textarea
              id="cancel-reason"
              className="min-h-24"
              maxLength={2000}
              value={cancelReason}
              onChange={(event) => setCancelReason(event.target.value)}
            />
          </div>
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setCancelDialogOpen(false)
                setRequestToCancel(null)
                setCancelReason("")
              }}
            >
              Close
            </Button>
            <Button type="button" variant="destructive" onClick={() => void onConfirmCancelRequest()} disabled={loading}>
              Cancel Request
            </Button>
          </DialogFooter>
        </DialogPopup>
      </Dialog>
    </div>
  )
}

"use client"

import * as React from "react"
import { SearchToggleField } from "@/components/common/search-toggle-field"
import { useRouter } from "next/navigation"

import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { ResizableTable, type Column } from "@/components/ui/resizable-table"
import {
  EmployeeAccessRemovalDialog,
  type EmployeeAccessRemovalTarget,
} from "@/components/dashboard/employee-access-removal-dialog"
import { listEmployees, type AdminRecord, type EmployeesQueryParams } from "@/lib/admin-api"
import { useDebouncedValue } from "@/hooks/use-debounced-value"
import { useRenderDiagnostics } from "@/hooks/use-render-diagnostics"
import { AUTH_STORAGE_KEYS } from "@/utils/constants"
import { env } from "@/lib/env"
import { Trash2 } from "lucide-react"

const TOKEN_STORAGE_KEY = "hrms.admin.accessToken"
const EMPLOYEE_STATUS_REFRESH_KEY = "hrms.employees.status.updatedAt"
const EMPLOYEE_STATUS_REFRESH_EVENT = "hrms:employee-status-updated"
const EMPLOYEE_LIST_CACHE_PREFIX = "hrms.employees.list"
const EMPLOYEE_LIST_CACHE_TTL_MS = env.NEXT_PUBLIC_LIST_CACHE_TTL_LONG_MS
const DEFAULT_QUERY: Required<Omit<EmployeesQueryParams, "employment_status">> & {
  employment_status: "" | NonNullable<EmployeesQueryParams["employment_status"]>
} = {
  page: 1,
  limit: 20,
  sortBy: "created_at",
  sortOrder: "DESC",
  search: "",
  employment_status: "",
  branch_id: 0,
  department_id: 0,
  position_id: 0,
}

type EmployeeListSnapshot = {
  rows: AdminRecord[]
  totalPages: number | null
  total: number | null
  cachedAt: number
}

const employeeListSnapshotCache = new Map<string, EmployeeListSnapshot>()

function readStoredToken() {
  if (typeof window === "undefined") {
    return ""
  }

  // Prefer session tokens bag (same order as branches/departments) so restricted
  // company users don't hit a stale legacy access-token key.
  const authTokensRaw = window.localStorage.getItem(AUTH_STORAGE_KEYS.tokens)
  if (authTokensRaw) {
    try {
      const parsed = JSON.parse(authTokensRaw) as { accessToken?: string; access_token?: string }
      const accessToken = (parsed.accessToken ?? parsed.access_token ?? "").trim()
      if (accessToken) {
        return accessToken
      }
    } catch {
      // Fall through to legacy key.
    }
  }

  return window.localStorage.getItem(TOKEN_STORAGE_KEY)?.trim() ?? ""
}

function readString(row: AdminRecord, keys: string[]) {
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "string" && value.trim()) {
      return value
    }
  }
  return "-"
}

function asRecordArray(value: unknown): AdminRecord[] {
  if (!Array.isArray(value)) {
    return []
  }
  return value.filter((entry) => typeof entry === "object" && entry !== null) as AdminRecord[]
}

function asRecord(value: unknown): AdminRecord | null {
  return typeof value === "object" && value !== null ? (value as AdminRecord) : null
}

function readNestedName(value: unknown) {
  const record = asRecord(value)
  if (!record) {
    return "—"
  }
  return readString(record, ["name", "department_name", "departmentName", "position_name", "positionName"])
}

function formatEmployeeDate(value: string) {
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return value
  }

  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  }).format(parsed)
}



function employeeDisplayName(row: AdminRecord) {
  const named = readString(row, ["full_name", "fullName", "name"])
  if (named !== "-") {
    return named
  }
  const first = readString(row, ["first_name", "firstName"])
  const middle = readString(row, ["middle_name", "middleName"])
  const last = readString(row, ["last_name", "lastName"])
  return [first, middle, last].filter((part) => part !== "-").join(" ").trim() || "-"
}

const REQUIRED_PROFILE_ITEMS: Array<{ key: string; label: string }> = [
  { key: "contacts", label: "Contacts" },
  { key: "addresses", label: "Addresses" },
  { key: "relatives", label: "Relatives" },
  { key: "identifications", label: "Identifications" },
  { key: "bank_accounts", label: "Bank Accounts" },
  { key: "departments", label: "Departments" },
  { key: "academic_qualifications", label: "Academic Qualifications" },
  { key: "professional_qualifications", label: "Professional Qualifications" },
  { key: "experience_details", label: "Experience Details" },
  { key: "documents", label: "Documents" },
]

function employeeProfileHref(employeeNo: string, missingItemKey?: string) {
  const params = new URLSearchParams()
  if (missingItemKey) {
    params.set("missing", missingItemKey)
  }
  const query = params.toString()
  const basePath = `/dashboard/employees/profile/${encodeURIComponent(employeeNo)}`
  return query ? `${basePath}?${query}` : basePath
}

function missingProfileItems(row: AdminRecord) {
  return REQUIRED_PROFILE_ITEMS.filter((item) => asRecordArray(row[item.key]).length === 0)
}

function readSnapshot(cacheKey: string) {
  const inMemory = employeeListSnapshotCache.get(cacheKey)
  if (inMemory && Date.now() - inMemory.cachedAt < EMPLOYEE_LIST_CACHE_TTL_MS) {
    return inMemory
  }

  if (typeof window === "undefined") {
    return null
  }

  try {
    const raw = window.sessionStorage.getItem(`${EMPLOYEE_LIST_CACHE_PREFIX}:${cacheKey}`)
    if (!raw) {
      return null
    }
    const parsed = JSON.parse(raw) as EmployeeListSnapshot
    if (Date.now() - parsed.cachedAt > EMPLOYEE_LIST_CACHE_TTL_MS) {
      window.sessionStorage.removeItem(`${EMPLOYEE_LIST_CACHE_PREFIX}:${cacheKey}`)
      return null
    }
    employeeListSnapshotCache.set(cacheKey, parsed)
    return parsed
  } catch {
    return null
  }
}

function writeSnapshot(cacheKey: string, snapshot: EmployeeListSnapshot) {
  employeeListSnapshotCache.set(cacheKey, snapshot)

  if (typeof window === "undefined") {
    return
  }

  try {
    window.sessionStorage.setItem(
      `${EMPLOYEE_LIST_CACHE_PREFIX}:${cacheKey}`,
      JSON.stringify(snapshot)
    )
  } catch {}
}



export function EmployeesListView() {
  const router = useRouter()
  const [query, setQuery] = React.useState(DEFAULT_QUERY)
  const [rows, setRows] = React.useState<AdminRecord[]>([])
  const [loading, setLoading] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [page, setPage] = React.useState(1)
  const [totalPages, setTotalPages] = React.useState<number | null>(null)
  const [total, setTotal] = React.useState<number | null>(null)
  const [missingDialog, setMissingDialog] = React.useState<{ employeeNo: string; missing: Array<{ key: string; label: string }> } | null>(null)
  const [removalOpen, setRemovalOpen] = React.useState(false)
  const [removalTarget, setRemovalTarget] = React.useState<EmployeeAccessRemovalTarget | null>(null)
  const debouncedSearch = useDebouncedValue(query.search, 350)
  const lastFetchAtRef = React.useRef(0)

  useRenderDiagnostics("EmployeesListView", {
    page,
    search: query.search,
    rows: rows.length,
    loading,
  })

  const normalizedQuery = React.useMemo(
    () => ({
      ...query,
      search: debouncedSearch,
      employment_status: query.employment_status || undefined,
      branch_id: query.branch_id > 0 ? query.branch_id : undefined,
      department_id: query.department_id > 0 ? query.department_id : undefined,
      position_id: query.position_id > 0 ? query.position_id : undefined,
    }),
    [debouncedSearch, query]
  )
  const queryCacheKey = React.useMemo(
    () => JSON.stringify({ ...normalizedQuery, page }),
    [normalizedQuery, page]
  )

  React.useLayoutEffect(() => {
    const snapshot = readSnapshot(queryCacheKey)
    if (!snapshot) {
      return
    }

    setRows(snapshot.rows)
    setTotalPages(snapshot.totalPages)
    setTotal(snapshot.total)
  }, [queryCacheKey])

  const fetchEmployees = React.useCallback(async (signal?: AbortSignal) => {
    const token = readStoredToken()
    if (!token) {
      setError("Authentication required. Please log in again.")
      setRows([])
      return
    }

    setLoading(true)
    setError(null)
    try {
      const result = await listEmployees(
        token,
        {
          ...normalizedQuery,
          page,
        },
        {
          signal,
          cacheTtlMs: env.NEXT_PUBLIC_LIST_CACHE_TTL_SHORT_MS,
        }
      )
      lastFetchAtRef.current = Date.now()
      writeSnapshot(queryCacheKey, {
        rows: result.rows,
        totalPages: result.totalPages,
        total: result.total,
        cachedAt: Date.now(),
      })
      setRows(result.rows)
      setTotalPages(result.totalPages)
      setTotal(result.total)
    } catch (errorObject) {
      if (signal?.aborted) {
        return
      }
      setError(errorObject instanceof Error ? errorObject.message : "Failed to load employees.")
    } finally {
      if (!signal?.aborted) {
        setLoading(false)
      }
    }
  }, [normalizedQuery, page, queryCacheKey])

  React.useEffect(() => {
    const controller = new AbortController()
    void fetchEmployees(controller.signal)
    return () => controller.abort()
  }, [fetchEmployees])

  React.useEffect(() => {
    if (typeof window === "undefined") {
      return
    }

    const onFocus = () => {
      if (Date.now() - lastFetchAtRef.current < 15_000) {
        return
      }
      void fetchEmployees()
    }

    const onStorage = (event: StorageEvent) => {
      if (event.key === EMPLOYEE_STATUS_REFRESH_KEY) {
        void fetchEmployees()
      }
    }

    window.addEventListener("focus", onFocus)
    window.addEventListener("storage", onStorage)
    window.addEventListener(EMPLOYEE_STATUS_REFRESH_EVENT, onFocus)
    return () => {
      window.removeEventListener("focus", onFocus)
      window.removeEventListener("storage", onStorage)
      window.removeEventListener(EMPLOYEE_STATUS_REFRESH_EVENT, onFocus)
    }
  }, [fetchEmployees])

  const canGoPrevious = page > 1 && !loading
  const canGoNext = !loading && (totalPages === null || page < totalPages)

  const openEmployeeDetails = (row: AdminRecord, missingItemKey?: string) => {
    const employeeNo = readString(row, ["employee_no", "employeeNo", "user_no", "employee_number", "employeeNumber"])
    if (employeeNo === "-") {
      return
    }
    router.push(employeeProfileHref(employeeNo, missingItemKey))
  }

  const openRemovalDialog = React.useCallback((row: AdminRecord) => {
    const idRaw = row.id ?? row.employee_id ?? row.employeeId
    const employeeId =
      typeof idRaw === "number" && Number.isFinite(idRaw)
        ? idRaw
        : typeof idRaw === "string" && idRaw.trim()
          ? Number(idRaw)
          : null
    if (employeeId === null || !Number.isFinite(employeeId)) {
      return
    }
    setRemovalTarget({
      employeeId,
      employeeName: employeeDisplayName(row),
      employeeNo: readString(row, ["employee_no", "employeeNo", "user_no", "employee_number", "employeeNumber"]),
    })
    setRemovalOpen(true)
  }, [])

  const handleEmployeeSelect = (employeeId: string) => {
    const matched = rows.find((r) => {
      const id = String(r.id ?? r.employee_id ?? r.employee_no ?? r.employeeNo ?? "")
      return id === employeeId
    })
    if (matched) {
      openEmployeeDetails(matched)
    }
  }

  const employeeColumns = React.useMemo<Column<AdminRecord>[]>(() => [
    {
      key: "employee_no",
      label: "No",
      defaultWidth: 80,
      sortable: true,
      render: (row: AdminRecord) =>
        readString(row, ["employee_no", "employeeNo", "user_no", "employee_number", "employeeNumber"])
    },
    {
      key: "name",
      label: "Name",
      defaultWidth: 120,
      sortable: true,
      render: (row: AdminRecord) => employeeDisplayName(row)
    },
    {
      key: "department",
      label: "Dept",
      defaultWidth: 90,
      sortable: true,
      render: (row: AdminRecord) => {
        const directDepartmentName = readString(row, ["department_name", "departmentName"])
        if (directDepartmentName !== "-") {
          return directDepartmentName
        }
        const primaryDepartmentName = readNestedName(row.primary_department)
        if (primaryDepartmentName !== "—") {
          return primaryDepartmentName
        }
        return readNestedName(row.department)
      }
    },
    {
      key: "position",
      label: "Position",
      defaultWidth: 100,
      sortable: true,
      render: (row: AdminRecord) => {
        const directPositionName = readString(row, ["position_name", "positionName"])
        if (directPositionName !== "-") {
          return directPositionName
        }
        const primaryPositionName = readNestedName(row.primary_position)
        if (primaryPositionName !== "—") {
          return primaryPositionName
        }
        return readNestedName(row.position)
      }
    },
    {
      key: "hireDate",
      label: "Hired",
      defaultWidth: 70,
      sortable: true,
      render: (row: AdminRecord) => {
        const raw = readString(row, ["hire_date", "hireDate", "hired_at", "joined_at", "join_date", "created_at"])
        return raw && /^\d{4}-\d{2}-\d{2}/.test(raw) ? formatEmployeeDate(raw) : "—"
      }
    },
    {
      key: "status",
      label: "Status",
      defaultWidth: 130,
      sortable: true,
      render: (row: AdminRecord) => {
        const s = (readString(row, ["employment_status", "employmentStatus", "status"]) || "active")
          .toLowerCase()
          .trim()
        const display = s
          ? s.replace(/[_-]+/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())
          : "Unknown"
        const tone =
          s === "active" || s === "onboarding"
            ? "text-emerald-600"
            : s === "pending"
              ? "text-amber-600"
              : s === "inactive" || s === "terminated" || s === "offboarding"
                ? "text-rose-600"
                : "text-slate-600"
        const dot =
          s === "active" || s === "onboarding"
            ? "bg-emerald-500"
            : s === "pending"
              ? "bg-amber-500"
              : s === "inactive" || s === "terminated" || s === "offboarding"
                ? "bg-rose-500"
                : "bg-slate-400"
        return (
          <span
            className={`inline-flex items-center gap-1.5 text-xs font-semibold whitespace-nowrap ${tone}`}
            title={display}
          >
            <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${dot}`} />
            {display}
          </span>
        )
      }
    },
    {
      key: "actions",
      label: "Actions",
      defaultWidth: 80,
      sortable: false,
      render: (row: AdminRecord) => (
        <button
          type="button"
          className="inline-flex h-8 w-8 items-center justify-center rounded-md border border-rose-200 text-rose-600 hover:bg-rose-50"
          title="Remove / disable access"
          aria-label="Remove or disable access"
          onClick={(event) => {
            event.stopPropagation()
            openRemovalDialog(row)
          }}
        >
          <Trash2 className="h-3.5 w-3.5" />
        </button>
      ),
    },
  ], [openRemovalDialog])

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-1.5">
        <SearchToggleField
          className="min-w-0"
          placeholder="Search name, email, phone, user_no"
          value={query.search}
          onChange={(value) => {
            setPage(1)
            setQuery((previous) => ({ ...previous, search: value }))
          }}
        />
        <select
          className="h-8 min-w-[8.5rem] rounded-md border border-slate-300 bg-white px-2 text-xs text-slate-900"
          value={query.employment_status}
          onChange={(event) => {
            setPage(1)
            setQuery((previous) => ({
              ...previous,
              employment_status: event.target.value as typeof previous.employment_status,
            }))
          }}
          aria-label="Filter employment status"
        >
          <option value="">All statuses</option>
          <option value="onboarding">Onboarding</option>
          <option value="active">Active</option>
          <option value="suspended">Suspended</option>
          <option value="terminated">Terminated</option>
          <option value="exited">Exited</option>
        </select>
      </div>

      {error ? <p className="text-sm text-rose-600">{error}</p> : null}

      <ResizableTable
        title="Employees"
        data={rows}
        columns={employeeColumns}
        onRowSelect={(id, row) => {
          if (row) openEmployeeDetails(row as AdminRecord)
        }}
        loading={loading}
        storageKey="employees"
        enableAnimations={false}
      />

      <EmployeeAccessRemovalDialog
        open={removalOpen}
        target={removalTarget}
        onOpenChange={(open) => {
          setRemovalOpen(open)
          if (!open) setRemovalTarget(null)
        }}
        onCompleted={() => {
          void fetchEmployees()
        }}
      />

      <AlertDialog
        open={Boolean(missingDialog)}
        onOpenChange={(open) => {
          if (!open) {
            setMissingDialog(null)
          }
        }}
      >
        <AlertDialogContent className="max-w-lg">
          <AlertDialogHeader>
            <AlertDialogTitle>Incomplete Profile Items</AlertDialogTitle>
            <AlertDialogDescription>
              {missingDialog
                ? `${missingDialog.employeeNo} has ${missingDialog.missing.length} incomplete item(s).`
                : "Incomplete profile details."}
            </AlertDialogDescription>
          </AlertDialogHeader>
          {missingDialog && missingDialog.missing.length > 0 ? (
            <div className="space-y-2">
              {missingDialog.missing.map((item) => (
                <div key={item.key} className="flex items-center justify-between rounded-md border border-slate-200 p-2">
                  <span className="text-sm text-slate-800">{item.label}</span>
                  <button
                    type="button"
                    className="text-xs font-medium text-indigo-600 hover:text-indigo-700"
                    onClick={() => {
                      router.push(employeeProfileHref(missingDialog.employeeNo, item.key))
                    }}
                  >
                    Open profile
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-sm text-emerald-700">All required items are completed.</p>
          )}
          <AlertDialogFooter>
            <AlertDialogCancel>Close</AlertDialogCancel>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

"use client"

import * as React from "react"
import { CheckCircle2, Loader2, RefreshCw, XCircle } from "lucide-react"

import { DatePickerPresets } from "@/components/ui/date-picker-presets"
import { Badge } from "@/components/ui/badge"
import { Textarea } from "@/components/ui/textarea"
import { ResizableTable, type Column } from "@/components/ui/resizable-table"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  approveHrAttendanceCorrectionRequest,
  getHrAttendanceCorrectionApprovalRequest,
  listHrAttendanceCorrectionApprovalRequests,
  rejectHrAttendanceCorrectionRequest,
  type AdminRecord,
} from "@/lib/admin-api"
import { showErrorAlert } from "@/lib/error-alert"
import { showSuccessAlert } from "@/lib/success-alert"
import { AUTH_STORAGE_KEYS } from "@/utils/constants"
import { cn } from "@/lib/utils"

const TOKEN_STORAGE_KEY = "hrms.admin.accessToken"

type ChangeRow = {
  field: string
  label: string
  currentValue: string
  requestedValue: string
}

function asRecord(value: unknown): AdminRecord | null {
  return typeof value === "object" && value !== null ? (value as AdminRecord) : null
}

function readStoredToken() {
  if (typeof window === "undefined") {
    return ""
  }

  const direct = window.localStorage.getItem(TOKEN_STORAGE_KEY)?.trim() ?? ""
  if (direct) {
    return direct
  }

  const authTokensRaw = window.localStorage.getItem(AUTH_STORAGE_KEYS.tokens)
  if (!authTokensRaw) {
    return ""
  }

  try {
    const parsed = JSON.parse(authTokensRaw) as { accessToken?: string; access_token?: string }
    return (parsed.accessToken ?? parsed.access_token ?? "").trim()
  } catch {
    return ""
  }
}

function readString(row: AdminRecord | null, keys: string[], fallback = "-") {
  if (!row) {
    return fallback
  }
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "string" && value.trim()) {
      return value
    }
  }
  return fallback
}

function readNumber(row: AdminRecord | null, keys: string[]) {
  if (!row) {
    return null
  }
  for (const key of keys) {
    const value = row[key]
    if (typeof value === "number" && Number.isFinite(value)) {
      return value
    }
    if (typeof value === "string" && value.trim()) {
      const parsed = Number(value)
      if (Number.isFinite(parsed)) {
        return parsed
      }
    }
  }
  return null
}

function formatDateTime(value: unknown) {
  if (typeof value !== "string" || !value.trim()) {
    return "-"
  }
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) {
    return value
  }
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  }).format(date)
}

function formatDateOnly(value: unknown) {
  if (typeof value !== "string" || !value.trim()) {
    return "-"
  }
  // Prefer bare YYYY-MM-DD display without timezone shift.
  if (/^\d{4}-\d{2}-\d{2}$/.test(value.trim())) {
    const [year, month, day] = value.trim().split("-")
    const date = new Date(Number(year), Number(month) - 1, Number(day))
    if (!Number.isNaN(date.getTime())) {
      return new Intl.DateTimeFormat("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      }).format(date)
    }
  }
  return formatDateTime(value)
}

function formatUnknownValue(value: unknown): string {
  if (value === null || value === undefined) {
    return "-"
  }
  if (typeof value === "boolean") {
    return value ? "Yes" : "No"
  }
  if (typeof value === "number") {
    return Number.isFinite(value) ? String(value) : "-"
  }
  if (typeof value === "string") {
    const trimmed = value.trim()
    if (!trimmed) return "-"
    if (/^\d{4}-\d{2}-\d{2}T/.test(trimmed) || /^\d{4}-\d{2}-\d{2} /.test(trimmed)) {
      return formatDateTime(trimmed)
    }
    if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
      return formatDateOnly(trimmed)
    }
    return trimmed
  }
  if (Array.isArray(value)) {
    const labels = value.map((entry) => formatUnknownValue(entry)).filter((entry) => entry !== "-")
    return labels.length > 0 ? labels.join(", ") : "-"
  }
  if (typeof value === "object") {
    const record = value as Record<string, unknown>
    const label =
      typeof record.name === "string" && record.name.trim()
        ? record.name.trim()
        : typeof record.title === "string" && record.title.trim()
          ? record.title.trim()
          : typeof record.label === "string" && record.label.trim()
            ? record.label.trim()
            : null
    if (label) {
      return label
    }
    try {
      return JSON.stringify(value)
    } catch {
      return "-"
    }
  }
  return "-"
}

function humanizeFieldName(field: string) {
  return field
    .replace(/[_-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^./, (value) => value.toUpperCase())
}

function getRequestId(row: AdminRecord | null) {
  const id = readNumber(row, ["id", "request_id"])
  return id === null ? "" : String(id)
}

function getStatusMeta(value: unknown) {
  const raw = typeof value === "string" ? value.trim() : ""
  const normalized = raw.toLowerCase()

  if (normalized === "approved") {
    return {
      label: raw || "Approved",
      className: "border-emerald-200 bg-emerald-50 text-emerald-700",
      terminal: true,
    }
  }
  if (normalized === "rejected") {
    return {
      label: raw || "Rejected",
      className: "border-rose-200 bg-rose-50 text-rose-700",
      terminal: true,
    }
  }
  if (normalized === "cancelled") {
    return {
      label: raw || "Cancelled",
      className: "border-slate-200 bg-slate-100 text-slate-700",
      terminal: true,
    }
  }
  if (["submitted", "pending", "in_review", "under_review"].includes(normalized)) {
    return {
      label: raw || "Pending",
      className: "border-amber-200 bg-amber-50 text-amber-700",
      terminal: false,
    }
  }
  if (normalized === "draft") {
    return {
      label: raw || "Draft",
      className: "border-slate-200 bg-white text-slate-600",
      terminal: false,
    }
  }

  return {
    label: raw || "Pending",
    className: "border-slate-200 bg-white text-slate-700",
    terminal: false,
  }
}

function getEmployeeLabel(row: AdminRecord | null) {
  const nestedEmployee = asRecord(row?.employee)
  const nestedUser = asRecord(nestedEmployee?.user) ?? asRecord(row?.user)
  const explicit =
    readString(row, ["employee_name", "full_name", "employee_full_name", "name"], "") ||
    readString(nestedEmployee, ["full_name", "name"], "") ||
    readString(nestedUser, ["full_name", "name"], "")

  const employeeNo =
    readString(row, ["employee_no", "employeeNo", "user_no"], "") ||
    readString(nestedEmployee, ["employee_no", "employeeNo", "user_no"], "") ||
    readString(nestedUser, ["employee_no", "employeeNo", "user_no"], "")

  if (explicit) {
    return employeeNo ? `${explicit} (${employeeNo})` : explicit
  }

  const firstName =
    readString(row, ["first_name"], "") ||
    readString(nestedEmployee, ["first_name"], "") ||
    readString(nestedUser, ["first_name"], "")
  const lastName =
    readString(row, ["last_name"], "") ||
    readString(nestedEmployee, ["last_name"], "") ||
    readString(nestedUser, ["last_name"], "")

  if (firstName || lastName) {
    const fullName = [firstName, lastName].filter(Boolean).join(" ")
    return employeeNo ? `${fullName} (${employeeNo})` : fullName
  }

  if (employeeNo) {
    return employeeNo
  }

  const employeeId = readNumber(row, ["employee_id", "user_id"])
  return employeeId === null ? "Employee" : `Employee #${employeeId}`
}

function getRequestTitle(row: AdminRecord | null) {
  const requestType = readString(row, ["request_type", "correction_type", "type"], "")
  const attendanceDate = formatDateOnly(
    row?.attendance_date ?? row?.attendanceDate ?? row?.work_date ?? row?.date
  )
  if (requestType && attendanceDate !== "-") {
    return `${humanizeFieldName(requestType)} · ${attendanceDate}`
  }
  if (requestType) {
    return humanizeFieldName(requestType)
  }
  if (attendanceDate !== "-") {
    return `Correction · ${attendanceDate}`
  }
  return (
    readString(row, ["title", "request_no", "reference_no", "reference"], "") ||
    "Attendance correction"
  )
}

function extractCorrectionRows(row: AdminRecord | null): ChangeRow[] {
  if (!row) {
    return []
  }

  const pairs: Array<{
    field: string
    label: string
    currentKeys: string[]
    requestedKeys: string[]
  }> = [
    {
      field: "check_in",
      label: "Check in",
      currentKeys: [
        "current_check_in_at",
        "original_check_in_at",
        "existing_check_in_at",
        "previous_check_in_at",
        "check_in_at",
        "first_check_in_at",
      ],
      requestedKeys: ["requested_check_in_at", "requested_check_in", "new_check_in_at"],
    },
    {
      field: "check_out",
      label: "Check out",
      currentKeys: [
        "current_check_out_at",
        "original_check_out_at",
        "existing_check_out_at",
        "previous_check_out_at",
        "check_out_at",
        "last_check_out_at",
      ],
      requestedKeys: ["requested_check_out_at", "requested_check_out", "new_check_out_at"],
    },
    {
      field: "status",
      label: "Status",
      currentKeys: [
        "current_status",
        "original_status",
        "existing_status",
        "previous_status",
        "attendance_status",
      ],
      requestedKeys: ["requested_status", "new_status"],
    },
  ]

  const rows: ChangeRow[] = []
  for (const pair of pairs) {
    const requested = pair.requestedKeys
      .map((key) => row[key])
      .find((value) => value !== null && value !== undefined && String(value).trim() !== "")
    if (requested === undefined) {
      continue
    }
    const current = pair.currentKeys
      .map((key) => row[key])
      .find((value) => value !== null && value !== undefined && String(value).trim() !== "")
    rows.push({
      field: pair.field,
      label: pair.label,
      currentValue: formatUnknownValue(current),
      requestedValue: formatUnknownValue(requested),
    })
  }

  // Fall back to generic requested_* / current_* object maps if present.
  if (rows.length === 0) {
    const requestedChanges =
      asRecord(row.requested_changes) ??
      asRecord(row.requested_values) ??
      asRecord(row.requested)
    const currentValues =
      asRecord(row.current_values) ??
      asRecord(row.original_values) ??
      asRecord(row.previous_values)

    if (requestedChanges) {
      Object.entries(requestedChanges).forEach(([field, value]) => {
        rows.push({
          field,
          label: humanizeFieldName(field),
          currentValue: formatUnknownValue(currentValues?.[field]),
          requestedValue: formatUnknownValue(value),
        })
      })
    }
  }

  return rows
}

function MetaChip({ label, value }: { label: string; value: string }) {
  return (
    <div className="min-w-0 rounded-md border border-slate-200/80 bg-slate-50/80 px-2 py-1">
      <p className="text-[10px] font-medium tracking-wide text-slate-500 uppercase">{label}</p>
      <p className="truncate text-xs font-medium text-slate-900" title={value}>
        {value}
      </p>
    </div>
  )
}

function ToolbarButton({
  children,
  onClick,
  disabled,
  variant = "outline",
}: {
  children: React.ReactNode
  onClick?: () => void
  disabled?: boolean
  variant?: "outline" | "primary"
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className={cn(
        "inline-flex h-7 items-center gap-1 rounded-md px-2 text-xs font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-50",
        variant === "primary"
          ? "bg-slate-900 text-white hover:bg-slate-800"
          : "border border-slate-300 text-slate-700 hover:bg-slate-50"
      )}
    >
      {children}
    </button>
  )
}

export function HrAttendanceCorrectionApprovalsView() {
  const [requests, setRequests] = React.useState<AdminRecord[]>([])
  const [selectedRequestId, setSelectedRequestId] = React.useState("")
  const [selectedRequestDetail, setSelectedRequestDetail] = React.useState<AdminRecord | null>(null)
  const [statusFilter, setStatusFilter] = React.useState("all")
  const [dateFrom, setDateFrom] = React.useState("")
  const [dateTo, setDateTo] = React.useState("")
  const [decisionComment, setDecisionComment] = React.useState("")
  const [feedback, setFeedback] = React.useState<string | null>(null)
  const [error, setError] = React.useState<string | null>(null)
  const [loading, setLoading] = React.useState(false)
  const [detailLoading, setDetailLoading] = React.useState(false)
  const [actionLoading, setActionLoading] = React.useState<"approve" | "reject" | null>(null)

  const selectedListRequest = React.useMemo(
    () => requests.find((row) => getRequestId(row) === selectedRequestId) ?? null,
    [requests, selectedRequestId]
  )

  const activeRequest = React.useMemo(() => {
    if (!selectedListRequest && !selectedRequestDetail) {
      return null
    }
    return {
      ...(selectedListRequest ?? {}),
      ...(selectedRequestDetail ?? {}),
    } as AdminRecord
  }, [selectedListRequest, selectedRequestDetail])

  const changeRows = React.useMemo(() => extractCorrectionRows(activeRequest), [activeRequest])
  const statusMeta = React.useMemo(
    () => getStatusMeta(activeRequest?.status ?? selectedListRequest?.status ?? ""),
    [activeRequest, selectedListRequest]
  )

  const loadRequestDetail = React.useCallback(async (requestId: string) => {
    const token = readStoredToken()
    if (!token || !requestId) {
      return
    }

    setDetailLoading(true)
    try {
      const detail = await getHrAttendanceCorrectionApprovalRequest(token, requestId)
      setSelectedRequestDetail(detail)
    } catch (errorObject) {
      const message =
        errorObject instanceof Error
          ? errorObject.message
          : "Failed to load attendance correction request details."
      setError(message)
      showErrorAlert(message)
    } finally {
      setDetailLoading(false)
    }
  }, [])

  const requestColumns = React.useMemo<Array<Column<AdminRecord>>>(
    () => [
      {
        key: "employee",
        label: "Employee",
        defaultWidth: 120,
        render: (row) => (
          <span className="text-xs font-medium text-slate-900">{getEmployeeLabel(row)}</span>
        ),
      },
      {
        key: "attendance_date",
        label: "Date",
        defaultWidth: 80,
        render: (row) => (
          <span className="text-xs text-slate-700 tabular-nums">
            {formatDateOnly(
              row.attendance_date ?? row.attendanceDate ?? row.work_date ?? row.date
            )}
          </span>
        ),
      },
      {
        key: "request",
        label: "Request",
        defaultWidth: 150,
        render: (row) => (
          <div className="min-w-0">
            <p className="truncate text-xs font-medium text-slate-900">{getRequestTitle(row)}</p>
            <p className="truncate text-[11px] text-slate-500">
              {readString(row, ["reason"], "No reason")}
            </p>
          </div>
        ),
      },
      {
        key: "status",
        label: "Status",
        defaultWidth: 78,
        render: (row) => {
          const meta = getStatusMeta(row.status)
          return (
            <Badge
              variant="outline"
              className={cn("px-1.5 py-0 text-[10px] capitalize", meta.className)}
            >
              {meta.label}
            </Badge>
          )
        },
      },
      {
        key: "actions",
        label: "",
        defaultWidth: 64,
        sortable: false,
        render: (row) => {
          const rowId = getRequestId(row)
          const isSelected = rowId === selectedRequestId
          return (
            <div className="flex justify-end" onClick={(event) => event.stopPropagation()}>
              <button
                type="button"
                className={cn(
                  "rounded px-1.5 py-0.5 text-[11px] font-medium transition-colors",
                  isSelected
                    ? "bg-slate-900 text-white"
                    : "text-slate-600 hover:bg-slate-100"
                )}
                onClick={() => {
                  setSelectedRequestId(rowId)
                  setFeedback(null)
                  setDecisionComment("")
                  void loadRequestDetail(rowId)
                }}
              >
                {isSelected ? "Open" : "Review"}
              </button>
            </div>
          )
        },
      },
    ],
    [loadRequestDetail, selectedRequestId]
  )

  const selectedRequestIdRef = React.useRef(selectedRequestId)
  selectedRequestIdRef.current = selectedRequestId

  const loadRequests = React.useCallback(async () => {
    const token = readStoredToken()
    if (!token) {
      const message = "Authentication required. Please log in again."
      setError(message)
      setRequests([])
      setSelectedRequestId("")
      setSelectedRequestDetail(null)
      return
    }

    setLoading(true)
    setError(null)
    try {
      const result = await listHrAttendanceCorrectionApprovalRequests(token, {
        page: 1,
        limit: 100,
        status: statusFilter === "all" ? undefined : statusFilter,
        date_from: dateFrom || undefined,
        date_to: dateTo || undefined,
      })
      setRequests(result.rows)

      const currentSelection =
        result.rows.find((row) => getRequestId(row) === selectedRequestIdRef.current) ??
        result.rows[0] ??
        null

      if (!currentSelection) {
        setSelectedRequestId("")
        setSelectedRequestDetail(null)
        return
      }

      const nextRequestId = getRequestId(currentSelection)
      setSelectedRequestId(nextRequestId)
      await loadRequestDetail(nextRequestId)
    } catch (errorObject) {
      const message =
        errorObject instanceof Error
          ? errorObject.message
          : "Failed to load attendance correction approval requests."
      setError(message)
      showErrorAlert(message)
    } finally {
      setLoading(false)
    }
  }, [dateFrom, dateTo, loadRequestDetail, statusFilter])

  React.useEffect(() => {
    void loadRequests()
  }, [loadRequests])

  const handleDecision = React.useCallback(
    async (action: "approve" | "reject") => {
      const token = readStoredToken()
      if (!token || !activeRequest) {
        const message = "Authentication required. Please log in again."
        setError(message)
        showErrorAlert(message)
        return
      }

      const requestId = getRequestId(activeRequest)
      if (!requestId) {
        return
      }

      const note = decisionComment.trim()
      if (action === "reject" && !note) {
        const message = "Add a rejection reason before declining this request."
        setError(message)
        setFeedback(message)
        showErrorAlert(message)
        return
      }

      setActionLoading(action)
      setError(null)
      setFeedback(null)
      try {
        const body = {
          comment: note || (action === "approve" ? "Approved by HR" : "Rejected by HR"),
          metadata: {
            reviewed_from: "HR_PORTAL",
          },
        }

        if (action === "approve") {
          await approveHrAttendanceCorrectionRequest(token, requestId, body)
        } else {
          await rejectHrAttendanceCorrectionRequest(token, requestId, body)
        }

        const successMessage =
          action === "approve"
            ? "Attendance correction approved and applied to the daily summary."
            : "Attendance correction request rejected."
        setFeedback(successMessage)
        setDecisionComment("")
        showSuccessAlert(successMessage)
        await loadRequests()
      } catch (errorObject) {
        const message =
          errorObject instanceof Error
            ? errorObject.message
            : `Failed to ${action} attendance correction request.`
        setError(message)
        setFeedback(message)
        showErrorAlert(message)
      } finally {
        setActionLoading(null)
      }
    },
    [activeRequest, decisionComment, loadRequests]
  )

  const pendingCount = React.useMemo(
    () => requests.filter((row) => !getStatusMeta(row.status).terminal).length,
    [requests]
  )

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-2 py-1.5">
        <h2 className="shrink-0 text-sm font-semibold text-slate-900">Correction Requests</h2>
        <Badge
          variant="outline"
          className="h-5 border-slate-200 bg-slate-50 px-1.5 text-[10px] text-slate-600"
        >
          {requests.length}
        </Badge>
        <Badge
          variant="outline"
          className="h-5 border-amber-200 bg-amber-50 px-1.5 text-[10px] text-amber-700"
        >
          {pendingCount} pending
        </Badge>

        <div className="mx-0.5 hidden h-4 w-px bg-slate-200 sm:block" />

        <Select value={statusFilter} onValueChange={(value) => setStatusFilter(value ?? "all")}>
          <SelectTrigger className="h-7 w-auto min-w-[7.5rem] text-xs">
            <SelectValue placeholder="Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All statuses</SelectItem>
            <SelectItem value="submitted">Submitted</SelectItem>
            <SelectItem value="draft">Draft</SelectItem>
            <SelectItem value="approved">Approved</SelectItem>
            <SelectItem value="rejected">Rejected</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <div className="min-w-[7.5rem]">
          <DatePickerPresets
            value={dateFrom}
            onChange={setDateFrom}
            placeholder="From"
            className="h-7 px-2 text-xs"
          />
        </div>
        <div className="min-w-[7.5rem]">
          <DatePickerPresets
            value={dateTo}
            onChange={setDateTo}
            placeholder="To"
            className="h-7 px-2 text-xs"
          />
        </div>

        <div className="ml-auto flex flex-wrap items-center gap-1">
          <ToolbarButton
            onClick={() => {
              setStatusFilter("all")
              setDateFrom("")
              setDateTo("")
              setFeedback(null)
            }}
          >
            Reset
          </ToolbarButton>
          <ToolbarButton variant="primary" onClick={() => void loadRequests()} disabled={loading}>
            <RefreshCw className={cn("size-3", loading ? "animate-spin" : "")} />
            Refresh
          </ToolbarButton>
        </div>
      </div>

      {error ? (
        <div className="rounded-md border border-rose-200 bg-rose-50 px-2.5 py-1.5 text-xs text-rose-700">
          {error}
        </div>
      ) : null}

      <div className="grid gap-2 xl:grid-cols-[minmax(0,1fr)_minmax(18rem,21rem)]">
        <div className="min-w-0 overflow-hidden rounded-lg border border-slate-200 bg-white">
          <div className="flex items-center justify-between border-b border-slate-100 px-2.5 py-1.5">
            <p className="text-xs font-semibold text-slate-800">Requests</p>
            <p className="text-[11px] text-slate-500">Select a row to review</p>
          </div>
          <div className="p-1.5">
            <ResizableTable
              title="Correction Requests"
              data={requests}
              columns={requestColumns}
              itemsPerPage={12}
              loading={loading}
              storageKey="hr-attendance-correction-approval-requests-v2"
            />
            {!loading && requests.length === 0 ? (
              <div className="rounded-md border border-dashed border-slate-200 px-3 py-5 text-center text-xs text-slate-500">
                No correction requests match the current filters.
              </div>
            ) : null}
          </div>
        </div>

        <aside className="flex min-h-[16rem] flex-col rounded-lg border border-slate-200 bg-white">
          <div className="flex items-center justify-between border-b border-slate-100 px-2.5 py-1.5">
            <p className="text-xs font-semibold text-slate-800">Review</p>
            {activeRequest ? (
              <Badge
                variant="outline"
                className={cn("px-1.5 py-0 text-[10px] capitalize", statusMeta.className)}
              >
                {statusMeta.label}
              </Badge>
            ) : null}
          </div>

          <div className="flex flex-1 flex-col gap-2 p-2.5">
            {detailLoading ? (
              <div className="flex flex-1 items-center justify-center gap-1.5 text-xs text-slate-500">
                <Loader2 className="size-3.5 animate-spin" />
                Loading…
              </div>
