    const fullName = readString(match, ["full_name", "fullName", "employee_name", "employeeName", "name"])
    if (fullName !== "-") {
      return fullName
    }
    return [readString(match, ["first_name", "firstName"]), readString(match, ["last_name", "lastName"])]
      .filter((part) => part !== "-")
