    const inlineEmployeeName =
      readString(row, ["employee_name", "employeeName", "full_name", "fullName", "name"])
    if (inlineEmployeeName !== "-") {
      return inlineEmployeeName
    }
    return employeeLabel(readNumber(row, ["employee_id"]))
