  status: string
  roleIds: string[]
}

interface BasicEntityForm {
  name: string
  display_name: string
  description: string
}

interface CompanyForm {
  company_name: string
  company_slug: string
  admin_first_name: string
  admin_last_name: string
  admin_email: string
