          sortable: true,
          render: (row) => (
            <span className="text-sm text-slate-700">{row.module}</span>
          ),
        },
        {
          key: "description",
          label: "Description",
          defaultWidth: 260,
          sortable: true,
          render: (row) => (
            <span className="line-clamp-2 text-xs text-slate-600">{row.description}</span>
          ),
        },
        {
