          label: "Type",
          defaultWidth: 100,
          sortable: true,
          render: (row) => (
            <span className="text-sm text-slate-700">{row.type}</span>
          ),
        },
        actionsColumn,
      ]
    }

    return [
      {
        key: "display",
        label: "Role",
        defaultWidth: 200,
        sortable: true,
        render: (row) => (
          <span className="font-medium text-slate-900">{row.display}</span>
        ),
      },
      {
        key: "permissions_count",
        label: "Permissions",
        defaultWidth: 120,
        sortable: true,
        render: (row) => (
          <span className="text-sm text-slate-700">{row.permissions_count ?? 0}</span>
        ),
      },
      {
        key: "description",
        label: "Description",
        defaultWidth: 260,
        sortable: true,
        render: (row) => (
          <span className="line-clamp-2 text-xs text-slate-600">{row.description}</span>
        ),
      },
      {
        key: "type",
        label: "Type",
        defaultWidth: 100,
        sortable: true,
        render: (row) => (
          <span className="text-sm text-slate-700">{row.type}</span>
        ),
      },
      actionsColumn,
    ]
  }, [activeResource, canDeleteResource, openAccessControlRow])

  const handleSetPassword = async () => {
    if (!token || !targetPasswordUser) {
      return
    }
    if (!targetPassword.trim()) {
      toast.error("New password is required.")
      return
    }

    try {
      await onSetUserPassword(targetPasswordUser.id, targetPassword)
      setTargetPassword("")
      setTargetPasswordUser(null)
      showSuccessAlert("Password updated.")
    } catch (errorObject) {
      const message = errorObject instanceof Error ? errorObject.message : "Password update failed."
      toast.error(message)
    }
  }

  const sortOrder = usersQuery.sortOrder as SortOrder
  const canPrevPage = usersQuery.page > 1
  const canNextPage = usersTotalPages
    ? usersQuery.page < usersTotalPages
    : rows.length >= usersQuery.limit
  const isAccessControlResource =
    activeResource === "roles" || activeResource === "permissions"

  React.useEffect(() => {
    setAccessControlSearch("")
  }, [activeResource])

  const canManageAssignments =
    hasActorPermission(actorPermissions, "users:update") ||
    hasActorPermission(actorPermissions, "company_users:update") ||
    hasActorPermission(actorPermissions, "manage_company_users") ||
    hasActorPermission(actorPermissions, "permissions:update") ||
    hasActorPermission(actorPermissions, "roles:update") ||
    hasActorPermission(actorPermissions, "users:assign-role")

  React.useEffect(() => {
    if (!editingEntity) {
      setDetailSheetTab("general")
      setMemberCompanyUsers([])
      setAssignedMemberIds(new Set())
      setRoleAssignedUsers([])
      setMembersError(null)
      setMembersLoading(false)
      setMemberSearch("")
      setMemberToAdd("")
      setRolePermissionNamesFromApi(null)
      setRolePermissionsLoading(false)
      setRevokeConfirm(null)
      setPeopleDialogOpen(false)
      return
    }
    // Roles open on Assigned so the people summary from GET /roles/{id}/users is visible first.
    setDetailSheetTab("assigned")
    setMemberSearch("")
    setMemberToAdd("")
    setAssignPickerQuery("")
    setRoleAssignedUsers([])
    setPeopleDialogOpen(false)
  }, [editingEntity?.id, editingEntity?.resource])

  React.useEffect(() => {
    if (!editingEntity) return
    if (editingEntity.resource !== "permissions" && editingEntity.resource !== "roles") return
    if (!token) {
      setMembersError("Sign in to load assigned users.")
      return
    }

    const controller = new AbortController()
    let cancelled = false

    const loadMembers = async () => {
      setMembersLoading(true)
      setMembersError(null)
      try {
        const companyUsers = await listAllCurrentCompanyUsers(token, {
          signal: controller.signal,
        })
        if (cancelled) return
        setMemberCompanyUsers(companyUsers)

        const assigned = new Set<string>()
        const entityId = editingEntity.id

        if (editingEntity.resource === "permissions") {
          for (const companyUser of companyUsers) {
            const membershipId = companyUserMembershipId(companyUser)
            if (membershipId && companyUserHasPermission(companyUser, entityId)) {
              assigned.add(membershipId)
            }
          }
          const permissionDetail = await getPermissionById(entityId, token).catch(() => null)
          if (cancelled) return
          if (permissionDetail && Array.isArray(permissionDetail.users)) {
            const linkedUserIds = new Set<string>()
            for (const entry of permissionDetail.users) {
              if (typeof entry === "number" || typeof entry === "string") {
                linkedUserIds.add(String(entry))
                continue
              }
              const rec = asRecordValue(entry)
              if (rec?.id !== undefined && rec.id !== null) {
                linkedUserIds.add(String(rec.id))
              }
            }
            for (const companyUser of companyUsers) {
              const membershipId = companyUserMembershipId(companyUser)
              const linkedUserId = companyUserLinkedUserId(companyUser)
              if (membershipId && linkedUserId && linkedUserIds.has(linkedUserId)) {
                assigned.add(membershipId)
              }
            }
          }
        } else {
          // Roles: GET /api/roles/{id}, /permissions, /users
          let roleUsersResult: { rows: AdminRecord[] }
          try {
            roleUsersResult = await listRoleUsers(token, entityId, {
              page: 1,
              limit: 100,
              sortBy: "created_at",
              sortOrder: "DESC",
            })
          } catch (roleUsersError) {
            // Don't swallow silently — surface API failures for the Assigned list.
            throw roleUsersError instanceof Error
              ? roleUsersError
              : new Error("Failed to load users assigned to this role.")
          }

          const [roleDetail, rolePermissions] = await Promise.all([
            getRoleById(entityId, token).catch(() => null),
            listRolePermissions(token, entityId).catch(() => [] as AdminRecord[]),
          ])
          if (cancelled) return

          const permissionNames = (() => {
            if (rolePermissions.length > 0) {
              return rolePermissionNamesFromRecord({ permissions: rolePermissions })
            }
            if (roleDetail) {
              return rolePermissionNamesFromRecord(roleDetail)
            }
            return [] as string[]
          })()

          setRolePermissionNamesFromApi(permissionNames)
          setEditingRolePermissionNames(permissionNames)
          setInitialEditingRolePermissionNames(permissionNames)

          if (roleDetail) {
            const nextForm = toEntityForm(roleDetail)
            setEditingEntityForm(nextForm)
            setInitialEditingEntityForm(nextForm)
          }

          // Primary list: render GET /api/roles/{roleId}/users rows directly.
          const fromApi = roleUsersResult.rows.map((row, index) =>
            mapRoleApiUserToMember(row, index)
          )
          setRoleAssignedUsers(fromApi)

          const linkedUserIds = new Set(
            fromApi.map((entry) => entry.userId).filter((id): id is string => Boolean(id))
          )

          for (const companyUser of companyUsers) {
            const membershipId = companyUserMembershipId(companyUser)
            const linkedUserId = companyUserLinkedUserId(companyUser)
            if (
              membershipId &&
              ((linkedUserId && linkedUserIds.has(linkedUserId)) ||
                companyUserHasRole(companyUser, entityId))
            ) {
              assigned.add(membershipId)
            }
          }
        }

        setAssignedMemberIds(assigned)
      } catch (errorObject) {
        if (cancelled || controller.signal.aborted) return
        const message =
          errorObject instanceof Error
            ? errorObject.message
            : "Failed to load assignment details."
        setMembersError(message)
        setMemberCompanyUsers([])
        setAssignedMemberIds(new Set())
      } finally {
        if (!cancelled) {
          setMembersLoading(false)
          setRolePermissionsLoading(false)
        }
      }
    }

    if (editingEntity.resource === "roles") {
      setRolePermissionsLoading(true)
    }
    void loadMembers()
    return () => {
      cancelled = true
      controller.abort()
    }
  }, [editingEntity, token, membersRefreshKey])

  const assignedMembers = React.useMemo((): AssignedMemberUser[] => {
    const query = memberSearch.trim().toLowerCase()

    // Roles: show people returned by GET /api/roles/{roleId}/users.
    if (editingEntity?.resource === "roles") {
      return roleAssignedUsers
        .filter((row) => {
          if (!query) return true
          return `${row.name} ${row.email} ${row.status} ${row.userId ?? ""}`
            .toLowerCase()
            .includes(query)
        })
        .sort((a, b) => a.name.localeCompare(b.name))
    }

    return memberCompanyUsers
      .filter((row) => {
        const membershipId = companyUserMembershipId(row)
        return membershipId ? assignedMemberIds.has(membershipId) : false
      })
      .map((row) => {
        const membershipId = companyUserMembershipId(row) ?? ""
        return {
          membershipId,
          userId: companyUserLinkedUserId(row),
          name: companyUserDisplayName(row),
          email: companyUserEmail(row),
          status: companyUserStatus(row),
          source: row,
        }
      })
      .filter((row) => {
        if (!query) return true
        return `${row.name} ${row.email} ${row.status}`.toLowerCase().includes(query)
      })
      .sort((a, b) => a.name.localeCompare(b.name))
  }, [
    assignedMemberIds,
    editingEntity?.resource,
    memberCompanyUsers,
    memberSearch,
    roleAssignedUsers,
  ])

  const availableMembers = React.useMemo(() => {
    const assignedUserIds = new Set(
      roleAssignedUsers
        .flatMap((entry) => [entry.userId, entry.membershipId])
        .filter((id): id is string => Boolean(id))
    )
    return memberCompanyUsers
      .filter((row) => {
        const membershipId = companyUserMembershipId(row)
        if (!membershipId) return false
        if (editingEntity?.resource === "roles") {
          const assignUserId = resolveRoleAssignUserId(row)
          if (assignUserId && assignedUserIds.has(assignUserId)) return false
          if (assignedMemberIds.has(membershipId)) return false
          return true
        }
        return !assignedMemberIds.has(membershipId)
      })
      .map((row) => {
        const membershipId = companyUserMembershipId(row) ?? ""
        const name = companyUserDisplayName(row)
        const email = companyUserEmail(row)
        const userId = resolveRoleAssignUserId(row)
        return {
          membershipId,
          userId,
          name,
          email,
          label: email && email !== "—" ? `${name} · ${email}` : name,
        }
      })
      .sort((a, b) => a.label.localeCompare(b.label))
  }, [assignedMemberIds, editingEntity?.resource, memberCompanyUsers, roleAssignedUsers])

  const selectedMemberToAdd = React.useMemo(
    () => availableMembers.find((entry) => entry.membershipId === memberToAdd) ?? null,
    [availableMembers, memberToAdd]
  )

  const filteredAssignableMembers = React.useMemo(() => {
    const query = assignPickerQuery.trim().toLowerCase()
    if (!query) return availableMembers
    const tokens = query.split(/\s+/).filter(Boolean)
    return availableMembers.filter((user) => {
      const haystack =
        `${user.name} ${user.email} ${user.label} ${user.userId ?? ""} ${user.membershipId}`.toLowerCase()
      return tokens.every((token) => haystack.includes(token))
    })
  }, [assignPickerQuery, availableMembers])

  const displayedRolePermissionNames = rolePermissionNamesFromApi ?? editingRolePermissionNames

  const handleAssignMember = async () => {
    if (!token || !editingEntity) return
    if (editingEntity.resource !== "permissions" && editingEntity.resource !== "roles") return
    if (!memberToAdd) {
      toast.error(
        editingEntity.resource === "roles"
          ? "Select a user to assign this role."
          : "Select a user to assign this permission."
      )
      return
    }
    const membershipId = String(memberToAdd)
    const selected = availableMembers.find((entry) => entry.membershipId === membershipId)
    setMembersBusy(true)
    try {
      if (editingEntity.resource === "permissions") {
        await assignPermissionToCurrentCompanyUser(token, membershipId, editingEntity.id)
        showSuccessAlert("Permission assigned to user.")
        setAssignedMemberIds((prev) => {
          const next = new Set(prev)
          next.add(membershipId)
          return next
        })
      } else {
        // POST /api/roles/{roleId}/users  body: { user_id }
        const companyUser = memberCompanyUsers.find(
          (row) => companyUserMembershipId(row) === membershipId
        )
        const userId =
          selected?.userId ??
          (companyUser ? resolveRoleAssignUserId(companyUser) : null) ??
          membershipId
        if (!userId) {
          throw new Error(
            "Could not resolve user_id for the selected person. Check that the company user has a linked account."
          )
        }
        await assignUserToRole(token, editingEntity.id, userId)
        showSuccessAlert(
          selected?.name
            ? `Assigned ${selected.name} to this role.`
            : "Role assigned to user."
        )
        // Reload from GET /api/roles/{roleId}/users so the list stays accurate.
        setMembersRefreshKey((key) => key + 1)
      }
      setMemberToAdd("")
    } catch (errorObject) {
      const message =
        errorObject instanceof Error ? errorObject.message : "Failed to assign to user."
      showErrorAlert(message)
    } finally {
      setMembersBusy(false)
    }
  }

  const requestRevokeMember = (
    membershipId: string,
    userId?: string | null,
    displayName?: string
  ) => {
    if (!token || !editingEntity) return
    if (editingEntity.resource !== "permissions" && editingEntity.resource !== "roles") return
    setRevokeConfirm({
      membershipId,
      userId: userId ?? null,
      displayName: displayName?.trim() || "this person",
    })
  }

  const handleConfirmRevokeMember = async () => {
    if (!token || !editingEntity || !revokeConfirm) return
    if (editingEntity.resource !== "permissions" && editingEntity.resource !== "roles") return

    const { membershipId, userId, displayName: personLabel } = revokeConfirm
    setMembersBusy(true)
    try {
      if (editingEntity.resource === "permissions") {
        await revokePermissionFromCurrentCompanyUser(token, membershipId, editingEntity.id)
        showSuccessAlert("Permission removed from user.")
        setAssignedMemberIds((prev) => {
          const next = new Set(prev)
          next.delete(String(membershipId))
          return next
        })
      } else {
        // DELETE /api/roles/{roleId}/users/{userId}
        let resolvedUserId = userId
        if (!resolvedUserId) {
          const companyUser = memberCompanyUsers.find(
            (row) => companyUserMembershipId(row) === membershipId
          )
          resolvedUserId = companyUser
            ? resolveRoleAssignUserId(companyUser)
            : membershipId
        }
        if (!resolvedUserId) {
          throw new Error("Could not resolve user_id for this assignment.")
        }
        await revokeUserFromRole(token, editingEntity.id, resolvedUserId)
        showSuccessAlert(`Removed ${personLabel} from this role.`)
        setMembersRefreshKey((key) => key + 1)
      }
      setRevokeConfirm(null)
    } catch (errorObject) {
      const message =
        errorObject instanceof Error ? errorObject.message : "Failed to remove assignment."
      showErrorAlert(message)
    } finally {
      setMembersBusy(false)
    }
  }

  const handleRolePermissionsChange = async (nextNames: string[]) => {
    if (!token || !editingEntity || editingEntity.resource !== "roles") {
      return
    }

    const previous = new Set(displayedRolePermissionNames)
    const next = new Set(nextNames)
    const toAdd = nextNames.filter((name) => !previous.has(name))
    const toRemove = displayedRolePermissionNames.filter((name) => !next.has(name))

    if (toAdd.length === 0 && toRemove.length === 0) {
      return
    }

    // Optimistic UI update
    setEditingRolePermissionNames(nextNames)
    setRolePermissionNamesFromApi(nextNames)
    setMembersBusy(true)

    try {
      for (const name of toAdd) {
        const option = permissionOptions.find((entry) => entry.name === name)
        const permissionId = option?.id
        if (!permissionId) {
          throw new Error(`Unknown permission: ${name}`)
        }
        await assignPermissionToRole(token, editingEntity.id, permissionId)
      }
      for (const name of toRemove) {
        const option = permissionOptions.find((entry) => entry.name === name)
        const permissionId = option?.id
        if (!permissionId) {
          throw new Error(`Unknown permission: ${name}`)
        }
        await revokePermissionFromRole(token, editingEntity.id, permissionId)
      }
      setInitialEditingRolePermissionNames(nextNames)
      if (toAdd.length > 0 || toRemove.length > 0) {
        showSuccessAlert(
          toAdd.length > 0 && toRemove.length === 0
            ? "Permission assigned to role."
            : toRemove.length > 0 && toAdd.length === 0
              ? "Permission removed from role."
              : "Role permissions updated."
        )
      }
    } catch (errorObject) {
      // Revert on failure
      setEditingRolePermissionNames(Array.from(previous))
      setRolePermissionNamesFromApi(Array.from(previous))
      const message =
        errorObject instanceof Error ? errorObject.message : "Failed to update role permissions."
      showErrorAlert(message)
    } finally {
      setMembersBusy(false)
    }
  }

  return (
    <div className="w-full flex-col justify-start gap-4">
      <div className="flex flex-col gap-2 px-3 lg:px-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          {isAccessControlResource ? (
            <div className="flex min-w-0 flex-1 flex-wrap items-center gap-2">
              <div className="relative min-w-0 max-w-sm flex-1">
                <Input
                  value={accessControlSearch}
                  onChange={(event) => setAccessControlSearch(event.target.value)}
                  placeholder={
                    activeResource === "permissions"
                      ? "Search permissions by name, key, or description…"
                      : "Search roles by name, key, or description…"
                  }
                  className="h-9 w-full pr-16"
                  autoComplete="off"
                />
                {accessControlSearch.trim() ? (
                  <button
                    type="button"
                    className="absolute top-1/2 right-2 -translate-y-1/2 rounded px-1.5 py-0.5 text-[11px] font-medium text-muted-foreground hover:bg-muted hover:text-foreground"
                    onClick={() => setAccessControlSearch("")}
                  >
                    Clear
                  </button>
                ) : null}
              </div>
              <Badge variant="outline" className="border-slate-200 bg-slate-50 text-slate-700">
                {filteredAccessControlRows.length}
                {filteredAccessControlRows.length !== rows.length
                  ? ` of ${rows.length}`
                  : ""}{" "}
                {RESOURCE_LABELS[activeResource].toLowerCase()}
              </Badge>
            </div>
          ) : (
            <div />
          )}
          {canCreateResource && isAccessControlResource ? (
            <Drawer>
              <DrawerTrigger asChild>
                <Button variant="outline" size="sm">
                  <PlusIcon data-icon="inline-start" />
                  <span>
                    {activeResource === "roles" ? "Create role" : "Create permission"}
                  </span>
                </Button>
              </DrawerTrigger>
              <DrawerContent>
                <DrawerHeader>
                  <DrawerTitle>
                    Create {activeResource === "roles" ? "Role" : "Permission"}
                  </DrawerTitle>
                  <DrawerDescription>
                    {activeResource === "roles"
                      ? "Create a company role. You can assign permissions after creation."
                      : "Create a permission in the catalog."}
                  </DrawerDescription>
                </DrawerHeader>
                <div className="grid gap-3 px-4 pb-2">
                  <div className="space-y-1.5">
                    <Label>Name (key)</Label>
                    <Input
                      value={roleForm.name}
                      onChange={(event) =>
                        setRoleForm((prev) => ({ ...prev, name: event.target.value }))
                      }
                      placeholder={activeResource === "roles" ? "hr_manager" : "employees:read"}
                      className="font-mono text-sm"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label>Display name</Label>
                    <Input
                      value={roleForm.display_name}
                      onChange={(event) =>
                        setRoleForm((prev) => ({ ...prev, display_name: event.target.value }))
                      }
                      placeholder={activeResource === "roles" ? "HR Manager" : "Read employees"}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <Label>Description</Label>
                    <Input
                      value={roleForm.description}
                      onChange={(event) =>
                        setRoleForm((prev) => ({ ...prev, description: event.target.value }))
                      }
                      placeholder="Optional description"
                    />
                  </div>
                  {activeResource === "roles" ? (
                    <div className="max-h-64 overflow-y-auto rounded-lg border border-border/60 p-2">
                      <PermissionPicker
                        options={permissionOptions}
                        selectedNames={rolePermissionNames}
                        onChange={setRolePermissionNames}
                      />
                    </div>
                  ) : null}
                </div>
                <DrawerFooter>
                  <Button onClick={() => void handleCreate()} disabled={loading}>
                    Create
                  </Button>
                  <DrawerClose asChild>
                    <Button variant="outline">Cancel</Button>
                  </DrawerClose>
                </DrawerFooter>
              </DrawerContent>
            </Drawer>
          ) : null}

          {canCreateResource && !isAccessControlResource ? (
            <Drawer>
              <DrawerTrigger asChild>
                <Button variant="outline" size="sm">
                  <PlusIcon data-icon="inline-start" />
                  <span>
                    Create {RESOURCE_LABELS[activeResource].slice(0, -1).toLowerCase()}
                  </span>
                </Button>
              </DrawerTrigger>
              <DrawerContent>
                <DrawerHeader>
                  <DrawerTitle>
                    Create {RESOURCE_LABELS[activeResource].slice(0, -1)}
                  </DrawerTitle>
                  <DrawerDescription>Fill in the details and submit.</DrawerDescription>
                </DrawerHeader>
                <div className="grid gap-3 px-4 pb-2 md:grid-cols-2">
                {activeResource === "users" ? (
                  <>
                    <div className="space-y-1">
                      <Label>First Name</Label>
                      <Input
                        value={createUserForm.first_name}
                        onChange={(event) =>
                          setCreateUserForm((prev) => ({ ...prev, first_name: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Last Name</Label>
                      <Input
                        value={createUserForm.last_name}
                        onChange={(event) =>
                          setCreateUserForm((prev) => ({ ...prev, last_name: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Email</Label>
                      <Input
                        type="email"
                        value={createUserForm.email}
                        onChange={(event) =>
                          setCreateUserForm((prev) => ({ ...prev, email: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Phone</Label>
                      <Input
                        value={createUserForm.phone}
                        onChange={(event) =>
                          setCreateUserForm((prev) => ({ ...prev, phone: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>User Number</Label>
                      <Input
                        value={createUserForm.user_no}
                        onChange={(event) =>
                          setCreateUserForm((prev) => ({ ...prev, user_no: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Status</Label>
                      <Select
                        value={createUserForm.status}
                        onValueChange={(value) =>
                          setCreateUserForm((prev) => ({ ...prev, status: value ?? "active" }))
                        }
                      >
                        <SelectTrigger className="w-full">
                          <SelectValue placeholder="Select status" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="active">Active</SelectItem>
                          <SelectItem value="inactive">Inactive</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-1 md:col-span-2">
                      <Label>Password</Label>
                      <Input
                        type="password"
                        value={createUserForm.password}
                        onChange={(event) =>
                          setCreateUserForm((prev) => ({ ...prev, password: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-2 md:col-span-2">
                      <Label>Assign Roles</Label>
                      <div className="flex flex-wrap gap-2">
                        {roleOptions.map((role) => (
                          <button
                            key={role.id}
                            type="button"
                            onClick={() =>
                              toggleRoleId(createUserForm.roleIds, role.id, (next) =>
                                setCreateUserForm((prev) => ({ ...prev, roleIds: next }))
                              )
                            }
                            className={cn(
                              "rounded-md border px-2 py-1 text-sm",
                              createUserForm.roleIds.includes(role.id)
                                ? "border-primary bg-primary text-primary-foreground"
                                : "border-border bg-background"
                            )}
                          >
                            {role.label}
                          </button>
                        ))}
                      </div>
                    </div>
                  </>
                ) : null}

                {activeResource === "companies" ? (
                  <>
                    <div className="space-y-1">
                      <Label>Company Name</Label>
                      <Input
                        value={companyForm.company_name}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, company_name: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Company Slug</Label>
                      <Input
                        value={companyForm.company_slug}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, company_slug: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Admin First Name</Label>
                      <Input
                        value={companyForm.admin_first_name}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, admin_first_name: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Admin Last Name</Label>
                      <Input
                        value={companyForm.admin_last_name}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, admin_last_name: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Admin Email</Label>
                      <Input
                        type="email"
                        value={companyForm.admin_email}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, admin_email: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1">
                      <Label>Admin Phone</Label>
                      <Input
                        value={companyForm.admin_phone}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, admin_phone: event.target.value }))
                        }
                      />
                    </div>
                    <div className="space-y-1 md:col-span-2">
                      <Label>Admin Password</Label>
                      <Input
                        type="password"
                        value={companyForm.admin_password}
                        onChange={(event) =>
                          setCompanyForm((prev) => ({ ...prev, admin_password: event.target.value }))
                        }
                      />
                    </div>
                  </>
                ) : null}
                </div>
                <DrawerFooter>
                  <Button onClick={handleCreate} disabled={loading}>
                    Create Record
                  </Button>
                  <DrawerClose asChild>
                    <Button variant="outline">Cancel</Button>
                  </DrawerClose>
                </DrawerFooter>
              </DrawerContent>
            </Drawer>
          ) : null}
        </div>

        {activeResource === "users" ? (
          <div className="rounded-lg border p-3">
            <div className="grid gap-3 md:grid-cols-[minmax(0,1fr)_auto]">
              <div className="space-y-1">
                <SearchToggleField
                  className="w-full"
                  label="Search users"
                  value={searchInput}
                  placeholder="Search name, email, phone, user number"
                  onChange={(value) => {
                    setSearchInput(value)
                    if (!value) {
                      onUsersQueryChange({ search: "" })
                    }
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter") {
                      onUsersQueryChange({ search: searchInput })
                    }
                  }}
                />
              </div>
              <div className="grid gap-3 sm:grid-cols-2">
                <div className="space-y-1">
                  <Label>Sort By</Label>
                  <Select
                    value={usersQuery.sortBy}
                    onValueChange={(value) => {
                      if (!value) {
                        return
                      }
                      onUsersQueryChange({ sortBy: value })
                    }}
                  >
                    <SelectTrigger className="w-full">
                      <SelectValue placeholder="Sort by" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="created_at">Created Date</SelectItem>
                      <SelectItem value="first_name">First Name</SelectItem>
                      <SelectItem value="last_name">Last Name</SelectItem>
                      <SelectItem value="email">Email</SelectItem>
                      <SelectItem value="status">Status</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-1">
                  <Label>Order</Label>
                  <Select
                    value={sortOrder}
                    onValueChange={(value) => {
                      if (!value) {
                        return
                      }
                      onUsersQueryChange({ sortOrder: value as SortOrder })
                    }}
                  >
                    <SelectTrigger className="w-full">
                      <SelectValue placeholder="Order" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="DESC">DESC</SelectItem>
                      <SelectItem value="ASC">ASC</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </div>
            <div className="mt-3 flex items-center gap-2">
              <Button
                variant="outline"
                onClick={() => onUsersQueryChange({ search: searchInput })}
                disabled={loading}
              >
                Apply
              </Button>
              <Button
                variant="ghost"
                onClick={() => {
                  setSearchInput("")
                  onUsersQueryChange({ search: "" })
                }}
                disabled={loading}
              >
                Clear
              </Button>
            </div>
          </div>
        ) : null}
      </div>

      <div className="relative flex flex-col gap-3 overflow-auto px-3 lg:px-4">
          {isAccessControlResource ? (
            <div className="space-y-2">
              {!token ? (
                <div className="rounded-lg border border-dashed border-slate-300 bg-white/80 p-6 text-sm text-muted-foreground">
                  Sign in to load data.
                </div>
              ) : error ? (
                <div className="rounded-lg border border-rose-200 bg-rose-50 p-6 text-sm text-rose-700">
                  {error}
                </div>
              ) : (
                <ResizableTable
                  title={RESOURCE_LABELS[activeResource]}
                  data={accessControlTableRows}
                  columns={accessControlColumns}
                  getRowId={(row) => row.__id}
                  onRowSelect={(_id, row) => {
                    if (row?.__source) {
                      openAccessControlRow(row.__source)
                    }
                  }}
                  loading={loading}
                  itemsPerPage={20}
                  showExport={false}
                  enableAnimations={false}
                  storageKey={`access-control-${activeResource}`}
                />
              )}
            </div>
          ) : null}

          {!isAccessControlResource ? (
            <>
              <div className="rounded-lg border-0 bg-transparent shadow-none">
                <Table>
                  <TableHeader
                    className="sticky top-0 z-10"
                    style={{ backgroundColor: "var(--table-header-accent-bg)" }}
                  >
                    <TableRow>
                      {columns.map((column) => (
                        <TableHead key={column} style={{ color: "var(--table-header-accent)" }}>
                          {prettifyKey(column)}
                        </TableHead>
                      ))}
                      <TableHead className="w-16 text-right" style={{ color: "var(--table-header-accent)" }}>
                        Actions
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {!token ? (
                      <TableRow>
                        <TableCell colSpan={columns.length + 1} className="h-24 text-center text-muted-foreground">
                          Sign in to load data.
                        </TableCell>
                      </TableRow>
                    ) : loading ? (
                      <TableRow>
                        <TableCell colSpan={columns.length + 1} className="h-24 text-center text-muted-foreground">
                          Loading {RESOURCE_LABELS[activeResource].toLowerCase()}...
                        </TableCell>
                      </TableRow>
                    ) : error ? (
                      <TableRow>
                        <TableCell colSpan={columns.length + 1} className="h-24 text-center text-destructive">
                          {error}
                        </TableCell>
                      </TableRow>
                    ) : rows.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={columns.length + 1} className="h-24 text-center text-muted-foreground">
                          No records found.
                        </TableCell>
                      </TableRow>
                    ) : (
                      rows.map((row, index) => {
                        const rowId = getRowId(row, index + 1)
                        const rowLabel = stringifyValue(row.name ?? row.email ?? rowId)

                        return (
                          <TableRow key={`${rowId}`}>
                            {columns.map((column) => (
                              <TableCell key={`${rowId}-${column}`}>
                                <span className="block max-w-[24rem] truncate">{stringifyValue(row[column])}</span>
                              </TableCell>
                            ))}
                            <TableCell className="text-right">
                              <DropdownMenu>
                                <DropdownMenuTrigger
                                  render={<Button variant="ghost" size="icon" className="size-8" />}
                                >
                                  <EllipsisVerticalIcon />
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end" className="w-52">
                                  <DropdownMenuItem
                                    onClick={() => {
                                      void navigator.clipboard
                                        .writeText(JSON.stringify(row, null, 2))
                                        .then(() => {
                                          showSuccessAlert("Record details copied.")
                                        })
                                        .catch(() => {
                                          showErrorAlert("Clipboard access was denied.")
                                        })
                                    }}
                                  >
                                    <CopyIcon />
                                    Copy Details
                                  </DropdownMenuItem>

                                  {activeResource === "users" ? (
                                    <DropdownMenuItem
                                      onClick={() => {
                                        setEditingUser({ id: rowId, label: rowLabel })
                                        setEditUserForm(toUserForm(row))
                                      }}
                                    >
                                      <PencilIcon />
                                      Edit User
                                    </DropdownMenuItem>
                                  ) : null}

                                  {activeResource === "users" ? (
                                    <DropdownMenuItem
                                      onClick={() => {
                                        setTargetPasswordUser({ id: rowId, label: rowLabel })
                                        setTargetPassword("")
                                      }}
                                    >
                                      <KeyRoundIcon />
                                      Set Password
                                    </DropdownMenuItem>
                                  ) : null}

                                  {isEditableResource(activeResource) &&
                                  (canUpdateResource || canDeleteResource) ? (
                                    <DropdownMenuSeparator />
                                  ) : null}
                                  {isEditableResource(activeResource) && canDeleteResource ? (
                                    <DropdownMenuItem
                                      variant="destructive"
                                      onClick={() => void handleDelete(rowId)}
                                    >
                                      <Trash2Icon />
                                      Delete
                                    </DropdownMenuItem>
                                  ) : null}
                                </DropdownMenuContent>
                              </DropdownMenu>
                            </TableCell>
                          </TableRow>
                        )
                      })
                    )}
                  </TableBody>
                </Table>
              </div>

              <div className="flex items-center justify-between px-1 text-sm text-muted-foreground">
                <div>
                  {activeResource === "users"
                    ? `${usersTotal ?? rows.length} users found`
                    : `${rows.length} ${RESOURCE_LABELS[activeResource].toLowerCase()} loaded`}
                </div>
                <Badge variant="outline">{activeResource}</Badge>
              </div>

              {activeResource === "users" ? (
                <div className="flex items-center justify-between px-1 text-sm text-muted-foreground">
                  <div>
                    Page {usersQuery.page}
                    {usersTotalPages ? ` of ${usersTotalPages}` : ""}
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={!canPrevPage || loading}
                      onClick={() => onUsersQueryChange({ page: usersQuery.page - 1 })}
                    >
                      Previous
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={!canNextPage || loading}
                      onClick={() => onUsersQueryChange({ page: usersQuery.page + 1 })}
                    >
                      Next
                    </Button>
                  </div>
                </div>
              ) : null}
            </>
          ) : null}
      </div>

      <Drawer open={Boolean(editingUser)} onOpenChange={(open) => !open && setEditingUser(null)}>
        <DrawerContent>
          <DrawerHeader>
            <DrawerTitle>Edit {editingUser?.label ?? "user"}</DrawerTitle>
            <DrawerDescription>Update user details and assigned roles.</DrawerDescription>
          </DrawerHeader>
          <div className="grid gap-3 px-4 pb-2 md:grid-cols-2">
            <div className="space-y-1">
              <Label>First Name</Label>
              <Input
                value={editUserForm.first_name}
                onChange={(event) =>
                  setEditUserForm((prev) => ({ ...prev, first_name: event.target.value }))
                }
              />
            </div>
            <div className="space-y-1">
              <Label>Last Name</Label>
              <Input
                value={editUserForm.last_name}
                onChange={(event) =>
                  setEditUserForm((prev) => ({ ...prev, last_name: event.target.value }))
                }
              />
            </div>
            <div className="space-y-1">
              <Label>Email</Label>
              <Input
                type="email"
                value={editUserForm.email}
                onChange={(event) =>
                  setEditUserForm((prev) => ({ ...prev, email: event.target.value }))
                }
              />
            </div>
            <div className="space-y-1">
              <Label>Phone</Label>
              <Input
                value={editUserForm.phone}
                onChange={(event) =>
                  setEditUserForm((prev) => ({ ...prev, phone: event.target.value }))
                }
              />
            </div>
            <div className="space-y-1">
              <Label>User Number</Label>
              <Input
                value={editUserForm.user_no}
                onChange={(event) =>
                  setEditUserForm((prev) => ({ ...prev, user_no: event.target.value }))
                }
              />
            </div>
            <div className="space-y-1">
              <Label>Status</Label>
              <Select
                value={editUserForm.status}
                onValueChange={(value) =>
                  setEditUserForm((prev) => ({ ...prev, status: value ?? "active" }))
                }
              >
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2 md:col-span-2">
              <Label>Assigned Roles</Label>
              <div className="flex flex-wrap gap-2">
                {roleOptions.map((role) => (
                  <button
                    key={role.id}
                    type="button"
                    onClick={() =>
                      toggleRoleId(editUserForm.roleIds, role.id, (next) =>
                        setEditUserForm((prev) => ({ ...prev, roleIds: next }))
                      )
                    }
                    className={cn(
                      "rounded-md border px-2 py-1 text-sm",
                      editUserForm.roleIds.includes(role.id)
                        ? "border-primary bg-primary text-primary-foreground"
                        : "border-border bg-background"
                    )}
                  >
                    {role.label}
                  </button>
                ))}
              </div>
            </div>
          </div>
          <DrawerFooter>
            <Button onClick={handleSaveUserEdit} disabled={loading || !editingUser}>
              Save Changes
            </Button>
            <DrawerClose asChild>
              <Button variant="outline">Cancel</Button>
            </DrawerClose>
          </DrawerFooter>
        </DrawerContent>
      </Drawer>

      <Drawer
        open={Boolean(targetPasswordUser)}
        onOpenChange={(open) => !open && setTargetPasswordUser(null)}
      >
        <DrawerContent>
          <DrawerHeader>
            <DrawerTitle>Set Password for {targetPasswordUser?.label ?? "user"}</DrawerTitle>
            <DrawerDescription>Update user password</DrawerDescription>
          </DrawerHeader>
          <div className="space-y-1 px-4 pb-2">
            <Label>New Password</Label>
            <Input
              type="password"
              value={targetPassword}
              onChange={(event) => setTargetPassword(event.target.value)}
            />
          </div>
          <DrawerFooter>
            <Button onClick={handleSetPassword} disabled={loading || !targetPasswordUser}>
              Update Password
            </Button>
            <DrawerClose asChild>
              <Button variant="outline">Cancel</Button>
            </DrawerClose>
          </DrawerFooter>
        </DrawerContent>
      </Drawer>

      <Sheet
        open={Boolean(editingEntity)}
        onOpenChange={(open) => {
          if (!open) {
            setEditingEntity(null)
            setInitialEditingEntityForm(EMPTY_ENTITY_FORM)
            setEditingRolePermissionNames([])
            setInitialEditingRolePermissionNames([])
          }
        }}
      >
        <SheetContent
          side="right"
          className="flex w-full flex-col gap-0 overflow-hidden bg-background p-0 data-[side=right]:w-full sm:data-[side=right]:max-w-none sm:data-[side=right]:w-[min(100vw-1rem,34rem)]"
        >
          <SheetHeader className="shrink-0 space-y-3 px-6 pb-0 pt-5 text-left">
            <div className="pr-8">
              <SheetTitle className="text-xl font-semibold tracking-tight text-foreground">
                {editingEntity?.label ?? "Details"}
              </SheetTitle>
              <SheetDescription className="mt-1 text-sm text-muted-foreground">
                {editingEntity?.resource === "roles"
                  ? "Review role details, assigned people, and included permissions."
                  : "Review this permission and manage direct user grants."}
              </SheetDescription>
            </div>
            <DetailTabs
              tabs={
                editingEntity?.resource === "roles"
                  ? [
                      { id: "general", label: "General" },
                      { id: "assigned", label: "Assigned" },
                      { id: "permissions", label: "Permissions" },
                    ]
                  : [
                      { id: "general", label: "General" },
                      { id: "assigned", label: "Assigned" },
                    ]
              }
              value={detailSheetTab}
              onChange={setDetailSheetTab}
            />
          </SheetHeader>

          <div className="flex min-h-0 flex-1 flex-col overflow-hidden px-6 py-4">
            {detailSheetTab === "general" ? (
              <div className="space-y-4 overflow-y-auto">
                {canUpdateResource ? (
                  <>
                    <div className="space-y-1.5">
                      <Label htmlFor="entity-display-name">Display name</Label>
                      <Input
                        id="entity-display-name"
                        value={editingEntityForm.display_name}
                        onChange={(event) =>
                          setEditingEntityForm((prev) => ({
                            ...prev,
                            display_name: event.target.value,
                          }))
                        }
                      />
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="entity-name">
                        {editingEntity?.resource === "roles" ? "Name (key)" : "Name"}
                      </Label>
                      <Input
                        id="entity-name"
                        value={editingEntityForm.name}
                        onChange={(event) =>
                          setEditingEntityForm((prev) => ({
                            ...prev,
                            name: event.target.value,
                          }))
                        }
                        className="font-mono text-sm"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <Label htmlFor="entity-description">Description</Label>
                      <Input
                        id="entity-description"
                        value={editingEntityForm.description}
                        onChange={(event) =>
                          setEditingEntityForm((prev) => ({
                            ...prev,
                            description: event.target.value,
                          }))
                        }
                      />
                    </div>
                  </>
                ) : (
                  <>
                    <div className="space-y-1">
                      <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                        Display name
                      </p>
                      <p className="text-sm font-medium text-foreground">
                        {editingEntityForm.display_name || editingEntity?.label || "—"}
                      </p>
                    </div>
                    {editingEntity?.resource === "roles" ? (
                      <div className="space-y-1">
                        <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                          Name
                        </p>
                        <p className="font-mono text-sm text-foreground">
                          {editingEntityForm.name || "—"}
                        </p>
                      </div>
                    ) : null}
                    <div className="space-y-1">
                      <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                        Description
                      </p>
                      <p className="text-sm leading-relaxed text-foreground">
                        {editingEntityForm.description || "No description provided."}
                      </p>
                    </div>
                  </>
                )}
                {editingEntity?.resource === "roles" ? (
                  <div className="space-y-1">
                    <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
                      Permissions included
                    </p>
                    <p className="text-sm text-foreground">
                      {displayedRolePermissionNames.length} permission
                      {displayedRolePermissionNames.length === 1 ? "" : "s"}
                    </p>
                  </div>
                ) : null}
              </div>
            ) : null}

            {detailSheetTab === "assigned" ? (
              <div className="flex min-h-0 flex-1 flex-col gap-2.5 overflow-hidden">
                <div className="flex shrink-0 items-center gap-2">
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-foreground">
                      {editingEntity?.resource === "roles"
                        ? "Assigned people"
                        : "Assigned people"}
                    </p>
                    <p className="text-[11px] text-muted-foreground">
                      {editingEntity?.resource === "roles"
                        ? "People who currently have this role."
                        : "People with this permission assigned directly."}
                    </p>
                  </div>
                  <span className="shrink-0 rounded-full border border-slate-200 bg-slate-50 px-2 py-0.5 text-[10px] font-medium text-slate-600">
                    {membersLoading
                      ? "…"
                      : `${
                          editingEntity?.resource === "roles"
                            ? roleAssignedUsers.length
                            : assignedMemberIds.size
                        } assigned`}
                  </span>
                  {canManageAssignments && editingEntity?.resource === "roles" ? (
                    <Button
                      type="button"
                      size="sm"
                      className="h-8 shrink-0"
                      disabled={membersLoading || membersBusy}
                      onClick={() => {
                        setMemberToAdd("")
                        setAssignPickerQuery("")
                        setPeopleDialogOpen(true)
                      }}
                    >
                      <UserPlusIcon className="size-3.5" data-icon="inline-start" />
                      Add
                    </Button>
                  ) : null}
                </div>

                <Input
                  value={memberSearch}
                  onChange={(event) => setMemberSearch(event.target.value)}
                  placeholder="Search assigned people…"
                  className="h-8 shrink-0 text-xs"
                />

                <div className="min-h-0 flex-1 overflow-y-auto rounded-lg border border-border/60">
                  {membersLoading ? (
                    <SectionLoader
                      label={
                        editingEntity?.resource === "roles"
                          ? "Loading assigned people…"
                          : "Loading permission assignments…"
                      }
                    />
                  ) : membersError ? (
                    <p className="px-3 py-8 text-center text-sm text-rose-600">{membersError}</p>
                  ) : assignedMembers.length === 0 ? (
                    <div className="flex flex-col items-center gap-2 px-3 py-8 text-center">
                      <UsersIcon className="size-5 text-muted-foreground/60" />
                      <p className="text-xs text-muted-foreground">
                        {editingEntity?.resource === "roles"
                          ? roleAssignedUsers.length === 0 && !memberSearch.trim()
                            ? "No one is assigned this role yet."
                            : "No people match your search."
                          : assignedMemberIds.size === 0
                            ? "No one has this permission assigned directly."
                            : "No people match your search."}
                      </p>
                      {canManageAssignments &&
                      editingEntity?.resource === "roles" &&
                      roleAssignedUsers.length === 0 &&
                      !memberSearch.trim() ? (
                        <Button
                          type="button"
                          size="sm"
                          variant="outline"
                          className="mt-1 h-8"
                          onClick={() => setPeopleDialogOpen(true)}
                        >
                          <UserPlusIcon className="size-3.5" data-icon="inline-start" />
                          Add person
                        </Button>
                      ) : null}
                    </div>
                  ) : (
                    <ul className="divide-y divide-border/50">
                      {assignedMembers.map((user) => (
                        <li
                          key={`${user.membershipId}-${user.userId ?? "x"}`}
                          className="flex items-center gap-2.5 px-2.5 py-2"
                        >
                          <div className="flex size-7 shrink-0 items-center justify-center rounded-full bg-primary/10 text-[10px] font-semibold text-primary">
                            {user.name
                              .split(/\s+/)
                              .slice(0, 2)
                              .map((part) => part[0]?.toUpperCase() ?? "")
                              .join("") || "?"}
                          </div>
                          <div className="min-w-0 flex-1">
                            <p className="truncate text-xs font-medium text-foreground">
                              {user.name}
                            </p>
                            <p className="truncate text-[10px] text-muted-foreground">
                              {user.email}
                            </p>
                          </div>
                          {canManageAssignments ? (
                            <button
                              type="button"
                              className="inline-flex size-7 shrink-0 items-center justify-center rounded-md text-rose-600 transition-colors hover:bg-rose-50"
                              title={`Remove ${user.name}`}
                              aria-label={`Remove ${user.name}`}
                              disabled={membersBusy}
                              onClick={() =>
                                requestRevokeMember(
                                  user.membershipId,
                                  user.userId,
                                  user.name
                                )
                              }
                            >
                              <UserMinusIcon className="size-3.5" />
                            </button>
                          ) : null}
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>
            ) : null}

            {detailSheetTab === "permissions" && editingEntity?.resource === "roles" ? (
              <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden">
                <p className="shrink-0 text-sm text-muted-foreground">
                  {canManageAssignments
                    ? "Toggle permissions to assign or revoke them on this role immediately."
                    : "Permissions currently included in this role."}
                </p>
                <div className="min-h-0 flex-1 overflow-y-auto pr-1">
                  {membersLoading || rolePermissionsLoading ? (
                    <SectionLoader label="Loading role permissions…" />
                  ) : canManageAssignments ? (
                    <PermissionPicker
                      options={permissionOptions}
                      selectedNames={displayedRolePermissionNames}
                      onChange={(next) => {
                        void handleRolePermissionsChange(next)
                      }}
                      className={cn(membersBusy ? "pointer-events-none opacity-70" : "")}
                    />
                  ) : (
                    <MicrosoftPermissionList
                      options={permissionOptions}
                      selectedNames={displayedRolePermissionNames}
                      emptyLabel="No permissions are included in this role yet."
                    />
                  )}
                </div>
              </div>
            ) : null}
          </div>

          <SheetFooter className="shrink-0 border-t border-border/70 px-6 py-3">
            {canUpdateResource && detailSheetTab === "general" && isEditingEntityDirty ? (
              <Button
                type="button"
                disabled={loading || membersBusy}
                onClick={() => void handleSaveEntityEdit()}
              >
                Save changes
              </Button>
            ) : null}
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                setEditingEntity(null)
                setInitialEditingEntityForm(EMPTY_ENTITY_FORM)
                setEditingRolePermissionNames([])
                setInitialEditingRolePermissionNames([])
                setRolePermissionNamesFromApi(null)
              }}
            >
              Close
            </Button>
          </SheetFooter>
        </SheetContent>
      </Sheet>

      <AlertDialog
        open={Boolean(revokeConfirm)}
        onOpenChange={(open) => {
          if (!open && !membersBusy) {
            setRevokeConfirm(null)
          }
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {editingEntity?.resource === "roles"
                ? "Remove from role?"
                : "Remove permission?"}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {editingEntity?.resource === "roles"
                ? `Remove ${revokeConfirm?.displayName ?? "this person"} from this role? They will lose permissions granted only through this role.`
                : `Remove ${revokeConfirm?.displayName ?? "this person"}'s direct permission grant?`}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={membersBusy} />
            <Button
              type="button"
              variant="destructive"
              disabled={membersBusy}
              onClick={() => void handleConfirmRevokeMember()}
            >
              {membersBusy ? (
                <>
                  <Loader2Icon className="size-3.5 animate-spin" data-icon="inline-start" />
                  Removing…
                </>
              ) : (
                "Remove"
              )}
            </Button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Add-person dialog only (assigned list stays on the Assigned tab) */}
      <Dialog
        open={peopleDialogOpen && editingEntity?.resource === "roles"}
        onOpenChange={(open) => {
          setPeopleDialogOpen(open)
          if (!open) {
            setMemberToAdd("")
            setAssignPickerQuery("")
          }
        }}
      >
        <DialogPopup
          className="flex max-h-[min(90vh,32rem)] w-[min(96vw,28rem)] flex-col gap-0 overflow-hidden p-0 sm:max-w-[28rem]"
          from="center"
        >
          <DialogHeader className="shrink-0 space-y-1 border-b border-border/60 px-5 py-4 text-left">
            <DialogTitle className="text-base">Add person</DialogTitle>
            <DialogDescription className="text-xs">
              {editingEntity?.label
                ? `Search and assign someone to “${editingEntity.label}”.`
                : "Search and assign someone to this role."}
            </DialogDescription>
          </DialogHeader>

          <div className="flex min-h-0 flex-1 flex-col gap-2.5 overflow-hidden px-5 py-3">
            <Input
              value={assignPickerQuery}
              onChange={(event) => setAssignPickerQuery(event.target.value)}
              placeholder={
                availableMembers.length === 0
                  ? "Everyone is already assigned"
                  : "Search people to assign…"
              }
              className="h-8 shrink-0 text-xs"
              disabled={membersBusy || membersLoading || availableMembers.length === 0}
              autoFocus
            />
            {selectedMemberToAdd ? (
              <p className="shrink-0 text-[11px] text-muted-foreground">
                Selected:{" "}
                <span className="font-medium text-foreground">
                  {selectedMemberToAdd.label}
                </span>
              </p>
            ) : null}
            <div className="min-h-0 flex-1 overflow-y-auto rounded-lg border border-border/60 bg-background">
              {membersLoading ? (
                <p className="px-3 py-6 text-center text-xs text-muted-foreground">
                  Loading people…
                </p>
              ) : availableMembers.length === 0 ? (
                <p className="px-3 py-6 text-center text-xs text-muted-foreground">
                  Everyone is already assigned.
                </p>
              ) : filteredAssignableMembers.length === 0 ? (
                <p className="px-3 py-6 text-center text-xs text-muted-foreground">
                  No people match “{assignPickerQuery.trim()}”.
                </p>
              ) : (
                <ul className="divide-y divide-border/50">
                  {filteredAssignableMembers.map((user) => {
                    const selected = user.membershipId === memberToAdd
                    return (
                      <li key={user.membershipId}>
                        <button
                          type="button"
                          disabled={membersBusy}
                          onClick={() => setMemberToAdd(user.membershipId)}
                          className={cn(
                            "flex w-full items-start gap-2 px-2.5 py-2 text-left transition-colors",
                            selected ? "bg-primary/10 text-foreground" : "hover:bg-muted/50"
                          )}
                        >
                          <span
                            className={cn(
                              "mt-0.5 flex size-3.5 shrink-0 items-center justify-center rounded-full border",
                              selected
                                ? "border-primary bg-primary text-primary-foreground"
                                : "border-border"
                            )}
                          >
                            {selected ? (
                              <CheckIcon className="size-2" strokeWidth={3} />
                            ) : null}
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className="block truncate text-xs font-medium">
                              {user.name}
                            </span>
                            <span className="block truncate text-[10px] text-muted-foreground">
                              {user.email !== "—"
                                ? user.email
                                : `ID ${user.userId ?? user.membershipId}`}
                            </span>
                          </span>
                        </button>
                      </li>
                    )
                  })}
                </ul>
              )}
            </div>
          </div>

          <DialogFooter className="shrink-0 border-t border-border/60 px-5 py-3">
            <DialogClose
              render={
                <Button type="button" variant="outline" size="sm">
                  Cancel
                </Button>
              }
            />
            <Button
              type="button"
              size="sm"
              disabled={!memberToAdd || membersBusy || membersLoading}
              onClick={() => void handleAssignMember()}
            >
              {membersBusy ? (
                <>
                  <Loader2Icon className="size-3.5 animate-spin" data-icon="inline-start" />
                  Assigning…
                </>
              ) : (
                <>
                  <UserPlusIcon className="size-3.5" data-icon="inline-start" />
                  Assign
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogPopup>
      </Dialog>
    </div>
  )
}

"use client"

import * as React from "react"
import {
  Calendar as HeroCalendar,
} from "@heroui/react"
import {
  fromDateToLocal,
  getLocalTimeZone,
  type DateValue,
} from "@internationalized/date"

import { cn } from "@/lib/utils"

type CalendarProps = {
  className?: string
  mode?: "single"
  captionLayout?: string
  selected?: Date
  onSelect?: (date: Date | undefined) => void
  fromYear?: number
  toYear?: number
}

function toCalendarValue(date?: Date) {
  if (!date) {
    return undefined
  }

  return fromDateToLocal(new Date(date.getFullYear(), date.getMonth(), date.getDate()))
}

function fromCalendarValue(value: DateValue | null | undefined) {
  if (!value) {
    return undefined
  }

  if ("timeZone" in value) {
    return value.toDate()
  }

  return value.toDate(getLocalTimeZone())
}

export function Calendar({
  className,
  selected,
  onSelect,
  fromYear,
  toYear,
  mode: _mode,
  captionLayout: _captionLayout,
}: CalendarProps) {
  const value = React.useMemo(() => toCalendarValue(selected), [selected])
  const minValue = React.useMemo(
    () => (typeof fromYear === "number" ? toCalendarValue(new Date(fromYear, 0, 1)) : undefined),
    [fromYear]
  )
  const maxValue = React.useMemo(
    () => (typeof toYear === "number" ? toCalendarValue(new Date(toYear, 11, 31)) : undefined),
    [toYear]
  )

  return (
    <div
      className={cn(
        "w-fit rounded-2xl border border-slate-200 bg-white p-3 shadow-xl shadow-slate-200/70 dark:border-slate-700 dark:bg-slate-900 dark:shadow-slate-950/40",
        className
      )}
    >
      <HeroCalendar
        aria-label="Event date"
        value={value}
        minValue={minValue}
        maxValue={maxValue}
        onChange={(nextValue) => onSelect?.(fromCalendarValue(nextValue))}
        className="calendar-modern w-full min-w-[18rem]"
      >
        <HeroCalendar.Header className="mb-3 grid grid-cols-[auto_1fr_auto] items-center gap-2">
          <HeroCalendar.NavButton
            slot="previous"
            className="rounded-full border border-slate-200 bg-white text-slate-700 shadow-sm hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100 dark:hover:bg-slate-800"
          />
          <HeroCalendar.YearPickerTrigger className="flex items-center justify-center gap-2 rounded-full bg-slate-100 px-4 py-2 text-sm font-semibold text-slate-900 transition hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-100 dark:hover:bg-slate-700">
            <HeroCalendar.YearPickerTriggerHeading />
            <HeroCalendar.YearPickerTriggerIndicator />
          </HeroCalendar.YearPickerTrigger>
          <HeroCalendar.NavButton
            slot="next"
            className="rounded-full border border-slate-200 bg-white text-slate-700 shadow-sm hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-950 dark:text-slate-100 dark:hover:bg-slate-800"
          />
        </HeroCalendar.Header>

        <HeroCalendar.Grid className="w-full">
          <HeroCalendar.GridHeader>
            {(day) => (
              <HeroCalendar.HeaderCell className="text-center text-[0.72rem] font-semibold uppercase tracking-[0.18em] text-slate-400 dark:text-slate-500">
                {day}
              </HeroCalendar.HeaderCell>
            )}
          </HeroCalendar.GridHeader>
          <HeroCalendar.GridBody>
            {(date) => (
              <HeroCalendar.Cell
                date={date}
                className="rounded-xl text-sm font-medium text-slate-700 transition data-[hovered=true]:bg-slate-100 data-[today=true]:ring-1 data-[today=true]:ring-slate-300 data-[selected=true]:bg-slate-900 data-[selected=true]:text-white data-[outside-month=true]:text-slate-300 data-[disabled=true]:text-slate-300 dark:text-slate-100 dark:data-[hovered=true]:bg-slate-800 dark:data-[today=true]:ring-slate-600 dark:data-[selected=true]:bg-white dark:data-[selected=true]:text-slate-900 dark:data-[outside-month=true]:text-slate-600 dark:data-[disabled=true]:text-slate-700"
              />
            )}
          </HeroCalendar.GridBody>
        </HeroCalendar.Grid>

        <HeroCalendar.YearPickerGrid>
          <HeroCalendar.YearPickerGridBody>
            {({ year }) => (
              <HeroCalendar.YearPickerCell
                year={year}
                className="rounded-xl text-sm font-medium text-slate-700 transition data-[hovered=true]:bg-slate-100 data-[selected=true]:bg-slate-900 data-[selected=true]:text-white dark:text-slate-100 dark:data-[hovered=true]:bg-slate-800 dark:data-[selected=true]:bg-white dark:data-[selected=true]:text-slate-900"
              />
            )}
          </HeroCalendar.YearPickerGridBody>
        </HeroCalendar.YearPickerGrid>
      </HeroCalendar>
    </div>
  )
}

"use client";

import { useState, useEffect, useMemo, useRef } from "react";
import { motion, useReducedMotion, AnimatePresence } from "framer-motion";
import { Download, ChevronDown } from "lucide-react";
import { Resizable } from "react-resizable";
import "react-resizable/css/styles.css";
import React from "react";
import { useTheme } from "@/components/theme-provider";
import { useRenderDiagnostics } from "@/hooks/use-render-diagnostics";
import { cn } from "@/lib/utils";

export interface Employee {
  id: string;
  name: string;
  email: string;
  department: string;
  position: string;
  salary?: number;
  hireDate: string;
  status: "active" | "inactive" | "on-leave";
  avatar?: string;
}

export interface Column<T = any> {
  key: string;
  label: string;
  defaultWidth?: number;
  sortable?: boolean;
  render?: (item: T) => React.ReactNode;
}

function isMeaningfulTableValue(value: React.ReactNode): boolean {
  if (value == null || value === false) {
    return false;
  }

  if (typeof value === "string") {
    const normalized = value.trim();
    return normalized !== "" && normalized !== "-" && normalized !== "—" && normalized.toLowerCase() !== "null";
  }

  if (typeof value === "number") {
    return true;
  }

  if (typeof value === "boolean") {
    return value;
  }

  if (Array.isArray(value)) {
    return value.some((entry) => isMeaningfulTableValue(entry));
  }

  return React.isValidElement(value);
}

interface ResizableTableProps<T = any> {
  title?: string;
  data?: T[];
  columns?: Column<T>[];
  // legacy support
  employees?: Employee[];
  onEmployeeSelect?: (employeeId: string) => void;
  onRowSelect?: (rowId: string, row?: T) => void;
  onColumnResize?: (columnKey: string, newWidth: number) => void;
  className?: string;
  enableAnimations?: boolean;
  getRowId?: (item: T, index: number) => string;
  itemsPerPage?: number;
  loading?: boolean;
  showCheckboxes?: boolean;
  /** When false, hides the table toolbar Export dropdown. Default true. */
  showExport?: boolean;
  storageKey?: string;
}

type SortOrder = "asc" | "desc";

export function ResizableTable<T = any>({
  title = "Item",
  data,
  columns,
  employees,
  onEmployeeSelect,
  onRowSelect,
  onColumnResize,
  className = "",
  enableAnimations = true,
  getRowId,
  itemsPerPage = 10,
  loading = false,
  showCheckboxes = false,
  showExport = true,
  storageKey
}: ResizableTableProps<T> = {}) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [mounted, setMounted] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortField, setSortField] = useState<string | null>(null);
  const [sortOrder, setSortOrder] = useState<SortOrder>("asc");
  const [showSortMenu, setShowSortMenu] = useState(false);
  const [showExportMenu, setShowExportMenu] = useState(false);

  const overflowRef = useRef<HTMLDivElement>(null);
  const [containerWidth, setContainerWidth] = useState(0);

  const shouldReduceMotion = useReducedMotion();
  const { resolvedTheme } = useTheme();
  const isDark = resolvedTheme === "dark";

  useRenderDiagnostics("ResizableTable", {
    title,
    rows: Array.isArray(data) ? data.length : Array.isArray(employees) ? employees.length : 0,
    loading,
  });

  // Normalize data
  // IMPORTANT: Always respect explicitly passed data (even empty array) so real pages
  // don't flash fake demo employees like "Sarah Chen".
  const tableData: any[] = useMemo(() => {
    if (Array.isArray(data)) return data;
    if (Array.isArray(employees)) return employees;
    return []; // safe default - no fake demo data in production tables
  }, [data, employees]);

  // Normalize columns (auto-generate for legacy employee-like data if needed)
  const tableColumns: Column<any>[] = useMemo(() => {
    if (columns && columns.length > 0) {
      return columns;
    }
    // Legacy / auto detection
    const sample = tableData[0] || {};
    const hasEmployeeShape = !!(sample.name || sample.email || sample.department);

    if (hasEmployeeShape || employees) {
      return [
        { key: "name", label: title || "Name", defaultWidth: 140, sortable: true },
        { key: "email", label: "Email", defaultWidth: 160, sortable: true },
        { key: "department", label: "Department", defaultWidth: 100, sortable: true },
        { key: "position", label: "Position", defaultWidth: 130, sortable: true },
        { key: "hireDate", label: "Hire Date", defaultWidth: 85, sortable: true },
        { key: "status", label: "Status", defaultWidth: 75, sortable: true },
      ];
    }

    // Generic fallback from first item's keys — skip internal fields to avoid "extra columns"
    const skip = new Set(["id", "_id", "avatar", "created_at", "updated_at", "createdAt", "updatedAt", "deleted_at", "salary", "base_salary", "compensation"]);
    const keys = Object.keys(sample).filter((k) => !skip.has(k) && !k.startsWith("_"));
    return keys.filter(k => !['id','employee_id','user_id','created_by'].includes(k)).slice(0, 6).map((key) => ({
      key,
      label: key
        .replace(/([A-Z])/g, " $1")
        .replace(/^./, (s) => s.toUpperCase())
        .trim(),
      defaultWidth: 105,
      sortable: true,
    }));
  }, [columns, tableData, employees, title]);

  const visibleTableColumns: Column<any>[] = useMemo(() => {
    if (tableData.length === 0) {
      return tableColumns;
    }

    if (columns && columns.length > 0) {
      return tableColumns;
    }

    return tableColumns.filter((col) => {
      if (col.key === "actions") {
        return true;
      }

      return tableData.some((item) => {
        const value = col.render ? col.render(item) : item?.[col.key];
        return isMeaningfulTableValue(value);
      });
    });
  }, [columns, tableColumns, tableData]);

  // Column keys for widths (optional checkbox + data columns)
  const allColumnKeys = useMemo(
    () =>
      showCheckboxes
        ? ["checkbox", ...visibleTableColumns.map((c) => c.key)]
        : visibleTableColumns.map((c) => c.key),
    [showCheckboxes, visibleTableColumns]
  );

  // Column widths state - initialize from columns
  const effectiveStorageKey = storageKey || (title ? `resizable-table:${title.toLowerCase().replace(/\s+/g, '-')}` : 'resizable-table:default');

  const [columnWidths, setColumnWidths] = useState<Record<string, number>>(() => {
    const initial: Record<string, number> = showCheckboxes ? { checkbox: 36 } : {};
    visibleTableColumns.forEach((col) => {
      initial[col.key] = col.defaultWidth ?? 105; // more compact default
    });

    // Load persisted widths if available
    if (typeof window !== 'undefined') {
      try {
        const saved = localStorage.getItem(effectiveStorageKey);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed && typeof parsed === 'object') {
            Object.keys(parsed).forEach((k) => {
              if (typeof parsed[k] === 'number' && initial[k] !== undefined) {
                initial[k] = Math.max(60, Math.min(500, parsed[k]));
              }
            });
          }
        }
      } catch {}
    }

    return initial;
  });

  // Compute display widths: start from base/persisted, then proportionally expand
  // all growable columns if their sum < available container width. This makes the
  // table fill the full width (no empty space on right), while keeping header
  // and cell sizes identical per column.
  const displayWidths = useMemo(() => {
    const res: Record<string, number> = {};
    const cbW = showCheckboxes ? (columnWidths.checkbox || 36) : 0;
    res.checkbox = cbW;
    let baseSum = cbW;
    visibleTableColumns.forEach((col) => {
      const w = columnWidths[col.key] ?? col.defaultWidth ?? 105;
      res[col.key] = w;
      baseSum += w;
    });
    if (containerWidth > 0 && baseSum < containerWidth) {
      const extra = containerWidth - baseSum;
      const growSum = baseSum - cbW;
      if (growSum > 0) {
        visibleTableColumns.forEach((col) => {
          const w = res[col.key];
          res[col.key] = w + extra * (w / growSum);
        });
      }
    }
    return res;
  }, [columnWidths, visibleTableColumns, containerWidth, showCheckboxes]);

  // Unified display widths for both headers and content cells (ensures they match exactly per column)
  const getColumnWidth = (col: Column<any> | string) => {
    const key = typeof col === 'string' ? col : col.key;
    return displayWidths[key] ?? columnWidths[key] ?? (typeof col === 'string' ? 36 : col.defaultWidth ?? 105);
  };

  // Reset widths if columns definition changes significantly
  useEffect(() => {
    setColumnWidths((prev) => {
      const next: Record<string, number> = showCheckboxes ? { checkbox: prev.checkbox || 36 } : {};
      visibleTableColumns.forEach((col) => {
        next[col.key] = prev[col.key] ?? col.defaultWidth ?? 105;
      });
      return next;
    });
  }, [visibleTableColumns, showCheckboxes]);



  const ITEMS_PER_PAGE = itemsPerPage;

  useEffect(() => {
    setMounted(true);
  }, []);

  // Measure available width for filling the table
  useEffect(() => {
    const el = overflowRef.current;
    if (!el) return;
    const update = () => {
      const w = el.clientWidth || 0;
      setContainerWidth(w);
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(el);
    window.addEventListener('resize', update);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', update);
    };
  }, []);

  const getRowIdentifier = (item: any, index: number): string => {
    if (getRowId) return getRowId(item, index);
    return String(
      item?.id ?? item?.employee_id ?? item?.user_id ?? item?.employeeNo ?? item?.no ?? item?.key ?? index
    );
  };

  const handleRowSelect = (rowId: string, item?: any) => {
    setSelectedIds((prev) => {
      if (prev.includes(rowId)) {
        return prev.filter((id) => id !== rowId);
      } else {
        return [...prev, rowId];
      }
    });
    if (onRowSelect) {
      onRowSelect(rowId, item);
    }
    if (onEmployeeSelect) {
      onEmployeeSelect(rowId);
    }
  };

  const handleSelectAll = () => {
    const pageIds = paginatedData.map((item, idx) => getRowIdentifier(item, idx));
    if (selectedIds.length === pageIds.length && pageIds.length > 0) {
      setSelectedIds((prev) => prev.filter((id) => !pageIds.includes(id)));
    } else {
      setSelectedIds((prev) => {
        const others = prev.filter((id) => !pageIds.includes(id));
        return [...others, ...pageIds];
      });
    }
  };

  const handleSort = (field: string) => {
    if (sortField === field) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortOrder("asc");
    }
    setShowSortMenu(false);
    setCurrentPage(1);
  };

  const clearSort = () => {
    setSortField(null);
    setSortOrder("asc");
    setShowSortMenu(false);
    setCurrentPage(1);
  };

  const sortedData = useMemo(() => {
    if (!sortField) return tableData;

    return [...tableData].sort((a, b) => {
      let aVal: any = a?.[sortField];
      let bVal: any = b?.[sortField];

      const lowerField = sortField.toLowerCase();
      if (lowerField.includes("date") || lowerField.includes("time") || lowerField === "hiredate") {
        aVal = aVal ? new Date(aVal).getTime() : 0;
        bVal = bVal ? new Date(bVal).getTime() : 0;
      } else if (typeof aVal === "string" && typeof bVal === "string") {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (aVal == null) return 1;
      if (bVal == null) return -1;

      if (aVal < bVal) return sortOrder === "asc" ? -1 : 1;
      if (aVal > bVal) return sortOrder === "asc" ? 1 : -1;
      return 0;
    });
  }, [tableData, sortField, sortOrder]);

  const paginatedData = useMemo(() => {
    const startIdx = (currentPage - 1) * ITEMS_PER_PAGE;
    return sortedData.slice(startIdx, startIdx + ITEMS_PER_PAGE);
  }, [sortedData, currentPage]);

  const totalPages = Math.ceil(sortedData.length / ITEMS_PER_PAGE);
  const loadingSkeletonRows = useMemo(
    () =>
      Array.from({
        length: Math.min(ITEMS_PER_PAGE, 6),
      }),
    [ITEMS_PER_PAGE]
  );

  const getStatusColor = (status: string) => {
    const normalized = String(status || "").toLowerCase().replace(/\s+/g, "-");
    if (!mounted) {
      return {
        textColor: "text-emerald-500",
        dotColor: "bg-emerald-500",
      };
    }

    const statusMap: Record<string, { textColor: string; dotColor: string }> = {
      active: {
        textColor: isDark ? "text-emerald-400" : "text-emerald-600",
        dotColor: isDark ? "bg-emerald-400" : "bg-emerald-500",
      },
      inactive: {
        textColor: isDark ? "text-rose-400" : "text-rose-600",
        dotColor: isDark ? "bg-rose-400" : "bg-rose-500",
      },
      "on-leave": {
        textColor: isDark ? "text-amber-400" : "text-amber-600",
        dotColor: isDark ? "bg-amber-400" : "bg-amber-500",
      },
      onboarding: {
        textColor: isDark ? "text-sky-400" : "text-sky-600",
        dotColor: isDark ? "bg-sky-400" : "bg-sky-500",
      },
      pending: {
        textColor: isDark ? "text-amber-400" : "text-amber-600",
        dotColor: isDark ? "bg-amber-400" : "bg-amber-500",
      },
    };

    return (
      statusMap[normalized] || {
        textColor: isDark ? "text-slate-400" : "text-slate-600",
        dotColor: isDark ? "bg-slate-400" : "bg-slate-500",
      }
    );
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(amount || 0);
  };

  const formatDate = (dateString: string) => {
    if (!dateString) return "—";
    try {
      return new Date(dateString).toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    } catch {
      return String(dateString);
    }
  };

  const handleResize = (columnKey: string, { size }: { size: { width: number } }) => {
    const newDisplayW = Math.max(60, Math.min(500, size.width));
    // Compute current scale from base to map the drag delta back to intrinsic size
    const cbW = showCheckboxes ? (columnWidths.checkbox || 36) : 0;
    let baseSum = cbW;
    visibleTableColumns.forEach((c) => {
      baseSum += columnWidths[c.key] ?? c.defaultWidth ?? 105;
    });
    const curScale = (containerWidth > 0 && baseSum > 0) ? (containerWidth / baseSum) : 1;
    let newIntrinsic = newDisplayW;
    if (curScale > 1) {
      newIntrinsic = newDisplayW / curScale;
    }
    const clamped = Math.max(60, Math.min(500, newIntrinsic));
    setColumnWidths((prev) => {
      const next = {
        ...prev,
        [columnKey]: clamped,
      };
      // Persist the intrinsic (user's preferred) widths
      if (typeof window !== 'undefined') {
        try {
          localStorage.setItem(effectiveStorageKey, JSON.stringify(next));
        } catch {}
      }
      return next;
    });
    if (onColumnResize) {
      onColumnResize(columnKey, clamped);
    }
  };

  const getExportValue = (item: any, col: Column<any>) => {
    if (col.render) {
      // Best effort: use raw when render is custom
      const raw = item?.[col.key];
      return raw != null ? raw : "";
    }
    const v = item?.[col.key];
    if (v == null) return "";
    if (typeof v === "object") return JSON.stringify(v);
    return v;
  };

  const exportToCSV = () => {
    const headers = visibleTableColumns.map((c) => c.label);
    const rows = sortedData.map((item) =>
      visibleTableColumns.map((col) => {
        const cell = getExportValue(item, col);
        return `"${String(cell).replace(/"/g, '""')}"`;
      })
    );

    const csvContent = [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `${(title || "data").toLowerCase()}-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  };

  const exportToJSON = () => {
    const jsonContent = JSON.stringify(sortedData, null, 2);
    const blob = new Blob([jsonContent], { type: "application/json;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `${(title || "data").toLowerCase()}-${new Date().toISOString().split("T")[0]}.json`;
    link.click();
  };

  const shouldAnimate = enableAnimations && !shouldReduceMotion;

  const containerVariants = {
    visible: {
      transition: {
        staggerChildren: 0.03,
        delayChildren: 0.05,
      },
    },
  };

  const rowVariants = {
    hidden: { opacity: 0, y: 12, scale: 0.985, filter: "blur(3px)" },
    visible: {
      opacity: 1,
      y: 0,
      scale: 1,
      filter: "blur(0px)",
      transition: { type: "spring", stiffness: 420, damping: 26, mass: 0.65 },
    },
    exit: { opacity: 0, y: -8, transition: { duration: 0.15 } },
  };

  // Cell renderer helper
  const renderCell = (col: Column<any>, item: any, index: number) => {
    if (col.render) {
      return col.render(item);
    }
    const raw = item?.[col.key];
    const keyLower = col.key.toLowerCase();

    if (col.key === "status" || keyLower === "status" || keyLower.includes("status")) {
      const statusRaw = String(raw ?? "").trim();
      const { textColor, dotColor } = getStatusColor(statusRaw || "unknown");
      const display = (statusRaw || "Unknown")
        .replace(/[-_]/g, " ")
        .replace(/\b\w/g, (l) => l.toUpperCase());
      return (
        <span
          className={`inline-flex items-center gap-1.5 text-xs font-semibold whitespace-nowrap ${textColor}`}
          title={display}
        >
          <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${dotColor}`} />
          <span className="max-w-[9rem] truncate">{display}</span>
        </span>
      );
    }

    if (typeof raw === "number" && (keyLower.includes("amount") || keyLower.includes("pay") || keyLower.includes("price"))) {
      return <span className="font-semibold text-foreground/90 text-xs">{formatCurrency(raw)}</span>;
    }

    if (raw && (keyLower.includes("date") || keyLower.includes("time") || keyLower.includes("hired") || keyLower.includes("join"))) {
      return <span className="text-foreground/80 text-xs">{formatDate(String(raw))}</span>;
    }

    if (keyLower.includes("email") && raw) {
      return (
        <a
          href={`mailto:${raw}`}
          className="text-blue-500 hover:text-blue-600 truncate text-xs"
          onClick={(e) => e.stopPropagation()}
        >
          {raw}
        </a>
      );
    }

    return <span className="text-foreground/80 truncate text-xs">{raw != null ? String(raw) : "—"}</span>;
  };

  const sortableColumns = visibleTableColumns.filter((c) => c.sortable !== false);

  return (
    <div className={`w-full ${className}`}>
      <div className="mb-2 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
        <div className="flex items-center gap-2" />

        <div className="flex items-center gap-2 flex-wrap">
          {/* Sort */}
          <div className="relative">
            <button
              onClick={() => setShowSortMenu(!showSortMenu)}
              className="px-2 py-1 bg-background border border-border/50 text-foreground text-xs hover:bg-muted/30 transition-colors flex items-center gap-1.5 rounded-md"
            >
              <svg width="12" height="12" viewBox="0 0 16 16" fill="none">
                <path d="M3 6L6 3L9 6M6 3V13M13 10L10 13L7 10M10 13V3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
              Sort {sortField && <span className="ml-1 text-[8px] bg-primary text-primary-foreground rounded-sm px-1 py-0">1</span>}
              <ChevronDown size={12} className="opacity-50" />
            </button>

            {showSortMenu && (
              <>
                <div className="fixed inset-0 z-10" onClick={() => setShowSortMenu(false)} />
                <div className="absolute right-0 mt-1 w-40 bg-background border border-border/50 shadow-lg rounded-md z-20 py-0.5 max-h-72 overflow-auto text-xs">
                  <button
                    type="button"
                    onClick={clearSort}
                    className={`w-full px-2 py-1 text-left hover:bg-muted/50 transition-colors ${sortField === null ? "bg-muted/30" : ""}`}
                  >
                    Default view
                  </button>
                  {sortableColumns.length > 0 ? (
                    <>
                      <div className="my-0.5 border-t border-border/40" />
                      {sortableColumns.map((col) => (
                        <button
                          key={col.key}
                          type="button"
                          onClick={() => handleSort(col.key)}
                          className={`w-full px-2 py-1 text-left hover:bg-muted/50 transition-colors ${sortField === col.key ? "bg-muted/30" : ""}`}
                        >
                          {col.label} {sortField === col.key && `(${sortOrder === "asc" ? "↑" : "↓"})`}
                        </button>
                      ))}
                    </>
                  ) : (
                    <div className="px-2 py-1 text-muted-foreground">No sortable columns</div>
                  )}
                </div>
              </>
            )}
          </div>

          {/* Export */}
          {showExport ? (
            <div className="relative">
              <button
                onClick={() => setShowExportMenu(!showExportMenu)}
                className="px-2 py-1 bg-background border border-border/50 text-foreground text-xs hover:bg-muted/30 transition-colors flex items-center gap-1.5 rounded-md"
              >
                <Download size={12} />
                Export
                <ChevronDown size={12} className="opacity-50" />
              </button>

              {showExportMenu && (
                <>
                  <div className="fixed inset-0 z-10" onClick={() => setShowExportMenu(false)} />
                  <div className="absolute right-0 mt-1 w-28 bg-background border border-border/50 shadow-lg rounded-md z-20 text-xs">
                    <button
                      onClick={() => {
                        exportToCSV();
                        setShowExportMenu(false);
                      }}
                      className="w-full px-2 py-1 text-left hover:bg-muted/50 transition-colors"
                    >
                      CSV
                    </button>
                    <button
                      onClick={() => {
                        exportToJSON();
                        setShowExportMenu(false);
                      }}
                      className="w-full px-2 py-1 text-left hover:bg-muted/50 transition-colors border-t border-border/30"
                    >
                      JSON
                    </button>
                  </div>
                </>
              )}
            </div>
          ) : null}
        </div>
      </div>

      <div className="bg-background border border-border/50 overflow-hidden rounded-lg relative">
        <div className="overflow-x-auto" ref={overflowRef}>
          <div className="min-w-full align-top" style={{ minWidth: containerWidth ? `${containerWidth}px` : undefined }}>
            {/* Header */}
            <div className="flex py-1 text-base font-semibold text-muted-foreground/70 bg-muted/5 border-b border-border w-full">
              {showCheckboxes && (
                <div className="flex items-center justify-center border-r border-border pr-1.5 flex-shrink-0" style={{ width: getColumnWidth('checkbox') || 36 }}>
                  <input
                    type="checkbox"
                    className="w-4 h-4 rounded border-border/40 cursor-pointer"
                    style={mounted ? { accentColor: isDark ? "rgb(113, 113, 122)" : "rgb(161, 161, 170)" } : {}}
                    checked={paginatedData.length > 0 && selectedIds.length === paginatedData.length}
                    onChange={handleSelectAll}
                  />
                </div>
              )}

              {visibleTableColumns.map((col) => {
                const isActions = col.key === "actions" || col.key === "act"
                return (
                <Resizable
                  key={col.key}
                  width={getColumnWidth(col)}
                  height={0}
                  onResize={(e, data) => handleResize(col.key, data)}
                  minConstraints={[isActions ? 44 : 60, 0]}
                  maxConstraints={[isActions ? 280 : 500, 0]}
                  handle={<div className="absolute right-0 top-0 bottom-0 w-1 hover:w-1.5 cursor-col-resize bg-transparent hover:bg-primary/40 transition-all" />}
                >
                  <div
                    className={cn(
                      "relative flex flex-shrink-0 items-center border-r border-border px-1.5 text-base",
                      isActions ? "justify-end overflow-visible" : "overflow-hidden"
                    )}
                    style={{ width: getColumnWidth(col) }}
                  >
                    <span className="truncate">{col.label}</span>
                  </div>
                </Resizable>
                )
              })}
            </div>

            {/* Rows */}
            <AnimatePresence mode="wait">
              <motion.div
                key={`page-${currentPage}`}
                variants={(shouldAnimate ? containerVariants : undefined) as any}
                initial={shouldAnimate ? "hidden" : false}
                animate="visible"
              >
                {paginatedData.map((item, index) => {
                  const rowId = getRowIdentifier(item, index);
                  const isSelected = selectedIds.includes(rowId);

                  return (
                    <motion.div key={rowId} variants={(shouldAnimate ? rowVariants : undefined) as any}>
                      <div
                        className={`py-1 group relative transition-all duration-150 border-b border-border flex cursor-pointer w-full ${
                          isSelected ? "bg-muted/30" : "bg-muted/5 hover:bg-muted/20"
                        }`}
                        onClick={() => handleRowSelect(rowId, item)}
                      >
                        {/* Checkbox */}
                        {showCheckboxes && (
                          <div className="flex items-center justify-center border-r border-border pr-1.5 flex-shrink-0" style={{ width: getColumnWidth('checkbox') || 36 }}>
                            <input
                              type="checkbox"
                              className="w-4 h-4 rounded border-border/40 cursor-pointer"
                              style={mounted ? { accentColor: isDark ? "rgb(113, 113, 122)" : "rgb(161, 161, 170)" } : {}}
                              checked={isSelected}
                              onChange={(e) => {
                                e.stopPropagation();
                                handleRowSelect(rowId, item);
                              }}
                              onClick={(e) => e.stopPropagation()}
                            />
                          </div>
                        )}

                        {/* Data columns */}
                        {visibleTableColumns.map((col) => {
                          const isActions = col.key === "actions" || col.key === "act"
                          return (
                          <div
                            key={col.key}
                            className={cn(
                              "flex min-w-0 flex-shrink-0 items-center border-r border-border px-1.5 text-xs",
                              isActions
                                ? "justify-end overflow-visible"
                                : "overflow-hidden"
                            )}
                            style={{ width: getColumnWidth(col) }}
                            onClick={(e) => {
                              // allow inner links/buttons to work
                              if ((e.target as HTMLElement).closest("a,button,[data-slot='popover-trigger'],[data-slot='dropdown-menu-trigger']")) {
                                e.stopPropagation();
                              }
                            }}
                          >
                            {renderCell(col, item, index)}
                          </div>
                          )
                        })}
                      </div>
                    </motion.div>
                  );
                })}

                {loading && tableData.length === 0 ? (
                  <div className="border-b border-border">
                    {loadingSkeletonRows.map((_, index) => (
                      <div
                        key={`skeleton-row-${index}`}
                        className="flex w-full border-b border-border/60 px-1.5 py-2 last:border-b-0"
                      >
                        {allColumnKeys.map((columnKey) => (
                          <div
                            key={`${columnKey}-${index}`}
                            className="flex-shrink-0 px-1.5"
                            style={{ width: columnKey === "checkbox" ? getColumnWidth("checkbox") || 36 : getColumnWidth(columnKey) }}
                          >
                            <div className="h-4 animate-pulse rounded bg-muted/70" />
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                ) : paginatedData.length === 0 ? (
                  <div className="py-4 text-center text-xs text-muted-foreground border-b border-border">
                    No records found.
                  </div>
                ) : null}
              </motion.div>
            </AnimatePresence>
          </div>
        </div>
      </div>

      {totalPages > 1 && (
        <div className="mt-1 flex items-center justify-between px-1 text-xs">
          <div className="text-muted-foreground/70">
            Page {currentPage} of {totalPages} • {sortedData.length} {title.toLowerCase()}s
          </div>

          <div className="flex gap-1">
            <button
              onClick={() => setCurrentPage((prev) => Math.max(1, prev - 1))}
              disabled={currentPage === 1}
              className="px-1.5 py-0.5 bg-background border border-border/50 text-foreground hover:bg-muted/30 disabled:opacity-40 disabled:cursor-not-allowed transition-colors rounded text-xs"
            >
              Prev
            </button>
            <button
              onClick={() => setCurrentPage((prev) => Math.min(totalPages, prev + 1))}
              disabled={currentPage === totalPages}
              className="px-1.5 py-0.5 bg-background border border-border/50 text-foreground hover:bg-muted/30 disabled:opacity-40 disabled:cursor-not-allowed transition-colors rounded text-xs"
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
